(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["文化福祉"]=[{"id":"00013014","register_sub_id":"101","register_pk":"368327","name":"網走市立郷土博物館新館","kana":"あばしりしりつきょうどはくぶつかんしんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道網走市桂町一丁目1","lat":44.01776667,"lng":144.26910556,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造及び鉄筋コンクリート造地上2階地下1階建、金属板葺、建築面積138㎡","structure_material":"木造及び鉄筋コンクリート造地上2階地下1階建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0157","desc":"昭和11年に開館した郷土博物館の新館として本館東側に増築した。設計は本館同様田上義也による。木造2階建、地階付とし、矩形平面で屋根は片流れとする。立面は本館との連続性を考慮しつつ、壁面の切込などの彫塑的表現に、田上の戦後の作風を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013014"},{"id":"00013013","register_sub_id":"101","register_pk":"368326","name":"網走市立郷土博物館本館","kana":"あばしりしりつきょうどはくぶつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道網走市桂町一丁目1","lat":44.01774167,"lng":144.26888611,"geo_status":"db","era":"昭和11年／昭和60年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、金属板葺、建築面積197㎡、塔屋付","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0156","desc":"市街南部の丘陵に南面して建つ、道内最初期の郷土博物館。塔屋付木造二階建、左右対称平面の中央を南北に張出し、正面にアーチをみせる。外壁は鉄網コンクリート塗、胴部は左官仕上で幾何学模様のパネルを貼る。建築家田上義也による独創的な意匠の文化施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013013"},{"id":"00002109","register_sub_id":"101","register_pk":"103099","name":"函館中華会館","kana":"はこだてちゅうかかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市大町1-20","lat":41.76806457,"lng":140.709457,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積374㎡","structure_material":"煉瓦造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"01 － 0028","desc":"関帝を祀る主棟と，左右前方に延びた翼廊，これを閉じる正面玄関棟からなる。日本に現存する唯一の関帝廟形式の集会所で，内部は華麗で爛熟した清朝末期の雰囲気を持つ。明治４０年の函館大火後に建てられた煉瓦造建築で，地域の景観のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002109"},{"id":"00014704","register_sub_id":"101","register_pk":"518962","name":"ヒノキ新薬株式会社ルスツ山寮","kana":"ひのきしんやくかぶしきかいしゃるすつさんりょう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"北海道","address":"北海道虻田郡留寿都村字泉川645他","lat":42.75938333,"lng":140.92279722,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、鉄板葺、建築面積812㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"01 - 0169","desc":"尻別岳山麓に位置する企業の保養所。設計は白井晟一。長大な二階建に緩勾配の切妻造屋根を架け、外壁に濃淡に富む煉瓦積・石積を用いた独特な外観。内部吹抜には、片持で薄く仕上げた踊場付階段など要所に彫塑的造形を配す。白井による北海道唯一の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014704"},{"id":"00010714","register_sub_id":"101","register_pk":"201549","name":"北海道護国神社平成館（旧陸軍第七師団北鎮兵事記念館）","kana":"ほっかいどうごこくじんじゃへいせいかん（きゅうりくぐんだいしちしだんほくちんへいじきねんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道旭川市花咲町一丁目3853他","lat":43.786841,"lng":142.366389,"geo_status":"db","era":"昭和10／平成2改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階地下１階建、鉄板葺、建築面積360㎡","structure_material":"鉄筋コンクリート造平屋一部2階地下１階建","registered":"2015.11.17(平成27.11.17)","register_no":"01 ‐ 0145","desc":"神社境内の南東に建つ、鉄筋コンクリート造一部二階地下一階建。中央部の正背面を張出し、切妻造の屋根も中央を高めて強調する。屋根の大棟や降棟に鬼を置き、破風に懸魚を飾る。白壁の腰を石張として城郭風に見せるなど、当時の日本趣味意匠の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010714"},{"id":"00014219","register_sub_id":"101","register_pk":"509609","name":"北海道大学空沼小屋","kana":"ほっかいどうだいがくそらぬまこや","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道札幌市南区常盤石狩森林管理署1157イ林小班","lat":42.88033611,"lng":141.26025278,"geo_status":"db","era":"昭和3年／平成28年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積56㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"01 - 0162","desc":"空沼岳の万計沼畔に所在する山小屋で、秩父宮雍仁親王の発意により、スイス人建築家ヒンデルが設計した。丸太組構法二階建、小規模ながら機能的な設計で最大30名宿泊可能。金具意匠、木柄太さ、ストーブ廻りの吹抜等、スイスの良質な山小屋を思わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014219"},{"id":"00008803","register_sub_id":"101","register_pk":"162246","name":"夕張鹿鳴館(旧北炭鹿ノ谷倶楽部)","kana":"ゆうばりろくめいかん（きゅうほくたんしかのたにくらぶ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道夕張市鹿の谷2-4-1","lat":43.03707729,"lng":141.96024781,"geo_status":"db","era":"大正2年／大正5年増築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1609㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"01 － 0112","desc":"北面して玄関を構える木造平屋建で、建築面積1609㎡に及ぶ。中央に本館、西に第一別館、東に第二別館を配し、廊下で繋ぐ。本館は諸室を雁行型に配し、寄棟や切妻の屋根を複雑に連続させ、下屋庇をまわし、深い陰影を見せる。倶楽部建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008803"},{"id":"00005729","register_sub_id":"101","register_pk":"106717","name":"岩手県公会堂","kana":"いわてけんこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市内丸11-2","lat":39.70316799,"lng":141.15348399,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積1580㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"03 － 0061","desc":"敷地中央にほぼ南面して建つ。間口４４ｍ，奥行４８ｍの規模で，ＲＣ造２階建，陸屋根とする。玄関奥を階段室，その奥を中庭とし，後部に大ホールを置く。中央に６層の塔屋を設け，外壁をスクラッチタイル貼とし，外部に柱形を現して垂直性を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005729"},{"id":"00011434","register_sub_id":"101","register_pk":"210405","name":"旧遠野寶物館（遠野市立博物館新町収蔵庫）","kana":"きゅうとおのほうもつかん（とおのしりつはくぶつかんしんまちしゅうぞうこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県遠野市新町230-2","lat":39.32901,"lng":141.526599,"geo_status":"db","era":"大正14年／昭和24年・同55年頃改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積96㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"03-0088","desc":"遠野市街地の中心に建つ。耐震耐火を考慮し、鉄筋コンクリート造とする。外壁は、窓廻りを窪ませるなどの幾何学的意匠が特徴で、内部は一、二階とも一室で、側柱のみで支える無柱の大空間とする。遠野地方における最初の鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011434"},{"id":"00013017","register_sub_id":"101","register_pk":"368224","name":"後藤伯記念公民館","kana":"ごとうはくきねんこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢大手町四丁目1","lat":39.14486944,"lng":141.14016389,"geo_status":"db","era":"昭和16年／昭和32年増築、同62年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積947㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"03 － 0110","desc":"水沢の旧城下中心部にある公民館。敷地西辺に南北棟で建つ本館と、南東側の柔剣道場を逆Ｌ字形の建物で繋ぐ。本館南寄りを大きな切妻屋根として妻壁をハーフティンバー風に飾り、前面に切妻屋根の車寄を突出する。大小の切妻屋根が重層した風格あるつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013017"},{"id":"00013910","register_sub_id":"101","register_pk":"508170","name":"齋藤子爵水沢文庫図書閲覧所","kana":"さいとうししゃくみずさわぶんことしょえつらんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢字吉小路24イ","lat":39.14429167,"lng":141.13471111,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"03 - 0112","desc":"図書庫の東に渡廊下で隣接する木造平屋建桟瓦葺、水回りなど自邸としての設備も有する閲覧所。寄棟造の屋根を雁行に重ね、南西に入母屋造玄関が付く。内部は洋間のほか、続き間座敷の南にガラス窓を連ねる閲覧室を設け、郷土の子弟への供用を目的とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013910"},{"id":"00013909","register_sub_id":"101","register_pk":"508169","name":"齋藤子爵水沢文庫図書庫","kana":"さいとうししゃくみずさわぶんことしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢字吉小路24イ","lat":39.14485,"lng":141.13464722,"geo_status":"db","era":"昭和7年／同10年増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積102㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"03 - 0111","desc":"第三〇代総理大臣斎藤實が水沢城下生家跡に建てた私設図書館。鉄骨鉄筋コンクリート造二階建、陸屋根、外壁をイギリス積風煉瓦張、腰は石貼。内部は一階入口に受付カウンターを配し、他は書庫で階段手摺や金具に真鍮を用いる。海軍技師の設計による建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013909"},{"id":"00009257","register_sub_id":"101","register_pk":"194050","name":"旧相川診療所","kana":"きゅうあいかわしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"宮城県","address":"宮城県石巻市北上町十三浜字崎山152-3","lat":38.60727696,"lng":141.50077518,"geo_status":"db","era":"昭和36年／平成23年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋一部2階建、スレート葺、建築面積166㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"04 － 0088","desc":"石巻市北東端の相川集落内に建つ。木造平屋建の診療所と同二階建の休憩所をＬ形に接続する。外壁は下見板張で診療所はペンキ塗とし、屋根は両者とも切妻造スレート葺である。病院のへき地出張所としての形態を伝えるとともに、スレート葺が地域的特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009257"},{"id":"00013922","register_sub_id":"101","register_pk":"508182","name":"竹駒神社馬事博物館","kana":"たけこまじんじゃばじはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県岩沼市稲荷町4-1","lat":38.10478056,"lng":140.86393056,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0210","desc":"竹駒神社境内に位置。基礎及び床を鉄筋コンクリート造、上部を木造とした平屋建寄棟造銅板葺。切妻造の車寄玄関を付し、鴟尾、懸魚、蟇股等、和風の細部意匠を持つ。展示室は壁及び天井を漆喰塗、腰をタイル貼とする。日本趣味が横溢する馬専門博物館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013922"},{"id":"00016478","register_sub_id":"101","register_pk":"574840","name":"大潟村公民館","kana":"おおがたむらこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"秋田県","address":"秋田県南秋田郡大潟村字中央1-21","lat":40.01771111,"lng":139.95990806,"geo_status":"db","era":"昭和44年","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造2階一部6階建、建築面積645㎡","structure_material":"鉄筋コンクリート造2階一部6階建","registered":"2026.02.10(令和8.02.10)","register_no":"05 - 0261","desc":"大潟村の中心部に位置する公民館。鉄筋コンクリート造２階建切妻造の東西棟で、西側の６階建展望塔と渡廊下で接続する。内部は中廊下の南北に大小の集会室を配し、中央階段の上部に天窓を開ける。計画都市の軸線上に建つ公民館で、地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016478"},{"id":"00012092","register_sub_id":"101","register_pk":"352891","name":"旧大倉沢報徳館","kana":"きゅうおおくらざわほうとくかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市大倉沢字大沢16-2","lat":39.437378,"lng":140.143784,"geo_status":"db","era":"昭和5年頃／平成15年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"05-217","desc":"木造平屋建、寄棟造桟瓦葺で、内部は鴨居上を高く取り、平面は玄関奥の廊下を矩折れに延ばし、大広間四二畳、応接室八畳、小会議所一二畳等を配す。細部に洋風意匠を配し、外壁は下見板張に窓上モルタル搔き落しとする。報徳社の支社社屋の数少ない遺存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012092"},{"id":"00007835","register_sub_id":"101","register_pk":"108816","name":"旧杏華堂石田医院座敷蔵","kana":"きゅうきょうかどういしだいいんざしきぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字上町56他","lat":39.20155204,"lng":140.54621337,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0170","desc":"敷地のほぼ中央に建つ。南北棟の切妻造鉄板葺、桁行９．１ｍ梁間５．５ｍ、土蔵造２階建。北妻に入口を穿ち、掛子塗四段の両開扉を吊る。内部仕上げや座敷飾りなどに伝統を踏襲しつつ、キングポストトラス組や階段高欄等に新たな技法や洋風の意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007835"},{"id":"00003346","register_sub_id":"101","register_pk":"104336","name":"旧小坂鉱山病院記念棟","kana":"きゅうこさかこうざんびょういんきねんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角郡小坂町小坂鉱山字古舘48-2","lat":40.3284678,"lng":140.74471737,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0093","desc":"旧小坂鉱山病院の霊安施設。西正面中央部に出入口を開き，２間四方の霊安室を取り，その北に踏込土間を備えた３畳敷の和室を配する。出入口にはペディメント付きのポーチを備え，各上げ下げ窓には繊細な蛇腹の庇を付けるなど，小規模ながら瀟洒な意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003346"},{"id":"00003345","register_sub_id":"101","register_pk":"104335","name":"天使館（旧聖園マリア園）","kana":"てんしかん（きゅうせいえんまりあえん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県鹿角郡小坂町小坂鉱山字古舘35-6","lat":40.3285642,"lng":140.74354433,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積372㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0092","desc":"小坂鉱山従業員のための幼児教育施設。木造平屋建で，町の中心を南北に通る町道に東面して建つ。ドイツ下見の外壁（西背面のみイギリス下見），縦長の上げ下げ窓，玄関ポーチの柱型やペディメント，大屋根端部やポーチ上部の棟飾等，平明な洋風の意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003345"},{"id":"00009894","register_sub_id":"101","register_pk":"196041","name":"朝日座","kana":"あさひざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県南相馬市原町区大町1-120","lat":37.63901969,"lng":140.96060271,"geo_status":"db","era":"大正12／昭和30頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積508㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"07 － 0149","desc":"通り沿いの敷地奥に西面して建つ映画館。木造二階建、外壁モルタル塗で、正面にはコーニス上にペディメントとフィニアルを飾る。内部には芝居小屋当時の桟敷席などを残す。地域の娯楽の殿堂として長く親しまれ、芝居小屋から映画館へ至る改修の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009894"},{"id":"00006290","register_sub_id":"101","register_pk":"107273","name":"旧大越娯楽場","kana":"きゅうおおごえごらくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県田村市大越町上大越字町1","lat":37.38306,"lng":140.630569,"geo_status":"db","era":"大正15／昭和30頃改造","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積466㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"07 － 0082","desc":"集落内の交差点に建つ。建築面積４６６㎡，木造２階建，鉄板葺。正面を入母屋形式として両側に塔屋を建てる芝居小屋風の構成とするが，外壁をモルタル塗として軒下にはデンティルを現し，窓上部を鎧戸風にして洋風の外観を呈する。村民のための娯楽施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006290"},{"id":"00014229","register_sub_id":"101","register_pk":"509619","name":"旧三宮堂田中医院診療所","kana":"きゅうさんのみやどうたなかいいんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県双葉郡双葉町大字長塚字町12","lat":37.45380833,"lng":141.00775,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"07 - 0272","desc":"双葉駅前の旧陸前浜街道沿いに所在する木造洋風医院建築。寄棟造、正面切妻破風、外壁モルタル掻落し、玄関ポーチを付して飾る。側背面は下見板張とする。一階は診療室など病院機能の諸室、二階は床付座敷と洋室を配す。町の象徴的な建物として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014229"},{"id":"00014230","register_sub_id":"101","register_pk":"509620","name":"旧三宮堂田中医院煉瓦蔵","kana":"きゅうさんのみやどうたなかいいんれんがぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県双葉郡双葉町大字長塚字町12","lat":37.45366944,"lng":141.00804167,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積19㎡","structure_material":"煉瓦造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"07 - 0273","desc":"診療所の背面側に建つ煉瓦造の小規模な倉庫。平屋建切妻造桟瓦葺妻入で、西面に入口を設けて鉄扉・格子戸を建て、掛庇を付して幾何学模様の持送金物で受ける。小屋は木造和小屋。壁はイギリス積で頂部に軒蛇腹を廻す。診療所とともに町の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014230"},{"id":"00002741","register_sub_id":"101","register_pk":"103731","name":"郡山市公会堂","kana":"こおりやましこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県郡山市麓山1-8-4","lat":37.394417,"lng":140.372284,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積1102㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0064","desc":"郡山市制施行を記念して市中心部に建てられた。連続半円アーチの柱廊と，窓台受，上げ下げ連窓などを丁寧にデザインした躯体の隅に，縦長ガラス面で垂直性を強調した塔屋を設ける。開拓の意気込みを壮麗に表現した本格的様式建築。設計は矢橋賢吉と荻原貞雄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002741"},{"id":"00013031","register_sub_id":"101","register_pk":"368341","name":"仙峡閣","kana":"せんきょうかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市大戸町大字上小塩字遅谷3084-3","lat":37.36436111,"lng":139.91824722,"geo_status":"db","era":"昭和13年／昭和30年移築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、金属板葺、建築面積605㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0224","desc":"会津若松市南郊の芦ノ牧温泉にある、もと武徳殿を転用した温泉旅館。渓谷沿いの斜面に建ち、入母屋造の大屋根に千鳥破風を飾り、正面に構える雄大な車寄に社寺建築の細部意匠を採用し、武徳殿の定型をよく示す。大胆な転用の経緯と勇壮な外観をもつ旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013031"},{"id":"00008804","register_sub_id":"101","register_pk":"162247","name":"蟹仙洞展示館","kana":"かいせんどうてんじかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県上山市矢来4-299-7他","lat":38.14944561,"lng":140.27889121,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造一部木造2階建、スレート葺一部鉄板葺、建築面積154㎡","structure_material":"鉄筋コンクリート造一部木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0122","desc":"敷地北西隅に建つ。北側に、鉄筋コンクリート造2階建切妻造桟瓦葺の主棟を配し、主屋との間に木造一部2階建の附属棟を建てて両者を接続する。建築面積174㎡である。主棟は伝統的な土蔵の外観を踏襲し、附属棟は急勾配の切妻屋根が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008804"},{"id":"00000330","register_sub_id":"101","register_pk":"101320","name":"掬粹巧芸館日本館","kana":"きくすいこうげいかんにほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2908、2909、2910-3","lat":38.01364594,"lng":140.05098713,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造・土蔵造2階建塔屋付，建築面積109㎡","structure_material":"石造・土蔵造2階建塔屋付","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0018","desc":"隣接する高畠町で産出する高畠石による石造建築。かつては川西町内に多数存在したが，現存するものは少ない。１階正面はアーチで外部空間を取り込んでいる。内部はタイルを多用した洋風のアプローチと，純和風の座敷からなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000330"},{"id":"00000329","register_sub_id":"101","register_pk":"101319","name":"掬粹巧芸館本館","kana":"きくすいこうげいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2911-5、6、8、9","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造平屋建，鉄板葺，建築面積70㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0017","desc":"樽平酒造当主井上家の十代目が設立した陶磁器美術館とするための建築である。土蔵造平屋建で，ほぼ正方形の平面を持つ。壁面には高窓を配し，正面は左右対称の構成としている。当初より展示を主目的とした建築としては最初期の例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000329"},{"id":"00014134","register_sub_id":"101","register_pk":"508764","name":"旧梅津歯科医院裏門及び黒板塀","kana":"きゅううめつしかいいんうらもんおよびくろいたべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15591667,"lng":140.276275,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、鉄板葺、間口1.9m 塀 木造、鉄板葺、総延長19m","structure_material":"門 木造","registered":"2022.02.17(令和4.02.17)","register_no":"06-0202","desc":"旧城下町の医家の裏門と板塀で、穀物蔵に連なり敷地背面側の外郭となる。裏門は切妻造鉄板葺、疎垂木の腕木門で、棟に鬼板を飾り、腕木に繰形を施し、引違板戸を建てる。板塀は竪板張で、鉄板葺の小屋根を備える。城下の小路の良好な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014134"},{"id":"00014132","register_sub_id":"101","register_pk":"508762","name":"旧梅津歯科医院穀物蔵","kana":"きゅううめつしかいいんこくもつぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15581667,"lng":140.27625556,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、鉄板葺、建築面積42㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0200","desc":"旧城下町の医家の土蔵で、裏門に連なり敷地背面側の外郭となる。二階建、切妻造鉄板葺平入、漆喰仕上鉢巻付、一階土間は一部を仕切り、二階は板敷とする。戸口に掛子塗の扉、窓に鉄扉を備え、いずれも鳥居枠を豪壮に塗上げ、城下小路の景観を整える穀物蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014132"},{"id":"00014131","register_sub_id":"101","register_pk":"508761","name":"旧梅津歯科医院座敷蔵","kana":"きゅううめつしかいいんざしきぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15588611,"lng":140.27646389,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0199","desc":"旧城下町の医家の土蔵。二階建、切妻造鉄板葺平入、漆喰仕上鉢巻付、池庭に面する蔵前は縁を通してガラス戸を建てる。戸口と窓に掛子塗扉を備え、一階は仏間と床付座敷の続き座敷で、二階は物置。牛梁とこれを支える曲梁は太く、雪国らしい豪壮な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014131"},{"id":"00014130","register_sub_id":"101","register_pk":"508760","name":"旧梅津歯科医院住居棟","kana":"きゅううめつしかいいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市十日町941","lat":38.15569722,"lng":140.27652222,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0198","desc":"旧城下町の医家の住居棟和館。診療棟洋館の西側に接続し、二階建、入母屋造鉄板葺で鬼板を棟に飾る。一階は南面する玄関、日常的な用途の続き座敷、台所からなる。二階は格天井の続き座敷で、眺望の効く開放的な造りとし、座敷蔵と好対照な接客空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014130"},{"id":"00014129","register_sub_id":"101","register_pk":"508759","name":"旧梅津歯科医院診療棟","kana":"きゅううめつしかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市十日町941","lat":38.15575,"lng":140.27665,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積76㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0197","desc":"旧城下町の医家の診療棟洋館。敷地中央東寄りに南面し、二階建、入母屋造鉄板葺フィニアル付、ペディメント風のポーチを突出する。一階に薬局、二階に診察室と技工室を配す。各階の待合等は畳敷だが、天井中心飾りや階段手摺等、全体に洋風意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014129"},{"id":"00014133","register_sub_id":"101","register_pk":"508763","name":"旧梅津歯科医院味噌蔵","kana":"きゅううめつしかいいんみそぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15574444,"lng":140.27634444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0201","desc":"旧城下町の医家の土蔵で、主屋背面側の敷地西辺に位置する。平屋建、切妻造鉄板葺平入、漆喰仕上で腰はモルタル仕上。和小屋で、内部は引違戸で南北二室に仕切り、北側は床を張り、高窓を設ける。戸口と窓には土戸を備える。屋敷後方の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014133"},{"id":"00000560","register_sub_id":"101","register_pk":"101550","name":"舞鶴橋","kana":"まいづるばし","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市丸の内1-4-13","lat":37.90889611,"lng":140.10592594,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"石造アーチ橋，橋長５m，幅員７m","structure_material":"石造アーチ橋","registered":"1998.07.23(平成10.07.23)","register_no":"06 － 0028","desc":"米沢城祉の堀に架かる石造橋で，現在は上杉神社への参道となっている。径間に比して幅員が広く，凝灰岩の欄干を設け親柱に自然石の奇岩を配するのが特徴。単アーチ橋ではあるが，「めがね橋」の愛称で米沢市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000560"},{"id":"00003784","register_sub_id":"101","register_pk":"104774","name":"旧大谷公会堂","kana":"きゅうおおやこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市大谷町1271-2","lat":36.59408889,"lng":139.81772222,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造平屋建、スレート葺、建築面積209㎡","structure_material":"石造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0087","desc":"地元産大谷石を構造躯体に用いた公会堂建築。正面１０ｍ，奥行２２ｍ規模，客席部は切妻造で，小屋組はキングポストトラスとし，正面に軒上まで立ち上げた４本の装飾的付柱が特徴的なファサードをつくる。設計は，県内建築事務所の草分的存在である更田時蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003784"},{"id":"00008638","register_sub_id":"101","register_pk":"149359","name":"駒橋歯科医院診療所","kana":"こまはししかいいんしんりょうしょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県鹿沼市今宮町字西中町1608-2","lat":36.564672,"lng":139.7453385,"geo_status":"db","era":"大正後期／昭和40年頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0192","desc":"神社への参道に西面する。木造2階建、1階に診療室、2階に客間などを配する。切妻造桟瓦葺で、正面左右に切妻造の棟を突き出す。下見板張で矩形窓を大きく開け、西・南面には幾何学模様を飾る。ハーフティンバー風仕上げの妻壁が並び、町並みに潤いを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008638"},{"id":"00013947","register_sub_id":"101","register_pk":"508207","name":"山縣有朋記念館別館","kana":"やまがたありともきねんかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県矢板市上伊佐野字一本木1022-344","lat":36.88725556,"lng":139.880275,"geo_status":"db","era":"昭和2年頃／平成元年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"09 - 0264","desc":"山縣有朋が拓いた農場に所在。二階建寄棟造桟瓦葺で南正面にドーマー窓を掲げる。パーゴラ付ポーチを設け、上下窓や両開窓を開ける。内部のリビングは出窓や暖炉を備え、壁は腰を木羽目板とし、天井は梁形を表す格式備えた洋室。広大な農場に建つ瀟洒な洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013947"},{"id":"00000123","register_sub_id":"101","register_pk":"101113","name":"桐生織物会館旧館","kana":"きりゅうおりものかいかんきゅうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町1184-4","lat":36.41292856,"lng":139.33668554,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建，瓦葺，建築面積833㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"10 － 0006","desc":"桐生織物協同組合の事務所として建築された木造２階の建物で，設計は群馬県土木課営繕係。外壁をスクラッチタイル張りとし，屋根は静緑色の瓦を葺くなど洋風の装いになる。整然とした配置の窓やなど，昭和期における生産管理関係の事務所の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000123"},{"id":"00007181","register_sub_id":"101","register_pk":"108163","name":"富岡市社会教育館玄関及び事務室棟","kana":"とみおかししゃかいきょういくかんげんかんおよびじむしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.255272,"lng":138.859726,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0260","desc":"高台に占める敷地のほぼ中央に南面して建つ。軒先を鉄板葺とする桟瓦葺の寄棟造で、東寄りに切妻造妻入の車寄、西寄りに二ノ口玄関を設ける。内部は北面に廊下、南側に事務室や館長室などを配する。車寄の緩やかな勾配の直線的な屋根が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007181"},{"id":"00007182","register_sub_id":"101","register_pk":"108164","name":"富岡市社会教育館講師室棟","kana":"とみおかししゃかいきょういくかんこうししつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.2553931,"lng":138.85982903,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0261","desc":"玄関及び事務室棟の東北に雁行型に取り付く。軒鉄板葺の寄棟造桟瓦葺で、東西棟とする。十五畳の主室と十畳の次の間を東西に並べ、畳敷と榑縁からなる縁を四周にまわす。主室のトコや棚、付書院からなる座敷構えや室境の欄間など、秀逸な意匠でまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007182"},{"id":"00007180","register_sub_id":"101","register_pk":"108162","name":"富岡市社会教育館講堂棟","kana":"とみおかししゃかいきょういくかんこうどうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.255508,"lng":138.860275,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積314㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0259","desc":"南面する入母屋造妻入で、正面に切妻造妻入玄関を付ける。屋根は桟瓦葺で、軒先を鉄板葺とする。内部は六十畳の講堂を中心に正・側面に広縁、背面に演壇等を設け、旧神殿を突出し、西面に渡廊下を付設。大きな入母屋破風と切妻屋根が威厳ある正面意匠をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007180"},{"id":"00007184","register_sub_id":"101","register_pk":"108166","name":"富岡市社会教育館正門","kana":"とみおかししゃかいきょういくかんせいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.25496217,"lng":138.85970221,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺一部鉄板葺、間口3.6m、袖塀及び潜り付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0263","desc":"車寄の西南方に位置する一間薬医門で、袖塀と潜りを付設。間口３．６ｍと規模が大きい。屋根は切妻造で、軒先に鉄板をまわす桟瓦葺とする。主柱上に冠木と男梁を架し、男梁上に束で棟木を支持する。軒は一軒疎垂木。軸太で簡明な意匠にまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007184"},{"id":"00007183","register_sub_id":"101","register_pk":"108165","name":"富岡市社会教育館和室棟","kana":"とみおかししゃかいきょういくかんわしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.25513024,"lng":138.85934082,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積498㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0262","desc":"玄関及び事務室棟の西南に位置する。北面に廊下を通し、三六畳の談話室と和室３室を１列に並べ、西側に食堂や厨房、便所などを付設。東西棟の寄棟造を主棟とし、東端には南北棟の入母屋造を直角に設け、西には寄棟造屋根を段違いに出し、見応えある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007183"},{"id":"00007003","register_sub_id":"101","register_pk":"107985","name":"日本基督教団島村教会島村めぐみ保育園本館","kana":"にほんきりすときょうだんしまむらきょうかいしまむらめぐみほいくえんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県伊勢崎市境島村2509-2","lat":36.244926,"lng":139.245636,"geo_status":"db","era":"昭和25／昭和28改修・昭和29増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"10 － 0258","desc":"島村教会敷地から交差点を挟んで斜め向かいの敷地に建つ。北を正面とした東西棟で、屋根は切妻造瓦葺とし、北面の中央に緩勾配の寄棟屋根の玄関、東寄りの下屋を便所とする。外壁は下見板張で、妻壁上部を漆喰塗としており、本館に倣った意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007003"},{"id":"00015287","register_sub_id":"101","register_pk":"532411","name":"廣池千九郎大穴記念館偲ぶの湯（旧洞窟温泉）","kana":"ひろいけちくろう おおあなきねんかんしのぶのゆ（きゅうどうくつおんせん）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町大穴字髙平735-1","lat":36.79096111,"lng":138.98069167,"geo_status":"db","era":"昭和12年／平成15年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"コンクリート造、延長7.0m","structure_material":"コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0361","desc":"大穴温泉に位置する入浴施設。南面する崖面から湧き出す温泉の源を求め、岩盤を掘り広げ、素掘のヴォールト状トンネル奥に浴槽を配し、源泉の湧出口やトンネル入口の廻りをコンクリートで補強。廣池千九郎が晩年療養した温泉で、岩窟内にある独特な入浴施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015287"},{"id":"00015288","register_sub_id":"101","register_pk":"532412","name":"廣池千九郎大穴記念館脱衣場","kana":"ひろいけちくろう おおあなきねんかんだついば","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町大穴字髙平735-1","lat":36.790875,"lng":138.98071389,"geo_status":"db","era":"昭和12年／平成15年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0362","desc":"旧洞窟温泉の入口南にある脱衣場。高いコンクリート基礎に建つ平屋建切妻造で、屋根は杉皮葺の上に杉皮葺を重ね、外壁は杉皮張仕上。内部は二室で上部にキングポスト・トラスを現す。地元の杉材を多用した独特な外観で、廣池千九郎が臨終した記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015288"},{"id":"00015286","register_sub_id":"101","register_pk":"532410","name":"廣池千九郎谷川記念館神壇","kana":"ひろいけちくろう たにがわきねんかんしんだん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町谷川字上原557-1他","lat":36.79057222,"lng":138.95266944,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0360","desc":"主屋の北に南面して建つ天照皇大神を祀る神殿。切妻造平入で屋根は割竹押縁の杉皮葺とし、外壁は杉皮張仕上。正面と側面の正面寄りに板戸を建て、内部は一室で幅一杯の上壇を構え祭壇とする。天井は割竹竿縁の杉皮張。地元杉材を多用した独特な外観の小社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015286"},{"id":"00015285","register_sub_id":"101","register_pk":"532409","name":"廣池千九郎谷川記念館麗澤館（旧主屋及び旧浴場）","kana":"ひろいけちくろう たにがわきねんかんれいたくかん（きゅうおもやおよびきゅうよくじょう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町谷川字上原557-1他","lat":36.79043889,"lng":138.95274167,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0359","desc":"谷川温泉の木立の中に建つ旧療養施設。平屋建切妻造の主屋で東に浴場を接続。屋根は杉皮葺の上に杉皮葺の屋根を重ねる。内部は一二・五畳と七・五畳の続き間座敷とし、西面に床を構え、天井は割竹押縁の杉皮張とする。地元の杉材を多用した特異な外観の施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015285"},{"id":"00013508","register_sub_id":"101","register_pk":"504872","name":"旧壺春堂醫院主屋","kana":"きゅうこしゅんどういいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県秩父郡皆野町大字皆野字原1169-1他","lat":36.070775,"lng":139.09615278,"geo_status":"db","era":"江戸末期／明治前期増改築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積160㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"11 － 0198","desc":"金子兜太の父で俳人・医師の金子元春の住宅兼医院。南北棟の二階建切妻造で南妻が旧街道に面する。両妻に土台を入れ小屋を折置とした整形四間取の主屋に京呂組の客間を増築。客間座敷に兜太の書を飾る等、著名な俳人の生家として文学史上も価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013508"},{"id":"00013509","register_sub_id":"101","register_pk":"504873","name":"旧壺春堂醫院土蔵","kana":"きゅうこしゅんどういいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父郡皆野町大字皆野字原1168-1","lat":36.07098889,"lng":139.09586111,"geo_status":"db","era":"昭和9年／昭和38年移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"11 － 0199","desc":"敷地北西寄りに西面して建つ。南北棟で二階建切妻造桟瓦葺。戸口は四段の掛子塗観音扉とし二階両妻にも三段掛子塗の窓を開ける。北妻に扇の鏝絵を飾る。内部は漆喰仕上で医療機器や家財等を収納した。主屋とともに地域の文化交流施設として景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013509"},{"id":"00005256","register_sub_id":"101","register_pk":"106244","name":"近藤歯科医院","kana":"こんどうしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1026-6","lat":35.99523742,"lng":139.08300728,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積83㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0094","desc":"２階建の医院棟を核とし，平屋建の住居棟が接続し，全体はＬ字型の形態になる。通り側の外観はハーフティンバー風の真壁造で，壁をドイツ壁風に仕上げ，屋根は桟瓦葺とする。内部は医院棟を洋風とし，住居棟を和風とする。和洋の特徴を兼備した個人病院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005256"},{"id":"00004211","register_sub_id":"101","register_pk":"105201","name":"坂田医院旧診療所","kana":"さかたいいんきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県熊谷市妻沼1420","lat":36.222523,"lng":139.377441,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積217㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0084","desc":"鉄筋コンクリート造，陸屋根造平屋建の産科医院診療棟。東面北寄りに車寄を突出させ，南北に調剤室・待合室・診察室・分娩室等を並べ，西側にレントゲン室等を配する。正側面はスクラッチタイル張とし，軒部にタイル張技法による歯飾状の装飾帯を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004211"},{"id":"00012876","register_sub_id":"101","register_pk":"367984","name":"栃谷八坂神社舞台","kana":"とちややさかじんじゃぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県秩父市栃谷字島府402-2","lat":36.02732222,"lng":139.11931944,"geo_status":"db","era":"明治32年／昭和25年頃・平成26年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"11 － 190","desc":"秩父盆地北部の神社にある地芝居舞台で、境内西側の広場に東面して建つ。寄棟造桟瓦葺の平屋建、正面は出桁造とし、差物を通して開放する。舞台は前二間を表、奧三間を裏とし、裏には可動式の二重舞台を備える。秩父地方の神社附設舞台の希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012876"},{"id":"00007004","register_sub_id":"101","register_pk":"107986","name":"日本基督教団島村教会島村めぐみ保育園別館","kana":"にほんきりすときょうだんしまむらきょうかいしまむらめぐみほいくえんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県深谷市横瀬字聖天68-1","lat":36.24478328,"lng":139.24592072,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"11 － 0119","desc":"島村教会敷地から交差点を挟んで斜め向かいの敷地に建つ。北を正面とした東西棟で、屋根は切妻造瓦葺とし、北面の中央に緩勾配の寄棟屋根の玄関、東寄りの下屋を便所とする。外壁は下見板張で、妻壁上部を漆喰塗としており、本館に倣った意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007004"},{"id":"00014453","register_sub_id":"101","register_pk":"512437","name":"本多流洗心洞（髙木道場）弓道場","kana":"ほんだりゅうせんしんどう（たかぎどうじょう）きゅうどうじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県久喜市下清久字鶴ノ谷395-11","lat":36.07516667,"lng":139.64840278,"geo_status":"db","era":"昭和7年頃／平成23年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"11 - 0219","desc":"旧清久村の旧家に所在する弓道場。切妻造で天井の高い板敷の射場を中心に、下屋で西に床構え付畳敷の上座、東に弓置場、北に畳敷の控えを配し、切妻造玄関を北東に設ける。控えの窓桟は矢羽根形とし、床天井の竿縁は弓なりに曲げる。木造の近代弓道場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014453"},{"id":"00014454","register_sub_id":"101","register_pk":"512438","name":"本多流洗心洞（髙木道場）的場","kana":"ほんだりゅうせんしんどう（たかぎどうじょう）まとば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県久喜市下清久字鶴ノ谷395-13","lat":36.07496667,"lng":139.64822778,"geo_status":"db","era":"昭和7年頃／平成23年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"11 - 0220","desc":"旧清久村の旧家に所在する弓道場の的場。切妻造で射場側を開放、残る三方を板壁とし、内部に安土を盛り上げる。コンクリート基礎と土台は安土断面を意識して背面側を高くする。左右に矢除板を配し、その背後に的置場を設ける。木造の近代弓道場的場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014454"},{"id":"00001239","register_sub_id":"101","register_pk":"102229","name":"一木歯科医院","kana":"いちきしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県筑西市甲12","lat":36.31075701,"lng":139.97806752,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積30㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0012","desc":"大正１０年隣家の失火により類焼した後の再建建物のため防火に配慮した造りになる。木造鐵網コンクリート仕上げの数少ない遺存例として貴重。外観は、上げ下げ窓を割付けただけの単純な構成をとるが、プロポーションは的確で古典的な風格すら感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001239"},{"id":"00001165","register_sub_id":"101","register_pk":"102155","name":"旧共楽館（日立武道館）","kana":"きゅうきょうらくかん（ひたちぶどうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県日立市白銀町2-21-15","lat":36.611504,"lng":140.645523,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積1200㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"08 － 0006","desc":"日立鉱山が従業員や地域住民のために建設した大規模な妻入の劇場で、歌舞伎座（東京）を模したといわれる。正面入り口の左右に２階建、唐破風屋根の階段室が附属する。内部は、屋内体育館として改造されているが、堂々たる外観は地域の象徴ともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001165"},{"id":"00010909","register_sub_id":"101","register_pk":"208880","name":"旧樋口病院入院棟","kana":"きゅうひぐちびょういんにゅういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字泉町北側705","lat":36.771032,"lng":140.353939,"geo_status":"db","era":"昭和30／平成26改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0282","desc":"大子駅から東に延びる通りに南面して建つ。奥行の長い木造二階建で、正面玄関脇には旧車庫を設ける。中廊下の両側に、一階には診察室等を、二階には病室を並べる。正面妻側には柱形を見せて垂直性を強調。縦桟で細長く割り付けるガラス窓も当時の特徴を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010909"},{"id":"00004512","register_sub_id":"101","register_pk":"105502","name":"武石家住宅主屋","kana":"たけいしけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町1107-1","lat":36.31234,"lng":140.567322,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積133㎡","structure_material":"木造平屋一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0172","desc":"洋館を医院，和館を住宅として建設。洋館は木造２階建，寄棟造，桟瓦葺で，外壁をドイツ下見板張とし，胴蛇腹を廻す。玄関庇は瓔珞形の鼻隠で飾る。１階が診察室，２階は書斎と子供室であった。和館は寄棟造の平屋建。地方における大正期医院併用住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004512"},{"id":"00014733","register_sub_id":"101","register_pk":"518991","name":"土浦市民会館","kana":"つちうらしみんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"茨城県","address":"茨城県土浦市東真鍋町1480-2","lat":36.09126389,"lng":140.20506111,"geo_status":"db","era":"昭和44年／令和2年改修","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造3階建、陸屋根、建築面積2，674㎡","structure_material":"鉄筋コンクリート造一部鉄骨造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"08 - 0319","desc":"建物の南正面全幅を階段とし、角柱の列柱廊をガラス壁で画し、吹抜のホワイエとする。東側の三階分を占める大ホールは側面壁と天井の曲面で音響を整える。西側二、三階を占める小ホールは傾斜席の靴箱形。佐藤武夫の設計による古典主義的意匠の外観が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014733"},{"id":"00004514","register_sub_id":"101","register_pk":"105504","name":"幕末と明治の博物館別館","kana":"ばくまつとめいじのはくぶつかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町字見付久保8231-4","lat":36.32144237,"lng":140.58308887,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積591㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0174","desc":"聖像殿と渡廊下で接続する鉄筋コンクリート造平屋建。展示室外壁は無窓で，石造風に目地を切った擬石仕上とし，角形付柱が区画する重厚な外観意匠である。軒下には歯飾を施す。第１展示室の南面には窓を設け，コリント風円柱を並べてアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004514"},{"id":"00007342","register_sub_id":"101","register_pk":"108324","name":"石原家住宅主屋","kana":"いしはらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県印旛郡栄町北辺田字前原573-1","lat":35.853152,"lng":140.26213534,"geo_status":"db","era":"明治7／昭和55頃改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積199㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"12 － 0115","desc":"敷地の中央に東面して建つ。桁行８間半梁間６間の木造平屋建で、寄棟造茅葺（鉄板仮葺）とし、正面北端に入母屋造の玄関を構える。内部は北寄りに奥座敷などを一列に並べ、南側の東半部を医療施設、西半部を住居にあてる。医院併用住宅として特徴的な構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007342"},{"id":"00001243","register_sub_id":"101","register_pk":"102233","name":"和泉公会堂","kana":"いずみこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県鴨川市和泉1612","lat":35.128761,"lng":140.102707,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積314㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0024","desc":"明治４２年着工された耕地整理の完成を機に建設された地区住民の共有建築物。耕地整理の記念碑的建造物でもある。瓦葺寄棟屋根の主屋の外周に庇を差出し、正面中央にムクリ入母屋の車寄玄関を突出させた、和風公会堂建築に共通した形態をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001243"},{"id":"00000236","register_sub_id":"101","register_pk":"101226","name":"興風会館","kana":"こうふうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田250","lat":35.94276827,"lng":139.8635723,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建，建築面積527㎡","structure_material":"鉄筋コンクリート造4階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0005","desc":"正面のファサードはルネッサンス風の意匠を基調とし、ロマネスク風アーチからなるゆったりとした玄関部はじめ全体として威圧的にならない構成にまとめ上げる。設計大森茂、施工戸田組。２階講堂の空間構成や、階段廻りの意匠など建築的に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000236"},{"id":"00000237","register_sub_id":"101","register_pk":"101227","name":"武田家住宅","kana":"たけだけじゅうたく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県市原市古市場53","lat":35.54169917,"lng":140.15029449,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建，瓦葺，建築面積185㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0006","desc":"元は和風の建物であったが、昭和３年建設の左半分の建屋に、昭和３１年に右半分の建屋を移築し結合した。その際、外壁のみ左手の建屋に合わせて洋風に改修されて和風屋根との折衷形式となった。特異な外観の住宅（元医院）として、地域の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000237"},{"id":"00015412","register_sub_id":"101","register_pk":"533427","name":"千葉県立美術館展示棟","kana":"ちばけんりつびじゅつかんてんじとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"千葉県","address":"千葉県千葉市中央区中央港一丁目104","lat":35.60115,"lng":140.10100833,"geo_status":"db","era":"昭和49年／平成24年改修","year":1974,"year_source":"db","year_min":1974,"year_max":1974,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建、鉄板葺、建築面積5，032㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"12 - 0336","desc":"千葉港中央地区の臨海公園に位置する美術館。設計は大髙建築設計事務所。鉄筋コンクリート造及び鉄骨造の展示室をグリッド状に配して拡張可能とし、それぞれ傾斜屋根と外壁炻器質タイルを用いて、外観にまとまりをみせる。大髙正人による初期の美術館の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015412"},{"id":"00013692","register_sub_id":"101","register_pk":"505209","name":"野田市郷土博物館","kana":"のだしきょうどはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市野田字谷端370-8","lat":35.94534722,"lng":139.86547778,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積257㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"12 － 307","desc":"山田守設計の博物館。鉄筋コンクリート造二階建で正面中央に玄関を付す。リシン仕上に横目地を入れ、プレキャストコンクリートの竪格子をはめた横長の開口部等、水平を意識したモダニズムに連なる外観意匠。内部は自然光を間接的に取込むなど環境設計も秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013692"},{"id":"00013054","register_sub_id":"101","register_pk":"504383","name":"稲荷湯長屋","kana":"いなりゆながや","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都北区滝野川六丁目27-5","lat":35.74473333,"lng":139.72453333,"geo_status":"db","era":"昭和2年／昭和5年頃移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0427","desc":"浴場兼主屋の東側に東面して建つ。木造平屋建、金属板葺で、一棟二戸の長屋である。従業員の住居であったと考えられる。内部は各戸とも下手に玄関と奥に三畳、上手に押入付の六畳とし、便所を附属する。銭湯の職住一体経営の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013054"},{"id":"00013053","register_sub_id":"101","register_pk":"504382","name":"稲荷湯浴場兼主屋","kana":"いなりゆよくじょうけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都北区滝野川六丁目27-5","lat":35.744675,"lng":139.72442222,"geo_status":"db","era":"昭和5年／昭和33年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積361㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0426","desc":"板橋駅東方の住宅地で通りに北面する銭湯。北半を浴場、南半を主屋とし、浴場正面に入母屋造の玄関部を構える。東半を男湯、西半を女湯とし、玄関奥に脱衣場、流し場、浴槽を配す。破風が三段に連なる正面意匠など、戦前の東京における銭湯の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013053"},{"id":"00000630","register_sub_id":"101","register_pk":"101620","name":"大倉集古館陳列館","kana":"おおくらしゅうこかんちんれつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都港区虎ノ門2-10-3","lat":35.667079,"lng":139.74339573,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造２階建，銅板葺，建築面積863㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0011","desc":"大倉喜八郎本邸に設けられた私設美術館の震災復興建築。伊東忠太の設計によるもので，伊東忠太の東洋建築に関する蘊蓄を披瀝した作品として知られる。陳列館東面から敷地低地に連なっていたかっての入口部分は失われて現存しない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000630"},{"id":"00001565","register_sub_id":"101","register_pk":"102555","name":"温故学会会館","kana":"おんこがっかいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区東2-9-1","lat":35.654331,"lng":139.711395,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積187㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0080","desc":"「群書類従」などの版木約２万枚を収蔵する目的で建設されたＲＣ造二階建。左翼一階を事務所，二階を和風の講堂，右翼各階を収蔵庫とする。正背面にバットレスが立ち並ぶ簡明な意匠を特色とし，正面中央に円形の玄関ポーチを張り出す。設計・施工は清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001565"},{"id":"00003070","register_sub_id":"101","register_pk":"104060","name":"学士会館","kana":"がくしかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田錦町3-28","lat":35.693192,"lng":139.758987,"geo_status":"db","era":"昭和3／昭和12増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上5階地下1階建、建築面積1839㎡","structure_material":"鉄骨鉄筋コンクリート造地上5階地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"13 － 0134","desc":"ホール，サロン，宿泊施設などの機能を持つ。ＳＲＣ造による関東大震災後の復興建築で，玄関の半円大アーチやスクラッチタイルの外観，窓廻り２・３層の直線基調と４層の曲線基調の対比などに特徴がある。設計は佐野利器と高橋貞太郎（増築部は藤村朗）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003070"},{"id":"00014753","register_sub_id":"101","register_pk":"519011","name":"旧柏湯","kana":"きゅうかしわゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区谷中六丁目17","lat":35.72176111,"lng":139.77050278,"geo_status":"db","era":"昭和26年／平成5年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺及び鉄板葺、建築面積177㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0498","desc":"谷中の尾根道の南東角地に建つかつての銭湯。北道路側に突出した玄関は引分け戸の上部に筬欄間を入れる。入母屋造の大屋根下が旧脱衣室で、南の旧浴場は上部中央を立上げて高窓とする。南端の二階建部分は旧火焚場。昭和初期から流行した宮造り銭湯の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014753"},{"id":"00012303","register_sub_id":"101","register_pk":"531627","name":"旧砂堀医院","kana":"きゅうすなぼりいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都目黒区目黒三丁目533-59","lat":35.63189167,"lng":139.70479167,"geo_status":"db","era":"昭和12年頃／昭和40年代・同60年代・平成24年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、金属板葺、建築面積66㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-409","desc":"住宅地の路地に西面して建つ。切妻造平入の北側に切妻造妻入の別棟を接続し、下屋を廻して一つにまとめる。内部はホールを中心に待合や診察室、応接室等を配する。改変多いが、大壁モルタル仕上や腰スクラッチタイル張、縦長窓が昭和の洋風住宅の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012303"},{"id":"00001501","register_sub_id":"101","register_pk":"102491","name":"旧清明文庫","kana":"きゅうせいめいぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区南千束2-3-1","lat":35.60212051,"lng":139.692261,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積548㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0072","desc":"東洋文明の啓蒙活動を行っていた清明会が設立した清明文庫の本館で，戦後出版社の所有となり鳳凰閣と称す。内装はモザイクタイルを用いるなど要所を飾るが，外壁は装飾的要素を控えた簡明なデザインとし，正面玄関上から立ち上がる４本の柱型に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001501"},{"id":"00007193","register_sub_id":"101","register_pk":"108175","name":"旧東京市深川食堂","kana":"きゅうとうきょうしふかがわしょくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区門前仲町1-19-15","lat":35.67407431,"lng":139.794922,"geo_status":"db","era":"昭和7／昭和20頃改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0234","desc":"角地に建つＲＣ造２階建。南面西端をエントランスとし、その奥を、２階天井まで全面窓で明るく開放的な階段室とする。当初は２階南面には水平に連続するスチール・サッシュ窓が設けられた。震災復興事業で建設された食堂で、当時の建築デザインの潮流を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007193"},{"id":"00013234","register_sub_id":"101","register_pk":"366223","name":"旧三井文庫第二書庫","kana":"きゅうみついぶんこだいにしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都品川区豊町一丁目1131-1","lat":35.61228333,"lng":139.72053611,"geo_status":"db","era":"大正11年／大正15年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造3階建、金属板葺、建築面積130㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0430","desc":"区立公園文庫の森に建つ、三井家史料管理のための書庫。鉄筋コンクリート造、二重の壁式構造で、一階を含む各階床と三階天井は鉄筋コンクリート造スラブとし、防火に優れた堅牢な造り。書架の鉄骨支柱で床を支持するなどの工夫がみられ、技術的価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013234"},{"id":"00004948","register_sub_id":"101","register_pk":"105938","name":"黒沢ビル","kana":"くろさわびる","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区上野2-40","lat":35.70906486,"lng":139.77054045,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積144㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"13 － 0188","desc":"小川眼科病院として建設。鉄筋コンクリート造，地上３階地下１階建で，正面１階の鉄平石張，尖頭アーチ窓やコンクリート製幌状の庇など表現派風意匠に特徴がある。屋上には温室風の紫外線療法室が残り，室内随所に小川三知作ステンドグラスをみることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004948"},{"id":"00005585","register_sub_id":"101","register_pk":"106573","name":"国際文化会館本館","kana":"こくさいぶんかかいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区六本木5-11-16","lat":35.65852616,"lng":139.733368,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積2824㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0199","desc":"敷地中央に北面して建ち，南側に広大な日本庭園をもつ。ＲＣ造３階建，地下１階で，２階以上を宿泊施設とし，１階及び地階を会議室，ホール等とする。木製建具を使った宿泊部分の軽快なモダニズムの外観意匠と日本庭園が融合する日本近代建築の傑作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005585"},{"id":"00009921","register_sub_id":"101","register_pk":"196068","name":"国立天文台表門","kana":"こくりつてんもんだいおもてもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67514943,"lng":139.53887173,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、間口5.5m、左右通用門付","structure_material":"コンクリート造","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0336","desc":"敷地東面に開く。中央門と左右脇門の四本の門柱からなる。門柱は鉄管を芯としたコンクリート造の表面に角石を乱れ張りとし、隅部は几帳面を取り、柱頭と足下の石にはフルーティングを施す。中央門柱の上には照明器具を据える。国立天文台の玄関口を飾る門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009921"},{"id":"00009919","register_sub_id":"101","register_pk":"196066","name":"国立天文台旧図庫及び倉庫","kana":"こくりつてんもんだいきゅうずこおよびそうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67486706,"lng":139.53694001,"geo_status":"db","era":"昭和5／昭和36改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、金属板葺、建築面積100㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0334","desc":"敷地中ほどに位置する。鉄筋コンクリート二階建で、窓の上下には水平に連続する小庇を付す。一階には丸窓を付ける。西にモルタル塗の増築部が付くが、当初から増築の想定がなされていた。シンプルな外観やスクラッチタイル貼仕上げに昭和初期の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009919"},{"id":"00009916","register_sub_id":"101","register_pk":"196063","name":"国立天文台ゴーチェ子午環室","kana":"こくりつてんもんだいごーちぇしごかんしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67494286,"lng":139.53590987,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積129㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0331","desc":"子午線上の天体の精密位置観測のための子午環を納める半円形立面を持つ建物。軸線を正確に南北に据え、建物から独立した中央の基礎に子午環を置く。建物の基礎及び側壁は鉄筋コンクリート造で、東西に出入口を付し、屋根は鉄骨造で観測時には屋根中央が開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009916"},{"id":"00009917","register_sub_id":"101","register_pk":"196064","name":"国立天文台第一子午線標室","kana":"こくりつてんもんだいだいいちしごせんひょうしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67424258,"lng":139.53529576,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積7.3㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0332","desc":"子午環室の南一〇〇メートルに位置し、子午環の規準点となる子午線標を納める。鉄筋コンクリート造二階建で北面を三角形の土留擁壁とし、背面は土盛とする。二階に子午線標を納め、擁壁前面に取付く階段で出入りする。子午環の南北軸の精度確保を担う施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009917"},{"id":"00002621","register_sub_id":"101","register_pk":"103611","name":"国立天文台第一赤道儀室","kana":"こくりつてんもんだいだいいちせきどうぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.674274,"lng":139.538559,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積50㎡、ドーム付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0126","desc":"構内の直線道路を介して大赤道儀室と対面する。外観左右対称の張出通路付ＲＣ造円筒状躯体の上に，手動で屋根の開閉と回転を行う直径５．６ｍの鉄骨造ドームが載り，口径２０ｃｍのツァイス製望遠鏡を収める。大赤道儀室と同様，東京帝国大学営繕課の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002621"},{"id":"00002620","register_sub_id":"101","register_pk":"103610","name":"国立天文台大赤道儀室","kana":"こくりつてんもんだいだいせきどうぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.674274,"lng":139.536743,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積238㎡、ドーム付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0125","desc":"市西部の雑木林を残す敷地内にある。頂部にロンバルト帯風の蛇腹を廻した円筒状ＲＣ造躯体に，直径１５ｍの銅板葺鉄骨造ドームを載せ総高19.5ｍとする。ツァイス製望遠鏡の鏡筒の方向・傾きに合わせて，ドーム回転と円形観測床の回転及び傾斜角調節を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002620"},{"id":"00009918","register_sub_id":"101","register_pk":"196065","name":"国立天文台第二子午線標室","kana":"こくりつてんもんだいだいにしごせんひょうしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67577611,"lng":139.53575114,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積7.2㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0333","desc":"子午環室の北一〇〇メートルに位置する。第一子午線標室と同型の建物で、子午環室を挟んで南北対称に配置される。内部の子午線標は鉄筋コンクリート基礎の上に置かれるが、建物とは縁が切られている。天文台ならではの自然環境から精密測定機器を守る建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009918"},{"id":"00000565","register_sub_id":"101","register_pk":"101555","name":"国立天文台太陽分光写真儀室","kana":"こくりつてんもんだいたいようぶんこうしゃしんぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.67334615,"lng":139.53671256,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積331㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"13 － 0010","desc":"アインシュタインの相対性原理の検証を主目的として建てられ，アインシュタイン塔の名で知られる。観測室を頂部にもつ塔状の外観が特徴で，塔の内部には建物と絶縁された機械室が上部までつながっており，その周囲に階段と準備室が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000565"},{"id":"00009920","register_sub_id":"101","register_pk":"196067","name":"国立天文台門衛所","kana":"こくりつてんもんだいもんえいじょ","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.6752601,"lng":139.53877926,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0335","desc":"正門北に建つ。木造平屋建切妻造平入で、正面に切妻屋根の玄関を付し、玄関上部や妻面にハーフティンバー風の意匠を見せ、外壁を下見板張とするなど洋風意匠とする。内部は中央を壁で仕切り、それぞれ六畳と四畳半の和室と便所を持つ左右対称の平面であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009920"},{"id":"00009915","register_sub_id":"101","register_pk":"196062","name":"国立天文台レプソルド子午儀室","kana":"こくりつてんもんだいれぷそるどしごぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.6749584,"lng":139.53640523,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積36㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0330","desc":"子午線上を通過する天体を観測し、その地の経度や時刻を決める子午儀を納める建物。ゼツェッション風の意匠を持つ鉄筋コンクリート造平屋建の建物で、鉄骨造の小屋組はレール上に据えられ、観測時には鉄骨造の切妻屋根が中央から開き、子午儀上方を開放する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009915"},{"id":"00013358","register_sub_id":"101","register_pk":"504384","name":"小杉湯","kana":"こすぎゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区高円寺北三丁目1003-11","lat":35.70808333,"lng":139.64882222,"geo_status":"db","era":"昭和8年／昭和38年・同46年増築、平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺及び金属板葺、建築面積287㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0436","desc":"高円寺駅北の商店街に所在する公衆浴場。脱衣室屋根の東正面に千鳥破風を掲げ、一階の唐破風庇下が旧入口である。浴室は中央に越屋根を掲げて高窓とし、西壁には男女の浴室にわたるペンキ絵を描く。改修はあるが、東京でよく見られた銭湯の典型例の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013358"},{"id":"00011889","register_sub_id":"101","register_pk":"354915","name":"五島美術館本館","kana":"ごとうびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都世田谷区上野毛三丁目112-3他","lat":35.612275,"lng":139.635627,"geo_status":"db","era":"昭和35年／平成24年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階一部地下1階建、建築面積1143㎡","structure_material":"鉄筋コンクリート造平屋一部2階一部地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"13-386","desc":"東急電鉄の創業者五島慶太の喜寿を記念したもの。設計は吉田五十八で、鉄筋コンクリート造による伝統表現を意図し、寝殿造を参照した平面や大径の丸柱、蔀戸や御簾の建具意匠、幅広の縁や深い軒による水平線の強調など平安朝の意匠を模す吉田五十八の代表作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011889"},{"id":"00015418","register_sub_id":"101","register_pk":"533433","name":"駒澤大学旧図書館（禅文化歴史博物館・耕雲館）","kana":"こまざわだいがくきゅうとしょかん（ぜんぶんかれきしはくぶつかん・こううんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区駒沢一丁目3403-1","lat":35.62850556,"lng":139.65812222,"geo_status":"db","era":"昭和3年／平成13年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造一部鉄骨造地上2階地下1階建、建築面積544㎡","structure_material":"鉄骨鉄筋コンクリート造一部鉄骨造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0527","desc":"駒沢オリンピック公園北側の大学内に建つ旧図書館。設計は菅原榮蔵。八角形ドームを頂く吹抜の旧大閲覧室を中心に事務室等を配する。ステンドグラスなどの幾何学的意匠はライト風で、スクラッチタイル貼の屏風状に広がる外観など自在なデザインが異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015418"},{"id":"00016497","register_sub_id":"101","register_pk":"574859","name":"十四世喜多六平太記念能楽堂","kana":"じゅうよんせいきたろっぺいたきねんのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"東京都","address":"東京都品川区上大崎四丁目245-1他","lat":35.63362889,"lng":139.71477778,"geo_status":"db","era":"昭和48年／令和7年改修","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上2階地下2階建、建築面積626㎡、舞台及び橋掛付","structure_material":"鉄骨鉄筋コンクリート造地上2階地下2階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0528","desc":"目黒駅付近に位置し、喜多流十四世宗家を記念した常設能楽堂。設計は榛沢敏郎。鉄骨鉄筋コンクリート造地上2階地下2階建で能舞台を内包する。主体部外観は地上より持上げて軽快にみせ、御影石張の階段やトラバーチン貼の壁面が入口アプローチを巧みに構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016497"},{"id":"00016654","register_sub_id":"101","register_pk":"579138","name":"松連庵(旧松連寺庫裏)","kana":"しょうれんあん（きゅうしょうれんじくり）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都日野市百草560","lat":35.654228,"lng":139.427061,"geo_status":"db","era":"江戸後期／昭和中期・令和7年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"13 - 0533","desc":"多摩川丘陵南東端に広がる百草園内に東面して建つ旧松連寺の庫裏。桁行八間半、梁間四間、寄棟造平入茅葺で、正面に二間半の式台を構え差掛け屋根を付す。内部は北を土間とする六間取で、端正な床構え付き座敷を設ける。旧庫裏を転用した茅葺屋根の園内施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016654"},{"id":"00015298","register_sub_id":"101","register_pk":"532422","name":"ソルフェージスクール","kana":"そるふぇーじすくーる","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"東京都","address":"東京都豊島区目白四丁目1434-2","lat":35.72548333,"lng":139.70059722,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造3階建、人工スレート葺、建築面積96㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0519","desc":"目白駅北西方の住宅街に建つ、吉村順三がバイオリニストの妻のために設計した音楽教室。一・二階の教室や階段は丁寧な造作で三階ホールは斜線規制に則した勾配屋根で天井高を確保し水平窓で巧みに分節する。吉村による一連の音楽施設の初期作品として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015298"},{"id":"00001498","register_sub_id":"101","register_pk":"102488","name":"高橋診療所","kana":"たかはししんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区山王3-30-5","lat":35.586273,"lng":139.726044,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0069","desc":"ＪＲ大森駅西側の池上通り商店街に，住宅を兼ねた診療所として建設。診療室を除き内部は改造されているが，昭和初期に流行したスパニッシュ風の外観を残す。近在の宅地化に伴って洒落た商店建築等が建ち並んでいた町並の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001498"},{"id":"00002618","register_sub_id":"101","register_pk":"103608","name":"東京文化財研究所黒田記念館書庫","kana":"とうきょうぶんかざいけんきゅうじょくろだきねんかんしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園12-53","lat":35.719067,"lng":139.773453,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積70㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0123","desc":"本館の北東に隣接して建てられた鉄筋コンクリート造３階建の矩形平面を有す建築物。美術研究所の書庫として建設。各壁面に縦長の開口部を設けていた。本館と同様のスクラッチタイル張の外装仕上げとし，本館と連続的な街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002618"},{"id":"00002617","register_sub_id":"101","register_pk":"103607","name":"東京文化財研究所黒田記念館本館","kana":"とうきょうぶんかざいけんきゅうじょくろだきねんかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園12-53","lat":35.71893524,"lng":139.7733612,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建半地下階付、建築面積463㎡、煙突付","structure_material":"鉄筋コンクリート造2階建半地下階付","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0122","desc":"東京芸術大学音楽学部敷地と同ブロックの角地に建つ。黒田清輝の遺言により建設された美術館施設で，２階に展示室を設ける。外観はスクラッチタイル張りで，正背面２階中央にイオニア式列柱６本を配してほぼ左右対称の端整な立面をつくる。設計は岡田信一郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002617"},{"id":"00001248","register_sub_id":"101","register_pk":"102238","name":"日本工業倶楽部会館","kana":"にほんこうぎょうくらぶかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都千代田区丸の内1-4-6","lat":35.68334265,"lng":139.76480432,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄骨造、鉄筋コンクリート造及び鉄筋鉄筋コンクリート造地上5階地下4階建、6階以上部分を除く、建築面積1877㎡","structure_material":"鉄骨造","registered":"1999.08.23(平成11.08.23)","register_no":"13 － 0055","desc":"東京駅駅頭に建つアメリカ式オフィスビルの形態にユーゲント・シュティルの意匠を加味した大正建築。我が国工業界のシンボル的建築で、正面中央パラペット上部の人像彫刻は当時の二大工業（石炭と紡績）を表す。設計は横河工務所、松井貴太郎の担当とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001248"},{"id":"00016500","register_sub_id":"101","register_pk":"574862","name":"日野市立中央図書館","kana":"ひのしりつちゅうおうとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"東京都","address":"東京都日野市豊田二丁目49-2","lat":35.65623694,"lng":139.38236694,"geo_status":"db","era":"昭和48年／令和元年改修","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積904㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0531","desc":"豊田駅南方に位置する市立中央図書館。鉄筋コンクリート造地上2階地下１階建、外壁は焼過煉瓦積。選書の快適さを重視し、開架室は吹抜の庭側を全面ガラス窓とするなど、初代館長前川恒雄の構想を建築家鬼頭梓が具現化。現代公共図書館の起点となった建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016500"},{"id":"00004528","register_sub_id":"101","register_pk":"105518","name":"山本歯科医院","kana":"やまもとしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田須田町1-3-3","lat":35.69608772,"lng":139.76918079,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造3階建、亜鉛メッキ鋼板葺、建築面積48㎡","structure_material":"木造3階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0182","desc":"靖国裏通り沿いに北面して建つ，木造３階建，切妻造，金属板葺の診療所兼住宅。入口付近等に改造が認められるが，全体に創建時の様子を良く残す。関東大震災復興期における看板建築の遺構で，軒蛇腹，看板，菱形装飾などによる正面の外観意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004528"},{"id":"00008656","register_sub_id":"101","register_pk":"149377","name":"矢来能楽堂","kana":"やらいのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新宿区矢来町60-1","lat":35.70289459,"lng":139.73244709,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"converted","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部地下1階建、瓦葺、建築面積432㎡、舞台及び橋掛付","structure_material":"木造平屋一部地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0279","desc":"市街地に所在する能楽堂。木造平屋1部地下1階建、建築面積432㎡。棟の高い切妻造桟瓦葺を中心に、玄関やロビー他を周囲に付設する。外壁モルタル仕上げ。舞台や橋掛のほか、楽屋や地下通路、客席を設け、風格のある内部空間を創出する。近代能楽堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008656"},{"id":"00007732","register_sub_id":"101","register_pk":"108714","name":"代々木能舞台敷舞台及び座敷","kana":"よよぎのうぶたいしきぶたいおよびざしき","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区代々木4-36-42","lat":35.6808947,"lng":139.68964368,"geo_status":"db","era":"昭和8／昭和25改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"13-0247","desc":"桁行１４ｍ梁間６．４ｍ、東西棟の木造平屋建。トコや棚を構える十七畳半の座敷を東に、敷舞台を西に設ける。敷舞台は小規模ながら後座と地謡座を備え、格天井を張り、木鼻付虹梁を掛け、蟇股を置く。座敷は舞台の桟敷でもあり、舞台側の北面窓を大きく開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007732"},{"id":"00007731","register_sub_id":"101","register_pk":"108713","name":"代々木能舞台舞台・橋掛・鏡の間","kana":"よよぎのうぶたいぶたい・はしがかり・かがみのま","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都渋谷区代々木4-36-42","lat":35.68098353,"lng":139.68964164,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋一部地下1階建、銅板葺、建築面積84㎡","structure_material":"木造平屋一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"13-0246","desc":"舞台は桁行５．５ｍ梁間５．４ｍの切妻造妻入で、背面に後座、側面に地謡座を付ける。面取方柱で大斗肘木組、化粧屋根裏天井。橋掛は舞台に直角に付き、桁行９．５ｍ梁間１．９ｍの化粧屋根裏天井で、西端が鏡の間へ通じる。丁寧に造られた本格的な能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007731"},{"id":"00014758","register_sub_id":"101","register_pk":"519016","name":"龍子記念館","kana":"りゅうしきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都大田区中央四丁目1034-2-1","lat":35.58237222,"lng":139.71555833,"geo_status":"db","era":"昭和37年／平成3年・同23年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、陸屋根一部瓦葺、建築面積747㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0503","desc":"川端龍子の作品を展示する記念館。角地に建つ鉄筋コンクリート造2階一部3階建で、全体をクの字とした特異な平面で１階をピロティ、2階を展示室とする。西隅3階部分は青い釉薬瓦葺の宝形造屋根で、竜舌蘭の宝珠を載せた姿は、地域のランドマーク的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014758"},{"id":"00016656","register_sub_id":"101","register_pk":"579140","name":"伊東医院住居棟","kana":"いとういいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.402956,"lng":139.536817,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、天然スレート葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0368","desc":"診療所の南側に西面して建つ住居棟。切妻破風を正面に見せた急勾配のスレート葺洋館の背面に、中廊下沿いに座敷を並べる和館を配す。座敷欄間の組子は技巧的で、書院の下地窓など数寄屋風意匠を取込む。破風に持送を付し、外観華やかな洋館付き近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016656"},{"id":"00016655","register_sub_id":"101","register_pk":"579139","name":"伊東医院診療棟","kana":"いとういいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.403008,"lng":139.536688,"geo_status":"db","era":"大正14年／平成7年・令和2年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積95㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0367","desc":"旧東海道戸塚宿沿いの敷地に北面して建つ診療所。木造２階建半切妻造、外壁モルタル洗出仕上で上下窓を開ける。玄関ポーチの庇は幾何学意匠の持送で支え、正面軒に半円形の破風を飾る。地域医療を支えてきた診療所で、内部の室構成も良く残る上質な近代建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016655"},{"id":"00016657","register_sub_id":"101","register_pk":"579141","name":"伊東医院門及び塀","kana":"いとういいんもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.403078,"lng":139.536624,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 鉄筋コンクリート造、間口2.4m 塀 鉄筋コンクリート造、総延長19m","structure_material":"門 鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0369","desc":"旧東海道沿いに配された門及び塀。門柱は主体部を切石貼とする他はモルタル洗出で仕上げる。塀は出隅にアールを付け、腰は色を変えて横目地を切り、上部に木製ガラリを嵌込んだ開口を連続的に穿つ。全体に丁寧なつくりで診療所とともに歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016657"},{"id":"00001662","register_sub_id":"101","register_pk":"102652","name":"鎌倉国宝館本館","kana":"かまくらこくほうかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下2-1051-2","lat":35.32472551,"lng":139.55691185,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積799㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"14 － 0040","desc":"鉄筋コンクリート造による高床式校倉風建築。設計は岡田信一郎。寄棟状屋根の中央部には小屋裏位置に採光用の越屋根を隠し、内部では虹梁大瓶束形式で採光用越屋根の棟を支える造りとするなど和風表現と近代的技法との調和に苦心した跡がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001662"},{"id":"00015007","register_sub_id":"101","register_pk":"529285","name":"旧鎌倉図書館","kana":"きゅうかまくらとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市御成町18-35","lat":35.31871944,"lng":139.54813056,"geo_status":"db","era":"昭和11年／令和5年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0352","desc":"市役所東側の敷地に南面して建つ。木造二階建の外観は一・二階通しの柱形を付し縦長窓を多用。腰は緑青釉薬スクラッチタイル貼、懸魚を付した大きな切妻屋根を架ける。階段柱にはアールデコ調意匠をあしらう。シンプルな和洋折衷意匠が特徴的な図書館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015007"},{"id":"00008268","register_sub_id":"101","register_pk":"133910","name":"旧後藤医院鵠沼分院","kana":"きゅうごとういいんくげぬまぶんいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市鵠沼橘1-1850-40","lat":35.3342685,"lng":139.48408678,"geo_status":"db","era":"昭和8年／平成4年・平成19年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"14 － 0165","desc":"東に街路に面する矩形敷地に建つ。桁行２０ｍ梁間８．４ｍの木造平屋建、東西棟の入母屋造銅板葺。東半部を医院、西半部を住居とした。通風のため床高を高く、出窓を付け二重窓とし、換気用の越屋根を三ヶ所設置するなど機能向上のための工夫がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008268"},{"id":"00012308","register_sub_id":"101","register_pk":"531632","name":"旧長濱検疫所一号停留所","kana":"きゅうながはまけんえきしょ１ごうていりゅうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市金沢区海の公園10","lat":35.35961389,"lng":139.63503056,"geo_status":"db","era":"明治中期／大正後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、金属板葺、建築面積420㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"14 - 0257","desc":"検疫対象者の旧宿泊施設。切妻造鉄板葺で、コの字形平面の主体部に停留室八室を設け、両端突出部に食堂と談話室を配する。外壁は下見板張、上下窓を基調としながら突出部の先端にベイウィンドウを用いて変化を付ける。横浜最古級の洋風建築として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012308"},{"id":"00012137","register_sub_id":"101","register_pk":"352936","name":"旧南湖院第一病舎","kana":"きゅうなんこいんだいいちびょうしゃ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県茅ヶ崎市南湖七丁目12869-201","lat":35.319634,"lng":139.388952,"geo_status":"db","era":"明治32年／昭和54年・同58年・平成15年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、スレート葺、建築面積115㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"14-256","desc":"敷地北寄りに建つ木造二階建。矩形平面で北面に切妻屋根の玄関部、西面に階段室を張出して立面に変化を付ける。外壁は下見板張で上下窓を並べ、二階窓にペディメントを飾り、開口が多く採光通風に配慮する。療養地として著名な湘南で希少な明治期の結核病棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012137"},{"id":"00014582","register_sub_id":"101","register_pk":"515124","name":"旧広田医院主屋","kana":"きゅうひろたいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県高座郡寒川町一之宮一丁目1126-1","lat":35.36378889,"lng":139.38482222,"geo_status":"db","era":"大正15年／昭和4年増築、昭和21年改修、昭和30年代増築","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積225㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0331","desc":"大山街道沿いの旧家の洋館付和風住宅。平屋建和館部は田の字型間取りで伝統的。二階建洋館は外壁を下見板張、一階に医院諸室を配し、Ｘ線室は大壁漆喰仕上。二階は床構え付一〇畳座敷に巡らした縁廊下に上下窓を開く。地域の医院として親しまれた佇まい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014582"},{"id":"00014583","register_sub_id":"101","register_pk":"515125","name":"旧広田医院門柱及び塀","kana":"きゅうひろたいいんもんちゅうおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県高座郡寒川町一之宮一丁目1126-1","lat":35.363575,"lng":139.384875,"geo_status":"db","era":"昭和4年／平成30年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門柱 コンクリート造、間口3.0m、袖塀付 塀 コンクリート造、総延長29m","structure_material":"門柱 コンクリート造","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0332","desc":"大山街道に開くコンクリート造門柱と塀基礎部分。門柱は太い角柱で、上部兜巾形で江戸切仕上の元は門扉付。袖柱を塀端部に立てて袖塀で塞ぎ、潜戸口を設ける。塀基礎は切石風モルタル仕上、元は板塀を載せた。医院表構えに相応しく重厚で歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014583"},{"id":"00013694","register_sub_id":"101","register_pk":"505211","name":"旧藤澤カントリー倶楽部クラブハウス（グリーンハウス）","kana":"きゅうふじさわかんとりーくらぶくらぶはうす（ぐりーんはうす）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市善行七丁目1-2","lat":35.36074167,"lng":139.47574167,"geo_status":"db","era":"昭和7年／令和2年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、瓦葺、建築面積786㎡、地下室付","structure_material":"鉄筋コンクリート造3階建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 291","desc":"Ａ・レーモンド設計。切妻造三階建の正面に車寄を張出し、背面に二階建をのばす。車寄など開口部の半円アーチによる構成、青緑色のスパニッシュ瓦葺屋根、アイアンワークの手摺など、全体をスパニッシュでまとめる。戦前のゴルフクラブハウスとしても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013694"},{"id":"00013371","register_sub_id":"101","register_pk":"368458","name":"材木座公会堂","kana":"ざいもくざこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市材木座四丁目356-1","lat":35.30763611,"lng":139.55270278,"geo_status":"db","era":"大正7年／平成9年頃改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積95㎡","structure_material":"木造平屋一部2階建","registered":"2020.08.17(令和2.08.17)","register_no":"14 － 0284","desc":"町民や別荘地の住民の寄付で建設した集会所兼防災施設、通り沿いの敷地に西面して建ち、敷地の南西隅に防火水槽を設置する。木造二階建、入母屋造金属板葺である。内部は広い一室の集会所で東面に床を構える。地域の集会所として現在も利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013371"},{"id":"00014775","register_sub_id":"101","register_pk":"519033","name":"山月庵","kana":"さんげつあん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24834722,"lng":139.04312222,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、檜皮葺一部こけら葺及び茅葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0343","desc":"強羅公園西の庭園神仙郷内に所在する茶室で、敷地中央北寄りに建つ。西面南に玄関を設け、中央の広間席八畳には畳床、琵琶床、香炉棚を飾る。東の茅葺屋根は三畳中板の小間で、蒲と煤竹の竿縁天井に吹寄丸太格天井を組合わせる。変化に富む近代数寄屋の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014775"},{"id":"00014776","register_sub_id":"101","register_pk":"519034","name":"日光殿（旧早雲寮）","kana":"にっこうでん（きゅうそううんりょう）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.2479,"lng":139.04363889,"geo_status":"db","era":"昭和24年／昭和26年増築、平成11年・令和3年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建一部地階付、こけら葺一部鉄板葺、建築面積640㎡","structure_material":"木造平屋建一部地階付","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0344","desc":"神仙郷の南東に建つ、吉田五十八設計の芸能鑑賞用の大広間棟。南面中央の玄関は地階に通じる。一階大広間は西寄りの小壁が廻る一郭と畳縁が当初の早雲寮に遡り、西に畳床を飾る。ここから南庭の芸能を観る。北東増築部は東寄りの床が一段高く舞台にもなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014776"},{"id":"00014779","register_sub_id":"101","register_pk":"519037","name":"箱根美術館休憩所","kana":"はこねびじゅつかんきゅうけいじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24868333,"lng":139.04321111,"geo_status":"db","era":"昭和27年／昭和56年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"コンクリートブロック造平屋建、陸屋根、建築面積115㎡","structure_material":"コンクリートブロック造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0347","desc":"神仙郷の北辺東端に北側道路に面して建つ補強コンクリートブロック造の平屋建の建物。外壁は大壁風につくり、陸屋根は庇を延ばし、わずかに高さを違えて三段につくる。西面北に券売口、南側を休憩室と売店とする。南面に大きく窓を開け、庭園鑑賞用の休憩所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014779"},{"id":"00014778","register_sub_id":"101","register_pk":"519036","name":"箱根美術館別館","kana":"はこねびじゅつかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24861667,"lng":139.04299722,"geo_status":"db","era":"昭和28年／昭和中期・同56年頃改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造2階建及びコンクリートブロック造平屋建、瓦葺、建築面積195㎡","structure_material":"鉄筋コンクリート造2階建及びコンクリートブロック造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0346","desc":"神仙郷の北辺中央に位置する美術館別館。補強コンクリートブロック造の平屋建の西に鉄筋コンクリート造二階建を増築。平屋は棟反りをつけた寄棟造、増築部は宝形造で青瓦葺とする。南面東寄りの玄関から展示室に入る。所蔵品に合わせて東洋趣味を加えた建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014778"},{"id":"00014777","register_sub_id":"101","register_pk":"519035","name":"箱根美術館本館","kana":"はこねびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24820556,"lng":139.04268889,"geo_status":"db","era":"昭和27年／昭和56年・平成７年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造及びコンクリートブロック造3階建、瓦葺、建築面積431㎡","structure_material":"鉄筋コンクリート造及びコンクリートブロック造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0345","desc":"神仙郷の北西に位置し東面して建つ美術館。鉄筋コンクリート造で床スラブに中空コンクリートブロックを用いる。中央に玄関、階段室を設け、南北に二階建の展示室を延ばす。三階塔屋は棟反りある寄棟屋根青瓦葺とし、貴賓室を設けて景観と共に名品を鑑賞する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014777"},{"id":"00005981","register_sub_id":"101","register_pk":"106966","name":"喬柏園（旧柏崎公会堂）","kana":"きょうはくえん（きゅうかしわざきこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県柏崎市西本町3-2-8","lat":37.36738707,"lng":138.54640128,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積535㎡、塔屋・煙突及び地下室付","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0256","desc":"南接する道路からやや奥まった位置に南面して建つ。間口１９ｍ，奥行８ｍ規模の棟の背面に，間口１６ｍ，奥行２２ｍ規模の棟が接続する鉄筋コンクリート造２階建。一部を３階建とする。外壁をタイル貼とし，円柱４本を並べる車寄を正面に張り出す公会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005981"},{"id":"00007735","register_sub_id":"101","register_pk":"108717","name":"三条市歴史民俗産業資料館（旧武徳殿）","kana":"さんじょうしれきしみんぞくさんぎょうしりょうかん（きゅうぶとくでん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市本町3-990-1","lat":37.63196778,"lng":138.95673472,"geo_status":"db","era":"昭和10／昭和24増築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0311","desc":"三条市の市街地に、東面して建つ。木造平屋建で、旧武道場を中心に西北に旧弓道場、東南に旧貴賓室を付ける。旧武道場は千鳥破風付の入母屋造桟瓦葺で、周囲に下屋庇をまわし、正面に唐破風造の玄関、北面に裏玄関を付設する。装飾を抑え、厳粛な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007735"},{"id":"00008270","register_sub_id":"101","register_pk":"133912","name":"第二藤巻医院石垣","kana":"だいにふじまきいいんいしがき","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市上野甲1350-1他","lat":37.1818454,"lng":138.74952303,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石積、総延長80m","structure_material":"石積","registered":"2010.09.10(平成22.09.10)","register_no":"15 － 0324","desc":"敷地西正面及び南北両側面に位置する。石積、総延長８０ｍ。信濃川の河原石を用い、仏の蓮華座のように積むことから蓮華積とも呼ばれる。正面最大の石は幅が１．２ｍほどもあり、南北両側面の奥にゆくほど積石が小さくなる。地域性の色濃い屋敷構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008270"},{"id":"00008269","register_sub_id":"101","register_pk":"133911","name":"第二藤巻医院本館","kana":"だいにふじまきいいんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市上野甲1350-1","lat":37.18182875,"lng":138.74973052,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積192㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"15 － 0323","desc":"道路に西面する敷地の中央に位置する。木造２階建、切妻造鉄板葺、建築面積１９２㎡。十字形平面で、病室や診察室、レントゲン室、居室部などゾーニングが明瞭である。外壁は板壁で、窓を規則的に配し、正面の車寄せや破風の持送りが左右対称の外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008269"},{"id":"00008438","register_sub_id":"101","register_pk":"134834","name":"高田世界館","kana":"たかだせかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市本町六丁目字下小町51-14","lat":37.11750858,"lng":138.24488387,"geo_status":"db","era":"明治44年／昭和後期改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦一部鉄板葺、建築面積331㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0332","desc":"本町通から三〇メートル奥に入った位置に東面して建つ。正面一五メートル奥行二三メートルの木造二階建。切妻造で、正面側を複雑な寄棟造とし、パラペットを付ける。内部にドリス風の柱をたてるなど、雁木や町家が建ち並ぶ界隈に残る洋風建築として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008438"},{"id":"00005808","register_sub_id":"101","register_pk":"106795","name":"森医院家財蔵","kana":"もりいいんかざいぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96730443,"lng":138.34721799,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0218","desc":"主屋南側に建ち，北側を正面とする。桁行６ｍ，梁間５ｍ，土蔵造２階建，切妻造，桟瓦葺，正面に奥行一間の下屋を設ける。外壁は下見板張とし，下屋前面にはガラス戸を付ける。正面入口扉と東側面上下階窓は漆喰仕上げとし，堅牢かつ上質な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005808"},{"id":"00005798","register_sub_id":"101","register_pk":"106786","name":"森医院主屋","kana":"もりいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.9674449,"lng":138.34721462,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積356㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0215","desc":"道路から入って正面に建つ。桁行２５ｍ，梁間１５ｍの主体部に増築部を付す。木造２階建，切妻造，桟瓦葺。平入りの既存建物の部材を使い明治４２年に建造し，主要軸部材を良く残すが，妻入りに変更した。茶の間上部を吹き抜けとする佐渡民家の特徴を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005798"},{"id":"00005810","register_sub_id":"101","register_pk":"106797","name":"森医院外便所","kana":"もりいいんそとべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96729797,"lng":138.34715054,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0220","desc":"敷地西辺に接して家財蔵と主屋増築部の間に建つ。桁行２．１ｍ，梁間１．５ｍの木造平屋建，切妻造，鉄板葺で，外部は波形鉄板及び横板張とする。正面軒を出桁造とし，内部は２室に区切る。裏庭の景観を構成する要素のひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005810"},{"id":"00005813","register_sub_id":"101","register_pk":"106800","name":"森医院中門","kana":"もりいいんちゅうもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96724888,"lng":138.34725835,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0222","desc":"主屋東側庭園の際に建ち，間口２．１ｍ，木造，腕木門，切妻造，桟瓦葺とする。主屋東側に広がる庭園と敷地南側の生活空間を隔てる境界をなす。間口の比較的大きな門であるが，造作は単純で簡素である。庭園の景観と一体となり，落着きのある空間を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005813"},{"id":"00005809","register_sub_id":"101","register_pk":"106796","name":"森医院納屋","kana":"もりいいんなや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96726139,"lng":138.34734481,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積53㎡、門付","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0219","desc":"主屋の南側に建つ。桁行１２ｍ，梁間４．５ｍ，木造２階建，切妻造，桟瓦葺で，北面に庇を付け，西面南端に脇門を設ける。納屋として規模が大きく，また主屋や病院棟の建築以前に建てられ，味噌蔵と共にかつての屋敷構えの景観を留めるひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005809"},{"id":"00005802","register_sub_id":"101","register_pk":"106790","name":"森医院病院棟","kana":"もりいいんびょういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.967583,"lng":138.34708473,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0216","desc":"主屋の北寄りに接続し，前庭に面する。桁行１４ｍ，梁間９ｍ，木造２階建，寄棟造，桟瓦葺。外壁は柱内を下見板張とし，軒を持送りで支持する。北及び東側屋根面に手摺付の切妻屋根を造り，アクセントとする。緑色を基調とした，特徴的な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005802"},{"id":"00005805","register_sub_id":"101","register_pk":"106792","name":"森医院味噌蔵","kana":"もりいいんみそぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96726676,"lng":138.3470147,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0217","desc":"主屋西側の増築部の南側に接続し，北側を正面とする。桁行３．６ｍ，梁間３ｍ，土蔵造２階建，切妻造，桟瓦葺。外壁はモルタル塗及び鉄板張とする。主屋や病院棟の建築以前に建てられており，納屋と共にかつての屋敷構えの景観を留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005805"},{"id":"00005812","register_sub_id":"101","register_pk":"106799","name":"森医院門","kana":"もりいいんもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96749315,"lng":138.34690369,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、間口3.8m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0221","desc":"敷地北東面の前面道路に面して立つ表門。柱間３．８ｍ，高さ２．８ｍ，石造。３０㎝角の石柱を基壇上に建て，表面を小叩き仕上げとし，隅部は磨き仕上げ，頂部は半球形に成形する。扉はもともと設けない。広大な敷地の入口を画し，格式ある表構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005812"},{"id":"00011112","register_sub_id":"101","register_pk":"205219","name":"良寛記念館回廊","kana":"りょうかんきねんかんかいろう","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542377,"lng":138.688263,"geo_status":"db","era":"昭和39","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、延長23m","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0454","desc":"管理棟と展示棟を結ぶ回廊。南側に壁を建て、片持状に床と屋根を張り出す。両棟と相まって庭を画するのみならず、展示棟を聖なる世界に見立て、その媒介としての強い意義を与えられていたと伝えられ、記念館全体の空間構成を有機的にまとめる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011112"},{"id":"00011111","register_sub_id":"101","register_pk":"205218","name":"良寛記念館管理棟","kana":"りょうかんきねんかんかんりとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542432,"lng":138.688465,"geo_status":"db","era":"昭和39／昭和47・平成17改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積80㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0453","desc":"切妻造平入の平屋建で、敷地の前面側に建つ南北棟。北寄りに外部階段を設けて玄関とし、南側に来館者の受付機能と事務室を配する。南西隅以外の濡縁、緩やかな屋根と深い軒の出、開口部の縦格子が意匠上の特徴で、谷口の得意な現代の和風表現を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011111"},{"id":"00011110","register_sub_id":"101","register_pk":"205217","name":"良寛記念館展示棟","kana":"りょうかんきねんかんてんじとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542378,"lng":138.687931,"geo_status":"db","era":"昭和36／昭和60・平成17改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積135㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0452","desc":"生誕地である出雲崎町において、良寛の遺墨などを展示するために建てられた記念館。設計は谷口吉郎。切妻造妻入平屋建で、東西北の各面に濡縁を巡らす。全体に建ちが低く、周辺環境とよく馴染む。谷口の特徴をよく表す鉄筋コンクリート造和風表現の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011110"},{"id":"00012890","register_sub_id":"101","register_pk":"504381","name":"桂湯","kana":"かつらゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県南砺市城端字大工町590他","lat":36.51420556,"lng":136.90153056,"geo_status":"db","era":"昭和5年頃／昭和37年・同41年・同52年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺及び金属板葺、建築面積155㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 147","desc":"旧城端町中心部の短冊形敷地に建ち、東から脱衣場棟、浴場棟、住居棟を並べる。脱衣場棟は木造二階建、正面銅板張の階境に蛇腹、軒に切妻破風を付し、中央の上部隅切の開口部に男女別出入口をまとめる。門前町の景観に彩りを添える洋風意匠のもと銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012890"},{"id":"00004226","register_sub_id":"101","register_pk":"105216","name":"富山市郷土博物館（富山城）","kana":"とやましきょうどはくぶつかん（とやまじょう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市本丸1-62","lat":36.69275781,"lng":137.21184698,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造4階建、瓦葺、建築面積725㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.07.23(平成16.07.23)","register_no":"16 － 0070","desc":"富山城跡南西寄り，二の丸から本丸への正面入口の石垣上に建つ。鉄筋コンクリート造４階建で，入母屋造の望楼をのせた３層４階からなる天守，２層２階の小天守状櫓など，城郭意匠で纏めている。地域の景観の核として，広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004226"},{"id":"00002030","register_sub_id":"101","register_pk":"103020","name":"廣野医院","kana":"ひろのいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県滑川市寺家町254","lat":36.76466469,"lng":137.33719009,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0057","desc":"住宅主屋北面に接続し，通り側を正面とした２階建の洋風建築。正面はクリーム色モルタル仕上げ壁面と鼠色洗出し仕上げの腰や隅部及び軒廻りで構成し，他面を下見板張りとする。正面妻飾に洋風の繊細な彫物や鬼板を用い，昭和初期の意匠をよくあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002030"},{"id":"00014475","register_sub_id":"101","register_pk":"513889","name":"石川県立能楽堂能舞台","kana":"いしかわけんりつのうがくどうのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市石引四丁目390-2","lat":36.55962778,"lng":136.663325,"geo_status":"db","era":"昭和6年／同46年移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積79㎡、橋掛り付","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"17 - 0311","desc":"兼六園南側に所在する能楽堂内にある舞台。入母屋造の典型的な能舞台で橋掛りを含み、観客席側は檜皮葺で背面杉皮葺。柱等の化粧材は台湾檜、足元の延石は戸室石を用い、時代性と地域性を示す。後座鏡板の松図は玉井敬泉画。加賀藩以来の能文化を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014475"},{"id":"00005814","register_sub_id":"101","register_pk":"106801","name":"上野家住宅旧診療所","kana":"うえのけじゅうたくきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市石引1-15-31","lat":36.55389317,"lng":136.67251679,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"2006.10.19(平成18.10.19)","register_no":"17 － 0157","desc":"道路に面して建ち，桁行４間，梁間４間半，木造２階建，宝形造，桟瓦葺とする。外壁のモルタル塗に横目地を入れ，４本のピラスターを設け，レリーフや持送りを飾り，石造建築風のファサードを形成する。地方の近代化を示す指標となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005814"},{"id":"00012322","register_sub_id":"101","register_pk":"531646","name":"鴨ヶ浦塩水プール","kana":"かもがうらえんすいぷーる","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県輪島市輪島崎町","lat":37.40685,"lng":136.89791667,"geo_status":"db","era":"昭和10年頃／昭和24年・同30年頃改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造一部コンクリート造、面積345㎡","structure_material":"石造一部コンクリート造","registered":"2018.05.10(平成30.05.10)","register_no":"17-282","desc":"輪島市街近傍の鴨ヶ浦海岸にある水泳用の屋外プール。岩礁を縦25メートル横13メートルに削孔し、縁辺部をコンクリートで整える。南北に設けた取排水口から海水が自然に流出入する仕組み。立地特性を生かした類例稀なスポーツ施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012322"},{"id":"00014236","register_sub_id":"101","register_pk":"509626","name":"呉竹文庫主屋","kana":"くれたけぶんこおもや","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47885,"lng":136.47915833,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0304","desc":"手取川河口に所在する実業家が設立した私設図書館の主屋。木造平屋建、切妻造桟瓦葺で、外壁は真壁白漆喰塗り。内部は片廊下で、広縁と次の間を備える表座敷、仏間を備える奥座敷、床柱に白樺を用いた数寄屋風の造りの角座敷を配する。上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014236"},{"id":"00014237","register_sub_id":"101","register_pk":"509627","name":"呉竹文庫書庫及び閲覧室","kana":"くれたけぶんこしょこおよびえつらんしつ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47878333,"lng":136.47901389,"geo_status":"db","era":"大正4年頃／昭和3年増築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積173㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0305","desc":"手取川河口に所在する私設図書館の土蔵造書庫と木造閲覧室棟。二階建で屋根を一体とする。書庫は腰壁モルタル洗出仕上、戸口に掛子塗扉を開く。一階に書棚を設置、二階書斎は重厚な洋風意匠。閲覧室棟は一階蔵前を閲覧室、二階は数寄屋風の床付き座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014237"},{"id":"00014239","register_sub_id":"101","register_pk":"509629","name":"呉竹文庫茶室","kana":"くれたけぶんこちゃしつ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47895833,"lng":136.47931389,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0307","desc":"手取川河口に所在する私設図書館に実業家が建築した茶室。切妻造桟瓦葺で、三面に庇を回して土縁とし、土縁と茶室境は引違障子で開放的にする。茶室は三畳で床の脇に洞口で仕切る一畳大の小室を付す。壁に埋め込む呉竹を床柱にするなど床構えが独創的な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014239"},{"id":"00014238","register_sub_id":"101","register_pk":"509628","name":"呉竹文庫土蔵","kana":"くれたけぶんこどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47895833,"lng":136.4792,"geo_status":"db","era":"明治22年頃／平成2年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0306","desc":"手取川河口に所在する実業家が建設した元着物蔵。土蔵造二階建、切妻造平入、桟瓦葺で、外壁は西面を腰石張、他を下見板張とする。各階とも一室で板敷きとし、一階の戸口に鏝絵を施した掛子塗扉と、豪壮な鳥居枠を構える。図書館開設より前に建設した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014238"},{"id":"00015181","register_sub_id":"101","register_pk":"530605","name":"赤井家住宅新診療所","kana":"あかいけじゅうたくしんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39-1","lat":36.07845833,"lng":136.40001111,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0251","desc":"主屋の南西に位置し、通りに南面して建つ診療所。木造平屋建寄棟造桟瓦葺で、外壁は軒までクリーム色モルタル吹付仕上。内部は玄関の東に薬局と診療室、北の廊下沿いに待合と休養室を配す。天井高と同高の軒を廻らし、縦長窓を並べるモダンな外観の診療所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015181"},{"id":"00015180","register_sub_id":"101","register_pk":"530604","name":"赤井家住宅病室棟（旧診療所）","kana":"あかいけじゅうたくびょうしつとう（きゅうしんりょうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39","lat":36.07861667,"lng":136.40001667,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0250","desc":"主屋の西に南面して建つ、内・外科医院の病室棟で旧診療所。切妻造平入桟瓦葺で正面に玄関を付し、東南の渡廊下で主屋と接続する。内部は中廊下の東西に各２室を配し、北に洗面及び便所棟を付す。外壁下見板張とし、洋風意匠の外観が地域医療の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015180"},{"id":"00001187","register_sub_id":"101","register_pk":"102177","name":"井上歯科医院","kana":"いのうえしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市京町3-50","lat":35.90399929,"lng":136.16411982,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造２階建，瓦葺，建築面積62㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"18 － 0012","desc":"市の中心部に鎮座する総社大社の北方に位置する。明治３６年の大火後の建築で、土蔵造りとするが、外観意匠を洋風とする点に特徴がある。玄関回りのトスカナ式柱型や櫛型ペジメントなどの左官仕上げは石動芳次郎の仕事とされる。棟梁は地元の田倉藤太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001187"},{"id":"00004538","register_sub_id":"101","register_pk":"105528","name":"越前市武生公会堂記念館（旧武生公会堂）","kana":"えちぜんしたけおこうかいどうきねんかん（きゅうたけおこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市蓬莱町8-8","lat":35.90175846,"lng":136.16831828,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部4階地下1階建、建築面積601㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階一部4階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"18 － 0036","desc":"南側及び東側が接道する敷地に南面して建つ。鉄筋コンクリート造地上２階建地下１階建で，南東部に６層の塔屋を配す。武生市では初期の本格的鉄筋コンクリート造で，塔屋のランドマーク性を強調する垂直線意匠や，楕円等を用いた１階玄関の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004538"},{"id":"00008684","register_sub_id":"101","register_pk":"149405","name":"旧昭和会館（今庄地区公民館今庄分館）","kana":"きゅうしょうわかいかん（いまじょうちくこうみんかんいまじょうぶんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県南条郡南越前町今庄75字東中町6","lat":35.77287446,"lng":136.19741881,"geo_status":"db","era":"昭和6年／昭和62年改修","year":1931,"year_source":"converted","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積382㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0105","desc":"旧北国街道から少し東に入った位置に西面して建つ。鉄筋コンクリート造3階建で、西正面からは2階建に見える。中央にポーチを構え、左右対称の正面を造る。等間隔に柱型を現し、各階とも大きく窓を穿つ。簡明な外観のなか、柱頭飾りが効果的に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008684"},{"id":"00006455","register_sub_id":"101","register_pk":"107438","name":"高鳥歯科医院診療所兼主屋","kana":"たかとりしかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県小浜市小浜鹿島19","lat":35.493347,"lng":135.738983,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0050","desc":"小浜漁港に向かう通りに東面して建つ。正面５間半、奥行５間の木造２階建で、２階南側３間分を診療所部とする。屋根は小屋根を戴くマンサード風とし、外部はモルタル洗出しで石目地を切って洋風に仕上げ、窓下等に煉瓦タイルを貼ってアクセントをつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006455"},{"id":"00012732","register_sub_id":"101","register_pk":"367635","name":"谷集会場","kana":"たにしゅうかいじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県勝山市北谷町谷87字中手外地6","lat":36.06088028,"lng":136.50062778,"geo_status":"db","era":"昭和28年／平成23年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、金属板葺、建築面積66㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"18 － 198","desc":"旧北谷郵便局南側の高台に牛首街道を挟んで西面して建つ。木造二階建、半切妻造鋼板葺妻入で、正面中央に切妻造の車寄を付す。外壁は下見板張で、正面二階に縦長窓を配し、大壁造の妻に三本の縦桟と鎧窓をあしらう。洒落た外観が特徴的な谷集落の象徴的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012732"},{"id":"00008670","register_sub_id":"101","register_pk":"149391","name":"深谷家住宅洋館","kana":"ふかやけじゅうたくようかん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県勝山市元町1-937他","lat":36.05946411,"lng":136.50109524,"geo_status":"db","era":"明治12年／明治前期増築","year":1879,"year_source":"converted","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積331㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0091","desc":"旧勝山城下に所在する。桁行14ｍ梁間12ｍ総2階建の東面に15畳の座敷が張り出す。起り屋根の寄棟造桟瓦葺で、2階の外壁を軒裏まで漆喰塗とし、街道に面する西面にはアーチ形の縦長窓を並べる。文明開化の世相を反映した元診療所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008670"},{"id":"00011947","register_sub_id":"101","register_pk":"211091","name":"福井市自然史博物館旧館（旧福井市立郷土博物館）","kana":"ふくいししぜんしはくぶつかんきゅうかん（きゅうふくいしりつきょうどはくぶつかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県福井市足羽上町147-1","lat":36.056693,"lng":136.20942,"geo_status":"db","era":"昭和27年／平成4年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積178㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"18-183","desc":"足羽山北東の山頂に建つ。鉄筋コンクリート造で、正面は玄関庇や各階の窓で水平性を、右端をカーテンウォールで垂直性を強調しながら、一階外壁は鉄平石張で積雪対策も講じる。階段廻りや屋上の天文台に旧規をよく留める。戦災・震災復興の記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011947"},{"id":"00008683","register_sub_id":"101","register_pk":"149404","name":"明治殿","kana":"めいじでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県南条郡南越前町今庄76字南中町6-1","lat":35.7727132,"lng":136.19615803,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"converted","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0104","desc":"公園の後方に東面して建つ。入母屋造妻入銅板葺、桁行7.6ｍ梁間6.5ｍの木造平屋建。正面に唐破風造向拝を出す。方柱で舟肘木、二軒半繁垂木。正面は中央に桟唐戸をたて、両脇に独特の花頭窓を穿つ。風格ある外観のなか、兎毛通しに繊細な彫刻が配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008683"},{"id":"00001072","register_sub_id":"101","register_pk":"102062","name":"旧今井医院","kana":"きゅういまいいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県大月市初狩町中初狩221","lat":35.59596806,"lng":138.88083695,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造２階建，建築面積185㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"19 － 0032","desc":"甲州街道に面して建つ木造，モルタル仕上げ，陸屋根の建物で，コンクリート造に似た外観とする点に特徴がある。柱形や窓上の部分等は目地を入れて石造風にみせている点や，コーニスを模して軒に廻した幾何学的な連続装飾も，時代の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001072"},{"id":"00012332","register_sub_id":"101","register_pk":"531656","name":"旧加茂内科医院表門及び塀","kana":"きゅうかもないかいいんおもてもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60919167,"lng":138.46691389,"geo_status":"db","era":"大正4年頃／昭和47年・平成12年移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長13m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-108","desc":"街道に面した敷地東面を区切る。表門は間口二・四メートルの腕木門で、切妻造桟瓦葺、肘木付の腕木で軒桁を受け、一軒疎垂木を配る。塀は真壁造で漆喰塗の腰板張とし、屋根を桟瓦葺とする。落ち着きのある表構えで、街道沿いの歴史的な景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012332"},{"id":"00012330","register_sub_id":"101","register_pk":"531654","name":"旧加茂内科医院診療所兼主屋","kana":"きゅうかもないかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60920556,"lng":138.46716667,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-106","desc":"旧小笠原宿内の短冊状の敷地中央に東面して建つ。二階建の入母屋造妻入で切妻起屋根の玄関を付ける。一階が診療所と居室、二階が座敷で、診療所の受付や待合室、診察室にはガラス窓を多用し、採光等に配慮する。大正期の地方診療施設の様相をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012330"},{"id":"00012331","register_sub_id":"101","register_pk":"531655","name":"旧加茂内科医院土蔵","kana":"きゅうかもないかいいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60924444,"lng":138.46748333,"geo_status":"db","era":"大正4年頃／昭和20年頃移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-107","desc":"敷地奥に建つ。木造平屋建、切妻造桟瓦葺平入で、北面に戸口二箇所を開く。内部は、東室を土間、西室を板床とする。外壁はモルタル仕上で、鉄板張の板戸や鉄格子を入れた窓など防盗の配慮が窺える。近代診療施設における附属建物の有様を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012331"},{"id":"00001603","register_sub_id":"101","register_pk":"102593","name":"旧下山療院","kana":"きゅうしもやまりょういん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町下山1871","lat":35.41607373,"lng":138.44295176,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造3階建、瓦葺、建築面積131㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"19 － 0040","desc":"中廊下型平面からなる住宅兼用の病院建築。東側の街道に面して１階玄関，山側の背面に２階玄関を構える。もとは，２階南半に待合室・診療室・薬局を配し，１階各室を病室とする。身延山系東山麓の斜面の地形を利用した建築として間取や外観に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001603"},{"id":"00000043","register_sub_id":"101","register_pk":"101033","name":"甲府法人会館（旧甲府商工会議所）","kana":"こうふほうじんかいかん（きゅうこうふしょうこうかいぎしょ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市中央4-12-21","lat":35.65711885,"lng":138.57183032,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積519㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1996.12.20(平成8.12.20)","register_no":"19 － 0001","desc":"現存する山梨県最古の鉄筋コンクリート造のビルで，設計及び施工は内藤半次郎（内藤工業所）である。２階・３階を通した列柱の柱型をもつ外観の意匠に特徴がある一方，各種の機能を巧みに配した建築計画等に現代建築への萌芽がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000043"},{"id":"00009271","register_sub_id":"101","register_pk":"194064","name":"杉浦家住宅旧医院","kana":"すぎうらけじゅうたくきゅういいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64036586,"lng":138.53259886,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積145㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0069","desc":"敷地東側に建つ。東西棟の入母屋造二階建と南北棟の入母屋造平屋建からなる。建築面積一四五平方メートル、南に入母屋造の玄関を張出す。外壁は赤味を帯びた漆喰塗で腰はモルタル刷毛引き仕上げとして縦長窓を連続させる。内部に調剤室などを配する医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009271"},{"id":"00009270","register_sub_id":"101","register_pk":"194063","name":"杉浦家住宅主屋","kana":"すぎうらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64032065,"lng":138.53237995,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積168㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0068","desc":"敷地中央に建つ。寄棟造桟瓦葺で、建築面積一六八平方メートル。北、東面に屋敷蔵と旧医院への廊下や角屋を延ばす。南面に唐破風造の式台玄関を構える。建ちは高く、南面西半分から西面に下屋を張出して縁を廻し、二階は三面に窓を開ける開放的な構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009270"},{"id":"00000240","register_sub_id":"101","register_pk":"101230","name":"大正館倉庫（旧大正館）","kana":"たいしょうかんそうこ（きゅうたいしょうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県上野原市上野原1404","lat":35.62673666,"lng":139.11661567,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積232㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"19 － 0014","desc":"甲州街道旧上野原宿の東側に建つ映画館。昭和63年まで現役であったが、現在は倉庫となっている。木造２階建、下見板張りの建築であるが、ファサードはモルタル塗りとし、横連窓を配しており、インターナショナルスタイルの影響が見られる早い事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000240"},{"id":"00011503","register_sub_id":"101","register_pk":"210532","name":"𣇃米公民館","kana":"つきよねこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡富士川町𣇃米1237","lat":35.5719,"lng":138.44771111,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0098","desc":"緩やかな斜面地に建つ。木造平屋建、入母屋造桟瓦葺で、南側正面には起り屋根の庇を設ける。南寄りに舞台を備える六〇畳大の集会室とし、北半には畳敷き数室を配する。公民館建築としては比較的大規模なもので、今日まで地域で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011503"},{"id":"00016381","register_sub_id":"101","register_pk":"536448","name":"上條産婦人科医院","kana":"かみじょうさんふじんかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市城東一丁目176-2","lat":36.23825278,"lng":137.97336667,"geo_status":"db","era":"大正4年／大正後期増築、昭和後期改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0675","desc":"市街地中心部の旧片端町に位置する産婦人科医院。全体雁行平面で南西に玄関ポーチを付し、一階中廊下の西は医院部、東は居住部とする。診療室は金属板装飾天井や腰タイル貼など上質な仕上。上下窓に櫛形ペディメントを付した洋風の外観が地域景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016381"},{"id":"00006598","register_sub_id":"101","register_pk":"107581","name":"旧草間歯科医院","kana":"きゅうくさましかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田2-29-4","lat":36.39660881,"lng":138.25729834,"geo_status":"db","era":"大正中期／平成16改修","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"20 － 0312","desc":"主屋の東方に位置し，西面して建つ。桁行３間，梁間２間半，土蔵造２階建，切妻造，桟瓦葺。小屋組は和小屋。外観は中塗仕上げで，出入口枠を丁寧に形づくり，前面に庇を設け，繰形を施した持送りを付ける。全体として簡素なつくりでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006598"},{"id":"00007027","register_sub_id":"101","register_pk":"108009","name":"旧鈴木歯科診療所（片岡山荘）","kana":"きゅうすずきしかしんりょうじょ（かたやまさんそう）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字西屋敷裏外167-15","lat":36.359276,"lng":138.632965,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積135㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"20 － 0333","desc":"敷地中央に南面して建つ旧別荘兼歯科診療所。切妻造鉄板葺の木造２階建、建築面積１３５㎡。食堂が拡張され、東側テラスが室内化されているが、全体として外観をよく残す。弁柄色系のペンキで塗装された鎧下見板の外壁に白色の窓枠のコントラストが映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007027"},{"id":"00016513","register_sub_id":"101","register_pk":"574875","name":"旧銭湯玉の湯","kana":"きゅうせんとうたまのゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県下伊那郡阿智村駒場1085-8","lat":35.44382778,"lng":137.74741361,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積105㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0685","desc":"集落中心部に東面して建つ銭湯。北半の二階建入母屋造は浴場で、内部に脱衣場と男女浴室を設け、外観は上下窓を配して、ドイツ壁の腰に橙色の洗出など洋風の意匠。南半の二階建切妻造は座敷棟で入母屋造玄関を構えた対照的な外観。山間集落を彩る戦前の銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016513"},{"id":"00014003","register_sub_id":"101","register_pk":"508263","name":"旧松岡医院","kana":"きゅうまつおかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大手五丁目1319-5他","lat":36.23509444,"lng":137.9751,"geo_status":"db","era":"大正13年／平成29年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0590","desc":"松本城下に位置。木造二階建、寄棟造桟瓦葺。パラペットを立上げモルタルに目地を切り石造にみせ、縦長上下窓を並べ、幾何学装飾を付す。一階はホール・診療室の洋室と仏間等の和室を破綻なく並置する。二階は和室病室。装飾を凝らした洋風医院兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014003"},{"id":"00012530","register_sub_id":"101","register_pk":"367825","name":"旧松髙産婦人科医院表門及び塀","kana":"きゅうまつたかさんふじんかいいんおもてもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田二丁目172-5、172-1","lat":36.394562,"lng":138.257034,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"表門 石造、間口2.2m 塀 石造及びコンクリート造、総延長15m","structure_material":"表門 石造","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0533","desc":"敷地前面にあり、大正館の玄関正面に表門を開き、東西に塀を延ばす。表門は花崗岩製、各頂部灯具付の門柱で、高さ間口とも2･2メートル。塀は成の低いコンクリート製で、柱と笠石に凝灰岩を用いる。丁寧なつくりで、洋式医院の気品ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012530"},{"id":"00012529","register_sub_id":"101","register_pk":"367824","name":"旧松髙産婦人科医院大正館","kana":"きゅうまつたかさんふじんかいいんたいしょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田二丁目172-5、172-1","lat":36.394562,"lng":138.257034,"geo_status":"geocoded","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、金属板葺、建築面積33㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0532","desc":"上田市街東部の住宅地にある診療所兼住宅の診察棟。敷地東北辺に北面して建つ木造二階建、寄棟造鉄板葺で、玄関上に入母屋造の庇を付す。正面軒中央の半円アーチや二階窓上のペディメントなど大ぶりの意匠が特徴的な洋館で、地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012529"},{"id":"00015185","register_sub_id":"101","register_pk":"530609","name":"旧横内医院","kana":"きゅうよこうちいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大字島立字門田1867-1","lat":36.22650556,"lng":137.94171389,"geo_status":"db","era":"昭和7年／昭和40年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部地階付、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部地階付","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0661","desc":"上高地線大庭駅の南方に位置し、敷地に東面して建つ医院兼主屋。正面は円柱を立て、起り付き入母屋造の玄関ポーチを付し、外壁モルタル塗洗出仕上、腰は石張風とする洋風医院で、背面に和風主屋を接続。診療室、薬局等の設えを残し、地域医療の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015185"},{"id":"00016383","register_sub_id":"101","register_pk":"536450","name":"小諸市立藤村記念館","kana":"こもろしりつとうそんきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県小諸市丁字本丸裏315-1","lat":36.32735833,"lng":138.41765,"geo_status":"db","era":"昭和33年／昭和45年増築","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0677","desc":"小諸城址懐古園内に南面して建つ島崎藤村の記念館。設計は谷口吉郎。木造平屋建、切妻造平入桟瓦葺。正面は格子を並べ、東半は吹放ちの石敷土間。内部の大半は展示室とし、玉砂利洗出仕上の土間とする。緩勾配屋根と簡素な和風意匠が公園内の景観と調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016383"},{"id":"00001516","register_sub_id":"101","register_pk":"102506","name":"信濃教育会生涯学習センター","kana":"しなのきょういくかいしょうがいがくしゅうせんたー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市豊科高家796-3","lat":36.27211234,"lng":137.92843687,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、銅板葺、建築面積428㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"20 － 0035","desc":"県内の教育活動推進のために建設された旧信濃教育会館本館を長野市内から移築したもの。木造２階建，左右対称型で，正面中央に車寄をつけ，屋根窓付マンサード屋根を載せる。設計は宮原工務店の小林弥吉，施工は県内の官庁建築物を多く手がけた宮本長作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001516"},{"id":"00010141","register_sub_id":"101","register_pk":"197974","name":"下伊那教育会館","kana":"しもいなきょういくかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市仲ノ町303-1","lat":35.516186,"lng":137.830036,"geo_status":"db","era":"昭和13／昭和56改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積342㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0451","desc":"飯田城下の武家地にあたる仲ノ町に建つ木造二階建で、一階を事務室等、二階を講堂とする。正面屋根中央にマンサードの破風を見せて壁面を幾何意匠で飾り、左右にドーマー窓を配る。外壁は下見板張で縦長窓を連続させる。地域のランドマークとなる洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010141"},{"id":"00010142","register_sub_id":"101","register_pk":"197975","name":"下伊那教育会土蔵","kana":"しもいなきょういくかいどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県飯田市仲ノ町303-1","lat":35.516275,"lng":137.830213,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0452","desc":"会館の北背面に南面して建つ。桁行三間、梁間二間半とし、正面に下屋を設ける。漆喰塗の壁面は、鉢巻下方まで下屋柱とも海鼠壁とし、腰高の印象を持たせる。もとは幕末以降の教育資料を収蔵していた建物で、下伊那地域の教育史を語る上でも重要な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010142"},{"id":"00008992","register_sub_id":"101","register_pk":"162352","name":"諏訪市美術館（旧懐古館）","kana":"すわしびじゅつかん（きゅうかいこかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市湖岸通り4-693-8","lat":36.04777658,"lng":138.11314298,"geo_status":"db","era":"昭和18年","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建、瓦葺、建築面積440㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0389","desc":"上諏訪温泉中心部に所在する片倉館の敷地内に建ち、建築面積４００㎡、木造二階建、入母屋造桟瓦葺である。内外ともコンクリート造風の大壁とし、全体を和風意匠でまとめる。洋風意匠の片倉館と相まって、諏訪湖畔独特の景観に貢献している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008992"},{"id":"00009951","register_sub_id":"101","register_pk":"196098","name":"諏訪市文化センター（旧北澤会館）","kana":"すわしぶんかせんたー（きゅうきたざわかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県諏訪市湖岸通り5-1018-1他","lat":36.04459981,"lng":138.11126238,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積2239㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0445","desc":"中庭で劇場部分と会館部分を二分する平面を持つ。海鼠壁状の壁面仕上げや、格子風のルーバー、ベランダ手摺を菱形断面として高欄風に作るなど、鉄筋コンクリート造を主体としたモダニズム建築に、和風要素を付加した表現とする。吉田五十八の円熟期の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009951"},{"id":"00002922","register_sub_id":"101","register_pk":"103912","name":"高遠閣","kana":"たかとおかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県伊那市高遠町東高遠2295","lat":35.833481,"lng":138.063766,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積790㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"20 － 0106","desc":"町中心部，国史跡高遠城跡内に位置する，町民の集会場及び観光客の休憩施設として建設された施設。木造２階建，鉄板葺，入母屋造の大規模な造りで，千鳥破風，唐破風などを備えつつも，内部・開口部・車寄せなどに近代的要素を示す。伊藤文四郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002922"},{"id":"00003539","register_sub_id":"101","register_pk":"104529","name":"ふれあい館しらふじ（旧丸田医院）物置","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ものおき","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65374397,"lng":138.31448336,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積41㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0143","desc":"主屋と洋館に挟まれた中庭東にあり，もとレントゲン室であった。東西棟の切妻造，桟瓦葺，妻入，一部２階建の土蔵造という伝統的な形式になり，中庭側の下屋を廊下とし，主屋や洋館と連続する。地方における近代医院の建築構成を知る上で，貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003539"},{"id":"00003538","register_sub_id":"101","register_pk":"104528","name":"ふれあい館しらふじ（旧丸田医院）洋館","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ようかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65364324,"lng":138.314392,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0142","desc":"医院開業当時の診療棟で，中庭を挟んで主屋南側にたつ。木造平屋建，東西棟の寄棟造，桟瓦葺，妻入で，内部は４室になる。軒蛇腹は白漆喰塗，他を黒漆喰塗とした土蔵造で，柱型や長押型をあらわした外壁，小壁の額縁飾や窓枠の蛇腹など，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003538"},{"id":"00009952","register_sub_id":"101","register_pk":"196099","name":"南内田公民館","kana":"みなみうちだこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県塩尻市大字片丘字若宮4156他","lat":36.15243426,"lng":137.98255891,"geo_status":"db","era":"昭和22／昭和23改修","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、瓦葺、建築面積264㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0446","desc":"道路沿いに東面して建つ木造の公民館。主体部は入母屋造二階建で、南北に張出す平屋部分も入母屋造として、各々東面に玄関を構え、風格ある外観を呈する。戦後新築されたものとして県内最古の公民館建築であり、地域住民の生活拠点として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009952"},{"id":"00016669","register_sub_id":"101","register_pk":"579153","name":"碌山美術館グズベリーハウス","kana":"ろくざんびじゅつかんぐずべりーはうす","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高5095-1","lat":36.343932,"lng":137.881836,"geo_status":"db","era":"昭和43年／平成9年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、石置板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0693","desc":"碌山美術館開館１０周年を記念して建てた展示室兼休憩室。払下げの枕木を積んで壁体とし、切妻屋根は石置板葺風モルタル塗の独特な外観。小屋はキングポスト・トラスとし、屋根東面に天窓を開ける。建設工事に地域の教員や学生が奉仕した山小屋風の展示施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016669"},{"id":"00016670","register_sub_id":"101","register_pk":"579154","name":"碌山美術館美術の倉","kana":"ろくざんびじゅつかんびじゅつのくら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高5095-1","lat":36.343781,"lng":137.881801,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"木造平屋建、石置板葺風モルタル塗、建築面積7.2㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0694","desc":"開館１０周年を記念して建てた収蔵庫。煉瓦造基礎の高床で払下げの枕木を積上げて壁体とする。切妻屋根は石置板葺風モルタル塗で、破風板上部に多数の十字架を飾る独特な外観。建設工事に地域の教員や学生が奉仕し、小規模ながら敷地景観を特徴付ける収蔵庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016670"},{"id":"00007991","register_sub_id":"101","register_pk":"128823","name":"碌山美術館碌山館","kana":"ろくざんびじゅつかんろくざんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県安曇野市穂高5095-1他","lat":36.34370221,"lng":137.88139659,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積116㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"20-0354","desc":"東面して建つＲＣ造平屋建で、外壁に焼き過ぎ煉瓦を貼る。切妻造妻入とし、主棟正面にポーチを付け、屋根はＳ字型瓦で葺き、銅板葺の尖塔を中心に建てる。側面には半円アーチ窓を連続させ、正背面にバラ窓を開ける。キリスト教会聖堂のイメージを反映した建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007991"},{"id":"00007994","register_sub_id":"101","register_pk":"128826","name":"旧飯地公民館（五毛座）","kana":"きゅういいじこうみんかん（ごもうざ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県恵那市飯地町字中下185-1","lat":35.48202392,"lng":137.28950177,"geo_status":"db","era":"昭和26／昭和36・昭和40・昭和48頃・平成14改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積427㎡","structure_material":"木造2階一部地下1階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0173","desc":"南と西に接道し、南面して建つ。木造２階一部地下１階建、建築面積４２７㎡ 。南北棟の半切妻造桟瓦葺。正面は下見板張で、中央に寄棟屋根を付け入口ポーチとする。内部は花道を備えた舞台や、客席の平土間や桟敷席を設け、地芝居小屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007994"},{"id":"00009279","register_sub_id":"101","register_pk":"194072","name":"旧河合療院","kana":"きゅうかわいりょういん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町弐之町3-19","lat":36.2343085,"lng":137.18688551,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造一部土蔵造2階建、鉄板葺、建築面積426㎡","structure_material":"木造一部土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0200","desc":"通りに南面して診療所を設け、後方に居住部、病室の順に配し、土間に土蔵を建てる。木造二階建、建築面積三六五平方メートル。大オーダー風の柱形をドイツ壁とし、各間に縦長の上下窓と幾何意匠をあしらう。古川の町並みに映える瀟洒な洋風意匠の医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009279"},{"id":"00014013","register_sub_id":"101","register_pk":"508273","name":"旧須田歯科医院","kana":"きゅうすだしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市桜町98","lat":36.14633611,"lng":137.26114444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"21 - 0292","desc":"高山市街江名子川右岸に建つ医院兼住宅。道路からやや引いて東面し、木造二階建、寄棟造平入で、東面中央を玄関とし張り出す。外壁は下見板張、南・東面に両開き縦長窓を開ける。内部は一階洋風、二階和風。町家の並ぶ高山にあって、大正期の洋風志向を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014013"},{"id":"00000825","register_sub_id":"101","register_pk":"101815","name":"旧林療院看護婦棟","kana":"きゅうはやしりょういんかんごふとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74951054,"lng":136.95879429,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造２階建，鉄板葺，建築面積41㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0015","desc":"本館の左手に位置し，これと接続して建つ木造２階建の建物。内部は１，２階とも小部屋に区画され天井高も低い。もとの足軽長屋を改造したものといわれる簡素な佇まいの建屋で，全体に旧態を良く伝えている。地方医院の歴史を知る上で欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000825"},{"id":"00000773","register_sub_id":"101","register_pk":"101763","name":"旧林療院本館","kana":"きゅうはやしりょういんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74944611,"lng":136.95867468,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造２階建，瓦葺，建築面積116㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"21 － 0013","desc":"木造二階建の擬洋風の外観で知られた医院で，玄関ポ－チはイオニア式オーダーの円柱を立てる。軸組は伝統的な和風で仕上げるが，建物の隅や腰壁は石造風に見せるモルタル仕上げとし，上げ下げ窓の窓枠頂部に簡略のペジメントを付けるなどの工夫が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000773"},{"id":"00000826","register_sub_id":"101","register_pk":"101816","name":"旧林療院レントゲン棟","kana":"きゅうはやしりょういんれんとげんとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74937086,"lng":136.95871838,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造２階建，鉄板葺，建築面積22㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0016","desc":"本館棟の背後に建つ小規模な２階建の洋風建物で，１階は土蔵風になるが，全体として本館棟を意識した意匠にまとめる。岐阜県下でレントゲン施設が最も早く設置された例と伝え，地方都市で当時最新の医療が施されたことを知ることができる貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000826"},{"id":"00002042","register_sub_id":"101","register_pk":"103032","name":"旧堀谷医院","kana":"きゅうほりやいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県郡上市八幡町大手町804","lat":35.75163762,"lng":136.95659521,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積60㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"21 － 0036","desc":"旧郡上八幡城に近接する市街地に位置する。木造２階建，外壁コンクリート洗出しで，繰形の上に２階が張り出す。１階に大きなアーチ形窓，２階に上げ下げ窓を設け対照的な開口形式をとる。玄関ポーチの持送りと正面欄間に漆喰で意匠を凝らし見所とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002042"},{"id":"00000048","register_sub_id":"101","register_pk":"101038","name":"名和昆虫博物館","kana":"なわこんちゅうはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市千畳敷大道西308-1","lat":35.43316309,"lng":136.77316051,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積183㎡","structure_material":"煉瓦造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"21 － 0001","desc":"桟瓦葺切妻屋根の煉瓦造建築で，ギリシャ神殿風屋根妻を模した車寄せ玄関と，奈良唐招提寺の解体修理時にもらい受けた３本の丸柱が意匠上の特徴である。設計は当時名古屋高等工業学校の校長であった武田五一であり，彼の作風を示す建物の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000048"},{"id":"00001774","register_sub_id":"101","register_pk":"102764","name":"旧五十嵐歯科医院","kana":"きゅういがらししかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市清水区蒲原3-23-3","lat":35.11981034,"lng":138.60328787,"geo_status":"db","era":"大正3頃／昭和16増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"22 － 0070","desc":"旧東海道筋に建つ木造２階建の洋風建築。在来の町屋の間取りを残しつつ，外観と内装一部が改造された。寄棟造瓦葺で硝子窓の開口部を広くとり，その他壁面を下見板張とし，玄関及び増築された西棟正面に軒板飾を付ける。地元の大工吉田源吉の設計と伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001774"},{"id":"00008695","register_sub_id":"101","register_pk":"149416","name":"旧木村家住宅主屋","kana":"きゅうきむらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県賀茂郡河津町峰603","lat":34.75514705,"lng":138.98288554,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部平屋建、瓦葺、建築面積304㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"22 － 0177","desc":"北に川を望む庭園内に建つ。木造2階1部平屋建、建築面積三304㎡。基礎まわりをタイル貼とし、壁はベージュ色のモルタル洗出し仕上げ、緑釉の桟瓦を葺き、所々に出窓を付け、ポーチなどに節のある磨丸太を使う。抑制のきいた意匠になる別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008695"},{"id":"00008694","register_sub_id":"101","register_pk":"149415","name":"旧順天堂田中歯科医院診療所兼主屋","kana":"きゅうじゅんてんどうたなかしかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県富士市吉原3-3510-6","lat":35.16418492,"lng":138.68615879,"geo_status":"db","era":"明治中期／大正14年移築増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積187㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"22 － 0176","desc":"通りに西面する敷地の東寄りに建つ。洋館と和館からなり、屋根は鉄板葺、建築面積187㎡。洋館は2階1部平屋建で、屋根寄棟造とし、6角形平面でドーム型の屋根や、急勾配の屋根を付設する。下見板張で、縦長の上下窓を配する。町中の洋館として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008694"},{"id":"00005276","register_sub_id":"101","register_pk":"106264","name":"神山復生病院事務所棟","kana":"こうやまふくせいびょういんじむしょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県御殿場市神山1910-8","lat":35.23858521,"lng":138.92306269,"geo_status":"db","era":"明治中期／昭和中期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積72㎡、地下室付","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"22 － 0107","desc":"病院敷地のほぼ中央に南面して建つ。切石積の基礎にのる木造２階建で，地下１階を設け，屋根は鉄板葺とし，正側面に下屋庇を付ける。正面中央入口には切妻造の玄関ポーチを突出し，外壁は下見板張とする。開院当初の歴史的な景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005276"},{"id":"00013400","register_sub_id":"101","register_pk":"368485","name":"ＹＭＣＡ東山荘齊藤記念館","kana":"わいえむしーえーとうざんそうさいとうきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県御殿場市深沢字丸嶽2013-5","lat":35.28866944,"lng":138.95636667,"geo_status":"db","era":"昭和40年／平成2年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部地下1階建、建築面積632㎡","structure_material":"鉄筋コンクリート造地上2階一部地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"22 － 0288","desc":"敷地西寄りに建つ、南北に長い平面の鉄筋コンクリート造で、中央南寄りに玄関を張出す。ラーメン構造を現し、水平軒を強調した立面などモダニズムの特徴を示しつつ、二階屋根に勾配をつけ、玄関ホールなど要所を自然石貼とするなど、内外観に変化をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013400"},{"id":"00013399","register_sub_id":"101","register_pk":"368484","name":"ＹＭＣＡ東山荘フィッシャー館","kana":"わいえむしーえーとうざんそうふぃっしゃーかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県御殿場市東山字池上1049-3他","lat":35.28942222,"lng":138.95775833,"geo_status":"db","era":"昭和25年／平成22年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積136㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"22 － 0287","desc":"西面し、広場越しに富士山を望む。平屋建の応接室棟と居室棟を渡廊下で接続し、前者は暖炉を備えた応接室と居間、後者は和室と水回りからなる。両棟とも開口を広く取り、外壁は腰高に下見板を張り、小壁と水平な軒裏を漆喰塗とする。落ち着いた佇まいの施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013399"},{"id":"00001912","register_sub_id":"101","register_pk":"102902","name":"旧井上家住宅西洋館","kana":"きゅういのうえけじゅうたくせいようかん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊田市平戸橋町波岩86-100","lat":35.1225478,"lng":137.19002514,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"23 － 0047","desc":"博覧会の貴賓館として名古屋に建造されたと伝わる。その後用途を変えつつ，移築･増改築された。木造2階建，寄棟造桟瓦葺，外装下見板貼のベランダ付洋館で，連子格子･上げ下げ･引違･回転と多様な開口部形式をとる。軒板飾，高欄に擬洋風建築の意匠を窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001912"},{"id":"00003989","register_sub_id":"101","register_pk":"104979","name":"旧今泉医院診療棟","kana":"きゅういまいずみいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.80809,"lng":137.314728,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積221㎡","structure_material":"木造平屋一部2階建","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0130","desc":"敷地西端に西面して建つ。正面は左右対称の洋風意匠で統一し，中央部のみ２階を設ける。前面中央には洋風の車寄せを張り出し，上部に病院名を記す額を掲げている。屋根は寄棟造，桟瓦葺で，外壁はドイツ壁とする。洋風意匠を導入した病院建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003989"},{"id":"00003991","register_sub_id":"101","register_pk":"104981","name":"旧今泉医院手洗い場","kana":"きゅういまいずみいいんてあらいば","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.80810189,"lng":137.3146331,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"コンクリート造、面積1.8㎡","structure_material":"コンクリート造","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0132","desc":"診療所前庭に位置する手洗い場。当時の農村地域の病院に良く設けられていたもので，患者が病院に入る前に使用していた。当初は井戸水を水源とし，診療所東側の高架水槽から配水していた。昭和初期の病院の在り方を，今日に伝える工作物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003991"},{"id":"00003990","register_sub_id":"101","register_pk":"104980","name":"旧今泉医院病室棟","kana":"きゅういまいずみいいんびょうしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.808216,"lng":137.31485,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0131","desc":"診療棟の北東隅に接して建つ。切妻造，桟瓦葺で，西端に土間玄関を開く。内部は６畳の病室３室を配し，東の１室のみ床を備え，病室の南北には板縁を通す。診療棟と異なり和風意匠で統一し，平面も伝統的な構成に準ずる。病院建築の発展過程を示す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003990"},{"id":"00010804","register_sub_id":"101","register_pk":"201639","name":"旧岡田医院給水塔","kana":"きゅうおかだいいんきゅうすいとう","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966968,"lng":136.865183,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、高さ3.9m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0447","desc":"主屋北側中央に隣接している。鉄筋コンクリート造、高さ二・八メートルの柱四本を内転びに立て、平面が一・四×一・一メートル、高さ一・一メートルの貯水槽を支える。診療所と住居の一日分の井戸水を貯め、各所に供給した。近代の生活を物語る構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010804"},{"id":"00010802","register_sub_id":"101","register_pk":"201637","name":"旧岡田医院蔵","kana":"きゅうおかだいいんくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967126,"lng":136.865266,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0445","desc":"敷地北東部の入口に建つ。木造二階建、南北棟の切妻造桟瓦葺で、一階を下見板張、二階をドイツ壁風仕上げのモルタル塗とする。弓状の梁を用いた小屋で、隅を火打梁で固める。窓の鉄格子、小庇の装飾鋳物の持送り、漆喰塗の内壁など、丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010802"},{"id":"00010800","register_sub_id":"101","register_pk":"201635","name":"旧岡田医院主屋","kana":"きゅうおかだいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966935,"lng":136.865252,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0443","desc":"敷地中央に位置し、南に築かれた庭園に面して建つ。東西に細長い木造二階建、入母屋造桟瓦葺で、小屋はトラス組である。軒を出桁造、ガラス戸を多用した開放的なつくりになる。中廊下式の一階平面、洋風応接室やサンルームを設ける点に時代的特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010800"},{"id":"00010801","register_sub_id":"101","register_pk":"201636","name":"旧岡田医院診療所棟","kana":"きゅうおかだいいんしんりょうじょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967014,"lng":136.865389,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0444","desc":"主屋東に接続し、北面に主屋と併用の玄関を設ける。北半を二階建、南半を平屋建、寄棟造桟瓦葺とし、一階は診療室や処置室、二階は看護婦居室である。横溝彫付で煉瓦色の一階外壁やコーニスを廻した二階外壁など洋風意匠で、特色ある地域景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010801"},{"id":"00010803","register_sub_id":"101","register_pk":"201638","name":"旧岡田医院道具蔵","kana":"きゅうおかだいいんどうぐぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966905,"lng":136.865069,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0446","desc":"木造二階建、南北棟の切妻造桟瓦葺で、東面に下屋庇を設け、小屋はトラス組とする。一階外壁は扉口のある東面がモルタル塗、南面と西面が下見板張、街路側北面が竪目地付モルタル塗、二階は石積風の疑似モルタル塗である。敷地の北西隅の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010803"},{"id":"00010805","register_sub_id":"101","register_pk":"201640","name":"旧岡田医院塀","kana":"きゅうおかだいいんへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967053,"lng":136.865131,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、総延長33m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0448","desc":"蔵から道具蔵の間に設けている。谷積風の石積基礎上に立上げた高さ約一・九メートルの鉄筋コンクリート造の塀で、約二・三メートル間隔に柱形を設け、その間をアーチ形の壁で連結し、ほぼ中間に非常用通路を設ける。敷地北辺の独特な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010805"},{"id":"00014615","register_sub_id":"101","register_pk":"515157","name":"旧常滑市立陶芸研究所（とこなめ陶の森陶芸研究所）正門","kana":"きゅうとこなめしりつとうげいけんきゅうじょ（とこなめとうのもりとうげいけんきゅうじょ）せいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県常滑市奥条七丁目22","lat":34.88651111,"lng":136.85036944,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造、間口5.0m、延長11m","structure_material":"コンクリートブロック造","registered":"2023.08.07(令和5.08.07)","register_no":"23 - 0588","desc":"本館同様、堀口捨己の設計にかかる陶芸研究所の正門。鉄格子戸を左右にスライドさせる間口五メートルの門扉と、門扉から矩折に控えた左右対称のコンクリートブロック塀からなる。門扉上部の板に打抜かれた極太明朝体の「常滑陶芸研究所」の文字が力強い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014615"},{"id":"00014614","register_sub_id":"101","register_pk":"515156","name":"旧常滑市立陶芸研究所（とこなめ陶の森陶芸研究所）本館","kana":"きゅうとこなめしりつとうげいけんきゅうじょ（とこなめとうのもりとうげいけんきゅうじょ）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県常滑市奥条七丁目22","lat":34.88685833,"lng":136.85054722,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積203㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2023.08.07(令和5.08.07)","register_no":"23 - 0587","desc":"堀口捨己設計の陶芸研究所。鉄筋コンクリート造２階建で、紫タイル貼の外壁にバルコニーや庇を張出して水平性を強調。内部は階段ホール西にトップライト付の展示室、東に事務室や会議室等。赤と金を配す応接室や銀の展示室等、色使い含め設計者の個性が光る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014614"},{"id":"00015464","register_sub_id":"101","register_pk":"533479","name":"創垂館","kana":"そうすいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県小牧市堀の内一丁目2","lat":35.29125,"lng":136.91384722,"geo_status":"db","era":"明治21年／昭和24年移築、令和4年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0616","desc":"史跡小牧山の中腹にある尾張徳川家の旧迎賓施設。南面して建つ寄棟造桟瓦葺で南面西寄りに式台玄関を付す。西を土間の供待所と勝手、東を続き間座敷とし、東・南に入側の広縁と竹の濡縁を廻らし庭を望む。広い式台など格式を備え、良材を用いた上質な座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015464"},{"id":"00010160","register_sub_id":"101","register_pk":"197993","name":"蘇山荘","kana":"そざんそう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.184286,"lng":136.932195,"geo_status":"db","era":"昭和12／昭和12移築・平成16改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0408","desc":"木曽材の宣伝を目的に名古屋汎太平洋平和博覧会の迎賓館和館として建設され、閉会後に移築された。車寄付玄関の南側に八畳、北側に台所等を配し、西奥に客間三室を配する。ヒノキやサワラ等、木曽の良材をふんだんに利用し見応えがあり、室内意匠を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010160"},{"id":"00000212","register_sub_id":"101","register_pk":"101202","name":"徳川美術館本館","kana":"とくがわびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.18353273,"lng":136.93320313,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上1階地下1階建，瓦葺，建築面積506㎡","structure_material":"鉄骨鉄筋コンクリート造地上1階地下1階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0003","desc":"設計競技の１等案をもとに吉本与志雄が実施設計を行った。施工は竹中工務店。外観の意匠は城壁を思わす外壁を巡らし、屋根は緑色釉薬瓦葺とし鯱を置く。全体としていわゆる帝冠様式のデザインをもつ建物で、尾張徳川家の所蔵品を展示する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000212"},{"id":"00000213","register_sub_id":"101","register_pk":"101203","name":"徳川美術館南収蔵庫","kana":"とくがわびじゅつかんみなみしゅうぞうこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.18354247,"lng":136.93357388,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建，瓦葺，建築面積250㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0004","desc":"本館とともに吉本与志雄が実施設計を行った。施工は竹中工務店。本館の西側に位置する中規模の鉄筋コンクリート造階建の収蔵庫。切妻造、本瓦葺で、開口部がほとんど無い大壁造風の建物である。本館に接続しともに重厚な外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000213"},{"id":"00000792","register_sub_id":"101","register_pk":"101782","name":"豊橋市公会堂","kana":"とよはししこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通2-22","lat":34.76804673,"lng":137.39222025,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1202㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0015","desc":"市制２５周年の記念建造物に相応しく，大階段・コリント式列柱による玄関ロッジア・両脇の階段室が堂々たる正面ファサードをつくる。階段室の半球ドームと四方に配置された羽ばたく大鷲がシンボル。静岡や浜松の公会堂を手がけた中村與資平の設計になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000792"},{"id":"00011710","register_sub_id":"101","register_pk":"210726","name":"中村公園記念館","kana":"なかむらこうえんきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中村区中村町字高畑","lat":35.17479,"lng":136.854221,"geo_status":"db","era":"明治43年／大正期・昭和25年頃・同33年・同45年・同50年・平成28年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0480","desc":"迎賓館として建てられたもので、Ｌ字型平面の木造平屋建。正面中央に唐破風造の車寄を張り出し、四周に下屋を廻らす。西側は和室三室を並べ、吟味された良材を用い、座敷飾りを備え、天井高の高い空間と共に、迎賓館としての風格を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011710"},{"id":"00013401","register_sub_id":"101","register_pk":"368486","name":"名古屋市公会堂","kana":"なごやしこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞一丁目101","lat":35.15677778,"lng":136.91911944,"geo_status":"db","era":"昭和5年／昭和33年・同55年・平成31年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上4階地下1階建、建築面積2765㎡","structure_material":"鉄骨鉄筋コンクリート造地上4階地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0548","desc":"名古屋市鶴舞公園内に位置し、昭和天皇御成婚記念事業で建てた。外観は茶系の落ち着いた色調で整え、最上階の円形アーチ窓や隅部の丸み等、ロマネスク的表現とする。内部は、三層吹抜の大ホールを中心に各室を配す。初期の鉄骨鉄筋コンクリート造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013401"},{"id":"00006337","register_sub_id":"101","register_pk":"107320","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立愛知病院正門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりつあいちびょういんせいもんおよびそとべい）","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.15711211,"lng":136.92098502,"geo_status":"db","era":"大正3／昭和5・平成11改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 石造門柱2基、間口4.2m、塀 煉瓦造、総延長16m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0247","desc":"名古屋大学鶴舞キャンパス敷地の南辺にあり、道路を挟んで鶴舞公園に面する。門柱は花崗岩の方柱で、新築病棟の柱にそのデザインが引用されている。塀は昭和５年にスクラッチタイルとテラコッタで改修したもので、当時のデザイン傾向が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006337"},{"id":"00006373","register_sub_id":"101","register_pk":"107356","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立愛知病院通用門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりつあいちびょういんつうようもんおよびそとべい）","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.15666517,"lng":136.92224554,"geo_status":"db","era":"大正後期／昭和5改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 石造門柱2基、間口7.4m、塀 煉瓦造、総延長55m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0248","desc":"名古屋大学鶴舞キャンパス敷地の南東にある。門柱、塀とも煉瓦造で昭和５年にスクラッチタイルとテラコッタで改修された。タイルは釉薬が施され、高いデザイン感覚とともに材料品質もよい。テラコッタ装飾は立体的かつ幾何学的な意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006373"},{"id":"00001113","register_sub_id":"101","register_pk":"102103","name":"西尾市岩瀬文庫書庫","kana":"にしおしいわせぶんこしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町474","lat":34.87442045,"lng":137.05347681,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造地下１階地上３階建，瓦葺，建築面積80㎡","structure_material":"煉瓦造地下１階地上３階建","registered":"1999.06.07(平成11.06.07)","register_no":"23 － 0022","desc":"地元出身の豪商岩瀬弥助が，収集した蔵書を市民に閲覧できるようにつくった文庫の書庫として建てられた。煉瓦の外壁を基調に窓の上部や窓台等にアクセントとして石材を用いた外観はよく整っている。内部は木組みで柱を立て３層に床を張り蔵書を納めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001113"},{"id":"00001114","register_sub_id":"101","register_pk":"102104","name":"西尾市立図書館おもちゃ館（旧岩瀬文庫児童館）","kana":"にしおしりつとしょかんおもちゃかん（きゅういわせぶんこじどうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町474","lat":34.87390794,"lng":137.05341439,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積57㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"23 － 0023","desc":"岩瀬文庫の児童館として建てられた。木造平屋建の小規模な洋風建築で，下見板貼りの外壁，ハーフティンバー風の妻飾，縦長の上下窓等に特徴がある。児童用の施設にふさわしいデザインで，現在も児童用の施設として使われている点にもみどころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001114"},{"id":"00002045","register_sub_id":"101","register_pk":"103035","name":"羽田八幡宮蔵（旧羽田八幡宮文庫）","kana":"はだはちまんぐうくら（きゅうはだはちまんぐうぶんこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市花田町字斉藤56-3","lat":34.76497066,"lng":137.37653386,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"23 － 0051","desc":"近代的図書館の先駆とされる羽田八幡宮文庫の書庫。桁行３間，梁行２間の規模，切妻造，桟瓦葺，平入の標準的なつくりの平屋建土蔵で，書庫らしく南面に小さな窓を設けただけの閉鎖的な構えをとり，東面に１間幅の戸口を設けて社務所離れに繋げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002045"},{"id":"00002046","register_sub_id":"101","register_pk":"103036","name":"羽田八幡宮門（旧羽田八幡宮文庫正門）","kana":"はだはちまんぐうもん（きゅうはだはちまんぐうぶんこせいもん）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市花田町字斉藤58","lat":34.76477096,"lng":137.37653314,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造、瓦葺、間口3m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"23 － 0052","desc":"豊橋駅西口近く，北西方に位置する羽田八幡宮の参道中程に西面して建つ。正面全幅１０尺ほどで中央１間分を通路とし，両側２尺づつは腰を板張とした土壁とする。桟瓦葺の切妻屋根を架けた簡素な腕木門であるが，由緒ある文庫位置の目印として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002046"},{"id":"00006767","register_sub_id":"101","register_pk":"107749","name":"三谷町北区山車蔵","kana":"みやちょうきたくやまぐら","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県蒲郡市三谷町七舗153-1他","lat":34.815315,"lng":137.24561372,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積35㎡","structure_material":"煉瓦造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0254","desc":"通りに西面して敷地を占め、前面に引き回しの場を設ける。煉瓦造で、桁行・梁間とも５．９ｍの規模で、切妻造桟瓦葺とする。山車を収蔵するため、開口部はアーチ頂部まで６ｍ高に及び、銅板張の両開戸をたてる。煉瓦造の山車蔵という数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006767"},{"id":"00003666","register_sub_id":"101","register_pk":"104656","name":"明治村北里研究所本館","kana":"めいじむらきたざとけんきゅうじょほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34156,"lng":136.991684,"geo_status":"db","era":"大正4／昭和55移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、スレート葺一部銅板葺、建築面積360㎡、塔屋付","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0079","desc":"木造２階建の洋風建築。天然スレート葺の腰折れ屋根に櫛形の屋根窓を置く。玄関上には段状破風と八角小塔を飾る。外壁は下見板張で，腰壁と軒下小壁を竪羽目板張とし，上げ下げ窓まわりに柱形を表す。玄関車寄は縦溝付の角柱で支え，パラペットを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003666"},{"id":"00003662","register_sub_id":"101","register_pk":"104652","name":"明治村清水医院","kana":"めいじむらしみずいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34177783,"lng":136.98897136,"geo_status":"db","era":"明治30代／昭和48移築","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、柿葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0075","desc":"土蔵造２階建，切妻造，平入で木曽檜のこけら葺とする。隅に柱型を付け，外壁の漆喰に目地を切って石造風に見せるなど洋風を意識した意匠をもつ。開口部は櫛形アーチだが，窓は引込み戸である。１階は通り土間式平面，２階は数寄屋風座敷と内部は和風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003662"},{"id":"00003858","register_sub_id":"101","register_pk":"104848","name":"明治村日本赤十字社中央病院病棟","kana":"めいじむらにほんせきじゅうじしゃちゅうおうびょういんびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34304926,"lng":136.99102585,"geo_status":"db","era":"明治23／昭和49移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0092","desc":"木造平屋建，寄棟造，桟瓦葺で，棟に換気塔を置く。煉瓦造の高い基礎に建ち，廊下を高床に造る。外壁はドイツ下見で，ハーフティンバー風に柱形をつける。病室は欄間付の上げ下げ窓に両開鎧戸，廊下は引違ガラス窓で小壁に革紐装飾を施す。設計は片山東熊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003858"},{"id":"00003859","register_sub_id":"101","register_pk":"104849","name":"明治村日本赤十字社中央病院付属便所","kana":"めいじむらにほんせきじゅうじしゃちゅうおうびょういんふぞくべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.3430597,"lng":136.99121322,"geo_status":"db","era":"明治23／昭和49移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0093","desc":"木造平屋建，寄棟造，桟瓦葺で棟上に切妻屋根の換気塔を載せる。切石基礎上に建ち，外壁はドイツ下見で，ハーフティンバー風に柱形で飾り，小壁に山形模様を刻む。妻側に上げ下げ窓，平側に引違窓を開く。設計は片山東熊。小規模だが細部まで意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003859"},{"id":"00001275","register_sub_id":"101","register_pk":"102265","name":"車山蔵","kana":"やまぐら","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券779","lat":35.38399831,"lng":136.93963283,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積37㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0033","desc":"犬山祭りの際にくりだす山車の格納蔵。間口４．５５ｍ、桁行８．２２ｍ規模の木造平屋建、瓦葺切妻屋根、妻入の建屋で、桁高は７ｍある。棟梁は犬山藩御用大工の系譜を継ぐ市橋清次郎で、水平筋違や側壁の筋違などに洋風建築技術の導入が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001275"},{"id":"00005079","register_sub_id":"101","register_pk":"106069","name":"龍影閣（旧名古屋博物館品評所）","kana":"りょうえいかく（きゅうなごやはくぶつかんひんぴょうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市熱田区神宮1-1-1","lat":35.125832,"lng":136.90802,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積295㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"23 － 0055","desc":"博覧会場の品評所として建設。木造２階建，寄棟造の和風建築で，階下に１８畳と１６畳半の座敷，階上に１０畳と上段付８畳（明治天皇御座所）を配置し，四周に廊下を巡らし，奥に階段室を設ける。棟梁は鈴木幸右衛門で，初期博覧会施設の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005079"},{"id":"00009021","register_sub_id":"101","register_pk":"162381","name":"石薬師文庫閲覧所","kana":"いしやくしぶんこえつらんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県鈴鹿市石薬師町字中町1707-3","lat":34.90356659,"lng":136.54766596,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0111","desc":"佐佐木信綱生家土蔵の東、旧東海道沿いに建つ。Ｌ字形棟の切妻造スレート葺で、入隅に下屋を設け、玄関とする。建築面積２９㎡。玄関奥を前室とし、その南に閲覧室を配する。クリーム色のモルタル外壁に大きく窓を穿ち、明るい内部空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009021"},{"id":"00014247","register_sub_id":"101","register_pk":"509637","name":"旧小渕医院診療棟","kana":"きゅうこぶちいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市一志町波瀬1969","lat":34.62723056,"lng":136.39236667,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0314","desc":"津市南西の農村に位置。平屋建寄棟造桟瓦葺。東正面に角柱で陸屋根の玄関ポーチを付け両脇に矩形窓を開ける。内部は玄関奥を待合室、脇に受付調剤室と診療室を配する。奥は中廊下両脇に内玄関や応接室、事務所を配す。洋風医院の典型で農村の小集落に希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014247"},{"id":"00014250","register_sub_id":"101","register_pk":"509640","name":"旧吉田医院主屋","kana":"きゅうよしだいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75774722,"lng":136.52741667,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積225㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0317","desc":"伊勢湾西岸の漁村に所在する医院。桟瓦葺の玄関棟、診療棟、居住棟で構成。診療棟は平屋建半切妻造。下見板張の上部をドイツ壁とし矩形窓を並べ、内部は診療室やレントゲン室を配す。居住棟は二階建入母屋造で各階とも田の字形で四室とる。洋風医院の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014250"},{"id":"00014251","register_sub_id":"101","register_pk":"509641","name":"旧吉田医院入院棟","kana":"きゅうよしだいいんにゅういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75764444,"lng":136.52753889,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0318","desc":"敷地の奥に位置し主屋と廊下で接続する。南北棟の平屋建寄棟造桟瓦葺で外壁は下見板張。内部は片廊下平面で入院室三室と、北端にお手伝い室を配する。入院室は引違ガラス戸の窓と押入を備える簡素なつくり。歴史的景観を構成する地域医院の要素として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014251"},{"id":"00014252","register_sub_id":"101","register_pk":"509642","name":"旧吉田医院門","kana":"きゅうよしだいいんもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75780833,"lng":136.52731389,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"石造、間口2.1m","structure_material":"石造","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0319","desc":"旧道に面して立つ医院正門。間口二・一メートル、高さ二・四メートルの一対の石柱を構え、間に鉄製アーチを架ける。石柱は江戸切仕上で柱頭を扁平な四角錐とし、アーチは渦巻き飾りを付けて中央に突針を立てる。洋風医院の表構えとして通り沿いの景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014252"},{"id":"00003103","register_sub_id":"101","register_pk":"104093","name":"旧四日市市立図書館","kana":"きゅうよっかいちしりつとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市諏訪栄町22-25諏訪公園内","lat":34.96865125,"lng":136.62196258,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積197㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"24 － 0046","desc":"地元の実業家熊沢一衛が四日市市に寄付した図書館で，設計は清水組の小笹徳蔵。鉄筋コンクリート造２階建，外観はスクラッチタイル張で比較的窓を大きく取る。繁華街に隣接した場所にあり，現在はこどもの家（児童館）として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003103"},{"id":"00007054","register_sub_id":"101","register_pk":"108036","name":"蔵前祭車庫","kana":"くらまえさいしゃこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県桑名市船馬町7","lat":35.068939,"lng":136.692627,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積34㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"24 － 0072","desc":"河岸屈曲部の橋の袂に建つ。建築面積３４㎡、鉄筋コンクリート造平屋建切妻造、鉄板瓦棒葺。妻面両端にパラペットを立ち上げ、外壁は柱型とスタッコ塗壁で構成し、小屋はハウトラスを組む。県内における初期の鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007054"},{"id":"00000830","register_sub_id":"101","register_pk":"101820","name":"神宮徴古館","kana":"じんぐうちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市神田久志本町1754-1","lat":34.48582886,"lng":136.7248766,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積1611㎡","structure_material":"煉瓦造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"24 － 0020","desc":"神宮の歴史資料を収集展示する目的で建てられた。設計は片山東熊・高山幸次郎で，煉瓦造に石貼仕上げとする端正な意匠の建物。平面は，中央ホ－ルとその奥の貴賓室，左右の翼屋を廊で繋ぐ構成になる。戦災後大改修されたが，外壁廻りは保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000830"},{"id":"00000831","register_sub_id":"101","register_pk":"101821","name":"神宮農業館","kana":"じんぐうのうぎょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市神田久志本町1754-1","lat":34.48679945,"lng":136.7243766,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積439㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"24 － 0021","desc":"農業の啓発と発展を目的として建てた施設。元はロの字型の平面であったが，近年の移築で中央部の宝形屋根の望楼の左右に翼屋を配し廊で繋ぐ前半部のみに縮小された。外観は和風で，内部架構は洋風にまとめる優れた技量がうかがえる。設計は片山東熊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000831"},{"id":"00009776","register_sub_id":"101","register_pk":"195605","name":"神武参剣道場","kana":"じんむさんけんどうじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市磯部町上之郷字上ノ里375-1他","lat":34.38015859,"lng":136.81030373,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0161","desc":"伊雑宮向かいの敷地に西面して建つ。木造二階建、入母屋造桟瓦葺で、一階周囲を下屋とし、正面中央に入母屋造の玄関を構える。柱上に舟肘木を載せ、壁は真壁漆喰塗で、腰を竪板張とする。内部は一階が祭壇付道場、二階は広間とする。風格ある外観をもつ武道場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009776"},{"id":"00005977","register_sub_id":"101","register_pk":"106962","name":"鈴屋遺蹟保存会旧事務所","kana":"すずのやいせきほぞんかいきゅうじむしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57659024,"lng":136.52586038,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0063","desc":"松阪城隠居丸跡南東に位置し，南東に面して建つ。桁行７間，梁間４間の規模で，木造平屋建，入母屋造，桟瓦葺。正面中央に銅板葺唐破風屋根の玄関を構え，奥に玄関ホール，南西端に洋間閲覧室，北西に座敷１０畳間を配す。近代和風の事務所建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005977"},{"id":"00005979","register_sub_id":"101","register_pk":"106964","name":"鈴屋遺蹟保存会正門","kana":"すずのやいせきほぞんかいせいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57538769,"lng":136.52619265,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右潜戸付","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0065","desc":"旧事務所南東に位置し，敷地北東正面に建つ。一間一戸の四脚門の形式をとり，屋根を切妻造，本瓦葺とする。左右に潜戸を付ける。柱を貫通した梁の頭を大仏様木鼻とし，梁中央に板蟇股を載せ，腕木の下を柱及び斗で支えるなど，特徴ある意匠と構造を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005979"},{"id":"00005978","register_sub_id":"101","register_pk":"106963","name":"鈴屋遺蹟保存会倉庫","kana":"すずのやいせきほぞんかいそうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.575397,"lng":136.52597,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0064","desc":"旧事務所の南西に北東に面して建つ。桁行３間，梁間２間の規模で，土蔵造２階建，寄棟造，桟瓦葺とし，正面に瓦葺の土庇をかけ，渡廊下で旧事務所と連絡する。基礎を煉瓦積，外壁を漆喰塗とし，外側を下見板で養生する。軒を深く出さずに落ち着いた外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005978"},{"id":"00005980","register_sub_id":"101","register_pk":"106965","name":"鈴屋遺蹟保存会塀","kana":"すずのやいせきほぞんかいへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57534043,"lng":136.52599191,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、総延長11m","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0066","desc":"旧事務所南西面から南西に本居宣長の旧宅まで延び，延長１１ｍで柱間を９間とする。正面の広場からの目隠しとなる。旧宅側の１間に出入口を設ける。木造で，腰を下見板張とし，上方に連子を嵌め，柱から腕木を出して瓦屋根を支え，重厚な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005980"},{"id":"00010826","register_sub_id":"101","register_pk":"201661","name":"中井家住宅主屋","kana":"なかいけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県名張市元町452","lat":34.620326,"lng":136.086943,"geo_status":"db","era":"昭和7／昭和40改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0227","desc":"市街地の角地に建つ、もと耳鼻咽喉科の医院建築で、木造二階建である。下見板張を基調とする外観は、上下階に並べた窓枠を縦に繋ぐ額縁で垂直線を強調し、上下の窓間を三分割して菱模様を飾るなど、幾何意匠でまとめる。街路のランドマークとなる洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010826"},{"id":"00000293","register_sub_id":"101","register_pk":"101283","name":"松阪市立歴史民俗資料館（旧飯南郡図書館）倉庫","kana":"まつさかしりつれきしみんぞくしりょうかん（きゅういいなんぐんとしょかん）そうこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1539","lat":34.57668316,"lng":136.52600906,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積20㎡","structure_material":"土蔵造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"24 － 0010","desc":"本館の東に隣接して建つ本館と同時に建設された２階建の土蔵。漆喰壁を下見板で覆い，外観の意匠を本館とあわせるが，高さを低く押さえている点は立ちの高い本館とは対照的である。市民の寄付でつくられた図書館の付属施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000293"},{"id":"00000292","register_sub_id":"101","register_pk":"101282","name":"松阪市立歴史民俗資料館（旧飯南郡図書館）本館","kana":"まつさかしりつれきしみんぞくしりょうかん（きゅういいなんぐんとしょかん）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1539","lat":34.57659024,"lng":136.52586038,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建，瓦葺，建築面積239㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"24 － 0009","desc":"松阪城跡公園の北端に建つ。木造，２階建で伝統的な和風の意匠をもち，左右に翼部，中央に玄関が突出した左右対称の構成に特徴がある。設計は清水義一である。近代における伝統的な和風建築の展開を知ることができる好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000292"},{"id":"00007053","register_sub_id":"101","register_pk":"108035","name":"楽翁公百年祭記念宝物館","kana":"らくおうこうひゃくねんさいきねんほうもつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県桑名市吉之丸9","lat":35.065273,"lng":136.69838,"geo_status":"db","era":"昭和9／昭和33改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積86㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"24 － 0071","desc":"神社境内の一隅に建つ。松平定信（楽翁）を顕彰する記念宝物館。建築面積８６㎡、鉄筋コンクリート造２階建。寄棟造桟瓦葺、正面に切妻破風を飾る。外壁は洗出し仕上げで、１階を石積風とし、２階は柱や長押型を表現するなど、和風意匠を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007053"},{"id":"00007752","register_sub_id":"101","register_pk":"108733","name":"アンドリュース記念館（旧近江八幡ＹＭＣＡ会館）","kana":"あんどりゅーすきねんかん（きゅうおうみはちまんわいえむしーえーかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市為心町中31","lat":35.13795563,"lng":136.09222125,"geo_status":"db","era":"昭和10／平成19改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"25-0277","desc":"八幡山東南の市街地に位置する。桁行１５ｍ梁間１１ｍの木造２階建、南北棟の入母屋造桟瓦葺。２階は南寄りに和室二室、北に洋室二室を並べ、中央を階段室等とする。釉薬瓦の赤とモルタル仕上げ壁の白が好対照をなし、親しみのある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007752"},{"id":"00008132","register_sub_id":"101","register_pk":"132530","name":"石田家住宅洋館（石田歯科医院）","kana":"いしだけいしだけじゅうたくようかん（いしだしかいいん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央1-409他","lat":35.00956718,"lng":135.86462812,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0283","desc":"浜通りに北面する洋館。東西棟の切妻造で、深緑色のスパニッシュ瓦を葺く。２階は中央に小さなバルコニーを設け、上部にタイルを縁取った丸い文様を飾り、切妻屋根を掛ける。外壁はグレーのリシン仕上げで、窓枠を薄桃色に塗る。伝統的な町並に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008132"},{"id":"00010179","register_sub_id":"101","register_pk":"198012","name":"ヴォーリズ記念病院旧本館（ツッカーハウス）","kana":"ゔぉーりずきねんびょういんきゅうほんかん（つっかーはうす）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町492","lat":35.152028,"lng":136.089106,"geo_status":"db","era":"大正7／昭和9改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積354㎡","structure_material":"木造2階一部3階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0348","desc":"中央の切妻造三階建の左右にのばす翼部両端を半八角形平面とする。玄関ポーチを半円アーチで構成し上部にベイウィンドウを開く。内部意匠にもヴォーリズの作風を示し、病室のおかれた二階開口を広めて通風採光に配慮するなど、結核病棟としての特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010179"},{"id":"00000980","register_sub_id":"101","register_pk":"101970","name":"近江八幡ユース・ホステル（旧蒲生郡勧業館）","kana":"おうみはちまんゆーす・ほすてる（きゅうがもうぐんかんぎょうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市円山町610","lat":35.16495665,"lng":136.08825157,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造２階建，瓦葺，建築面積329㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0103","desc":"明治中期以降流行しだす総二階木造和風の公共建築。真壁造で，腰を竪羽目とし，連続窓により立面をつくる。瓦葺入母屋の大屋根を架け，正面中央に唐破風の玄関を付ける。虹梁・笈形付大瓶束の玄関妻飾や内部の大階段などの凝った造りが見所となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000980"},{"id":"00008498","register_sub_id":"101","register_pk":"134894","name":"大津市旧大津公会堂","kana":"おおつしきゅうおおつこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市浜大津1-72-1","lat":35.01045707,"lng":135.86536471,"geo_status":"db","era":"昭和9年／昭和21年・昭和60年・昭和63年・平成22年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積430㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2011.01.26(平成23.01.26)","register_no":"25 － 0293","desc":"大津市の中心市街地に建つ。東西一七メートル南北二八メートルで、東面に車寄せを突き出す。鉄筋コンクリート造三階地下一階建、外壁スクラッチタイル貼。左右対称で、三階に半円アーチ窓、隅に円窓、一・二階に縦長窓を開け、格調ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008498"},{"id":"00011976","register_sub_id":"101","register_pk":"211111","name":"旧近江療養院希望館（五葉館）","kana":"きゅうおうみりょうよういんきぼうかん（ごようかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町字川西492","lat":35.15228,"lng":136.088525,"geo_status":"db","era":"大正7年／平成27年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"25-400","desc":"旧本館北側の斜面に建つ病棟。中央ラウンジの北を入口とし、南側に病室五室を放射状に配し、各病室の三面に窓を開いて通風と採光を確保する。外壁はドイツ壁で、窓に鎧戸をたて、ラウンジの屋根頂部に換気塔を載せる。独創的な形態をもつ個室型の結核療養施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011976"},{"id":"00014036","register_sub_id":"101","register_pk":"508296","name":"旧北村医院（李軒邸）井戸屋形","kana":"きゅうきたむらいいん（りけんてい）いどやかた","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.37486389,"lng":136.32827222,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0486","desc":"敷地南側、表門の内側東に建つ井戸屋形。切妻造桟瓦葺、軒は疎垂木小舞打。軸部は開放で洗い場入口を除き飛貫を入れる。正面両端柱に控柱を添える。南半に井戸、北半を洗い場とする。井戸上の化粧棟木下端には吊り金具が残る。医師宅の建物構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014036"},{"id":"00014037","register_sub_id":"101","register_pk":"508297","name":"旧北村医院（李軒邸）表門","kana":"きゅうきたむらいいん（りけんてい）おもてもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.37485278,"lng":136.32827222,"geo_status":"db","era":"元治2年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、間口2.6m","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0487","desc":"敷地南側に離れ座敷の東に接続して建つ薬医門。切妻造桟瓦葺。両脇に袖塀を設け、西側に潜戸を付す。桁行に比して梁間が大きい。袖壁は土壁で腰を竪板張。梁の木鼻に繰形を施す。扉は板唐戸で八双金具等を付ける。医師宅の表構えに相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014037"},{"id":"00014029","register_sub_id":"101","register_pk":"508289","name":"旧北村医院（李軒邸）主屋","kana":"きゅうきたむらいいん（りけんてい）おもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.374975,"lng":136.32814444,"geo_status":"db","era":"文政10年(1827)","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0479","desc":"長浜市街から東方の農村集落に南面して建つ医院建築。二階建切妻造桟瓦葺、正面中央に処置室を張出し診察棟と接続。東側に土間を配し、居室部は六間取平面で表側を医院とする。西端二間を書院座敷とし文人の書画で飾る。近世から続く医家の主屋として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014029"},{"id":"00014038","register_sub_id":"101","register_pk":"508298","name":"旧北村医院（李軒邸）車庫","kana":"きゅうきたむらいいん（りけんてい）しゃこ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37478333,"lng":136.32820833,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0488","desc":"離れ座敷の南にあり、東面する車庫。平屋建、正面入母屋背面切妻造桟瓦葺。妻飾りは木連格子、正面は襷桟付ガラス欄間を入れ、出入口を開放とするがもとは双折戸が入っていた。南面にガラス窓、北・西面に引違戸を設ける。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014038"},{"id":"00014030","register_sub_id":"101","register_pk":"508290","name":"旧北村医院（李軒邸）診療棟","kana":"きゅうきたむらいいん（りけんてい）しんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37486667,"lng":136.32815556,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0480","desc":"医院主屋南面から待合棟北面に接続する南北棟の診療棟。平屋建、入母屋造桟瓦葺で、壁は漆喰仕上で腰を洗出仕上。内部は診察室と薬局の二室で、受付カウンター・視線を遮る摺りガラス等に診療機能がみえる。近世主屋と共に医院建築の変遷を物語る近代診療棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014030"},{"id":"00014035","register_sub_id":"101","register_pk":"508295","name":"旧北村医院（李軒邸）土蔵","kana":"きゅうきたむらいいん（りけんてい）どぞう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37505556,"lng":136.328025,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0485","desc":"通りに面した敷地北西隅に建ち、主屋の縁と接続する土蔵。土蔵造二階建、切妻造桟瓦葺で置屋根の梁先に絵様繰形を施す。外壁は漆喰仕上で一階を竪板張とする。正面扉は観音開き鋼製扉を備え、一階北面に板葺庇付の窓を設ける。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014035"},{"id":"00014032","register_sub_id":"101","register_pk":"508292","name":"旧北村医院（李軒邸）西病棟","kana":"きゅうきたむらいいん（りけんてい）にしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37507778,"lng":136.32815,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0482","desc":"主屋の北側、裏門の西に接続して建つ病棟。二階建、切妻造桟瓦葺で東面に下屋を付し物入・便所とする。南面東端を入口及び階段とし、各階とも東西に六畳間を二室並べ南北面に窓を配す。二階は起り天井で釣床を備える。明治の医家の様相を伝える希少な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014032"},{"id":"00014031","register_sub_id":"101","register_pk":"508291","name":"旧北村医院（李軒邸）離れ座敷（待合棟）","kana":"きゅうきたむらいいん（りけんてい）はなれざしき（まちあいとう）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37483611,"lng":136.32816667,"geo_status":"db","era":"慶応4年(1868)／大正後期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0481","desc":"表門西隣で、診療棟南面に廊下で接続する和風医院建築。平屋建、寄棟造桟瓦葺。北面東端に入母屋造銅板葺の玄関庇を付す。中央に五畳半の待合、西に四畳半の書院座敷を並べる。面皮床柱や丸窓の意匠が座敷を印象付ける。当初隠居屋で医院建築の変遷を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014031"},{"id":"00014033","register_sub_id":"101","register_pk":"508293","name":"旧北村医院（李軒邸）東病棟","kana":"きゅうきたむらいいん（りけんてい）ひがしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37507778,"lng":136.32835833,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0483","desc":"敷地北東部に建つ南北棟の病棟。二階建、切妻造桟瓦葺で西・北面に庇を廻す。外壁は真壁造に竪板張。西面南端に入口とし、内部幅一間を土間とする。各階とも一〇畳間で北面を押入とし二階南西隅に便所を設ける。木部は弁柄塗。地域医療の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014033"},{"id":"00014034","register_sub_id":"101","register_pk":"508294","name":"旧北村医院（李軒邸）東病棟便所","kana":"きゅうきたむらいいん（りけんてい）ひがしびょうとうべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.375025,"lng":136.32831111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積4.2㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0484","desc":"東病棟の西側に建つ東西棟の便所。平屋建、切妻造桟瓦葺、壁は真壁造。正面は繰形付腕木で出桁とする。中央踏込み部の両側に個室を並べる。個室の床は赤色市松模様のタイル張。東個室は弁柄塗棹縁天井、西個室は漆喰塗込天井。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014034"},{"id":"00013132","register_sub_id":"101","register_pk":"368288","name":"旧常喜医院馬小屋","kana":"きゅうじょうきいいんうまごや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34733889,"lng":136.35439167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0446","desc":"敷地南面に開く門の近く、敷地の南東に西面して建つ。木造平屋建、切妻造桟瓦葺平入で、西面の桁行三間のうち中央一間を片引戸の出入口とする。出入口は馬に配慮してか、吊戸とし敷居は設けず、内法高も高い。長年地域医療に従事してきた医家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013132"},{"id":"00013128","register_sub_id":"101","register_pk":"368284","name":"旧常喜医院主屋","kana":"きゅうじょうきいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.347525,"lng":136.35417778,"geo_status":"db","era":"明治37年／大正14年頃・昭和5年頃増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0442","desc":"米原市南部の農村集落にある代々医者を務めた旧家の主屋で、敷地中央に南面して建つ。一階南側に張出した玄関回りに医院機能をまとめ、北側と二階を住居とする。数次に渡る改修の図面が残り履歴がわかる。地域医療を担い続けた医家の建築の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013128"},{"id":"00013129","register_sub_id":"101","register_pk":"368285","name":"旧常喜医院書院","kana":"きゅうじょうきいいんしょいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34744167,"lng":136.35401389,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0443","desc":"主屋の西側に建ち、北側の廊下を介して主屋と繋ぐ。入母屋造桟瓦葺の周囲に下屋を廻らし、南面と東面の下屋は畳廊下とする。南側に接客用の書院之間、北側に次之間と八畳間を並べ、次之間の北西隅に三畳の化粧室を張出す。地方医院の生活様式を反映している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013129"},{"id":"00013131","register_sub_id":"101","register_pk":"368287","name":"旧常喜医院西蔵","kana":"きゅうじょうきいいんにしのくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34764444,"lng":136.35410833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0445","desc":"主屋の北側に東面して建つ。東西棟の切妻造桟瓦葺、土蔵造二階建で、戸口前に下屋を設ける。外壁は東蔵と同様に、上部を漆喰塗、水切下を竪板張とする。内部は一、二階とも西側から一間の位置に片引戸を立て仕切る。屋敷北側背面の景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013131"},{"id":"00013130","register_sub_id":"101","register_pk":"368286","name":"旧常喜医院東蔵","kana":"きゅうじょうきいいんひがしのくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34762222,"lng":136.35434722,"geo_status":"db","era":"大正4年／昭和前期移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積21㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0444","desc":"主屋の北東に南面して建つ。東西棟の切妻造桟瓦葺、土蔵造二階建で、平入の戸口前に桟瓦葺の下屋を設ける。外壁は上部を漆喰塗、水切下を竪板張とする。内部は一、二階とも一室で、内壁は柱間に板を落し込む。西蔵とともに背面の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013130"},{"id":"00002410","register_sub_id":"101","register_pk":"103400","name":"旧水口図書館","kana":"きゅうみなくちとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町本町1-2-1","lat":34.96985398,"lng":136.17589663,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積52㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0179","desc":"町の中心地，水口小学校正門脇の角地に建つ。建物の北東側に塔屋を設けた鉄筋コンクリート造２階建。正面玄関の両脇にトスカナ式オーダーを配し，上部に薄彫を施した櫛形ペディメントを掲げる。太めの軒蛇腹が全体の外観を引き締める。ヴォーリズの設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002410"},{"id":"00014856","register_sub_id":"101","register_pk":"519116","name":"江北図書館（旧伊香郡農会庁舎）","kana":"こほくとしょかん（きゅういかぐんのうかいちょうしゃ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字西浦1362","lat":35.50649722,"lng":136.22250278,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積255㎡","structure_material":"木造2階一部平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"25 - 0521","desc":"木ノ本駅前に位置するかつての伊香郡農会の庁舎兼公会堂。二階建寄棟造桟瓦葺の東西棟で、南に玄関、西に平屋建の台所棟を付す。二階南面は中央をわずかに外部に突出させて切妻屋根を架ける。半円アーチの縦長窓とバットレスを並べた陰影深い外観が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014856"},{"id":"00003255","register_sub_id":"101","register_pk":"104245","name":"醒井公会堂","kana":"さめがいこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県米原市醒井字新町117、117-1","lat":35.329063,"lng":136.351501,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0215","desc":"江戸時代に宿場町として栄えた醒ヶ井の町並の中に所在する。木造平屋建，寄棟造桟瓦葺で，正面と側面前よりは吹きつけ壁，他は下見板張とする。正面隅はコーナーストーン風の仕上とするなど和洋のデザイン・構法を混在させた昭和初期公民館建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003255"},{"id":"00000137","register_sub_id":"101","register_pk":"101127","name":"滋賀大学陵水会館","kana":"しがだいがくりょうすいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市馬場1-1-1","lat":35.27735472,"lng":136.24568967,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階一部平屋建，瓦葺，建築面積292㎡","structure_material":"木造2階一部平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"25 － 0002","desc":"経済学部の前身の彦根高等商業学校同窓会館として建設された。設計はヴォーリズ。淡いクリーム色の外壁にスペイン瓦の屋根，ドア廻りのタイルによる市松模様など，スパニッシュスタイルでまとめられた外観に特徴があり，設計者の作風の一端がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000137"},{"id":"00013568","register_sub_id":"101","register_pk":"504931","name":"中川家住宅土蔵","kana":"なかがわけじゅうたくどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市地福寺町962","lat":35.37572222,"lng":136.27706389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0456","desc":"敷地南東に建つ能関連の衣装や道具などの収納蔵。二階建の土蔵造桟瓦葺で、西面に戸口を開く。外壁は漆喰で軒先まで塗込めて軒裏は垂木形を表し、腰に鉄板を張る。内部は板敷で、壁を竪板張とし、登梁形式の小屋組とする。敷地背面の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013568"},{"id":"00013567","register_sub_id":"101","register_pk":"504930","name":"中川家住宅能舞台","kana":"なかがわけじゅうたくのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市地福寺町962","lat":35.37582222,"lng":136.27701667,"geo_status":"db","era":"昭和6年／昭和39年増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0455","desc":"市南部にある能楽師の住宅。能舞台は敷地北東に建ち、南北棟で切妻造の本屋の四周に下屋を廻して北側下屋を楽屋とする。本舞台は桁行梁間共五・六メートルで、東に地謡座、北に後座と橋掛を設け、南と西に畳敷の見所を設ける。地域芸能を支えた近代能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013567"},{"id":"00000700","register_sub_id":"101","register_pk":"101690","name":"浅香山病院西病棟","kana":"あさかやまびょういんにしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区今池町3-3-16","lat":34.58509578,"lng":135.4907486,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積271㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0044","desc":"清水組大阪支店の設計施工。白塔棟の西端から矩折れに南に延び，創建時は女子の一等病室等にふりあてられていた。外壁面の凹凸やスカイラインに突起した塔屋小屋根などにスパニッシュに常套的なスペイン瓦の見せ所を意図的につくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000700"},{"id":"00000699","register_sub_id":"101","register_pk":"101689","name":"浅香山病院白塔","kana":"あさかやまびょういんはくとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区今池町3-3-16","lat":34.58511655,"lng":135.49125763,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造２階建塔屋付，瓦葺，建築面積627㎡","structure_material":"鉄筋コンクリート造２階建塔屋付","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0043","desc":"堺脳病院として建設。創立者の意向によりスパニッシュ・スタイルが採用された。スパニッシュのもつ明るいイメージや，白スタッコ壁の清潔さが好まれたのであろう。白塔はいわば事務所棟で，背後に平屋の病棟がパヴィリオン式に配置されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000699"},{"id":"00001080","register_sub_id":"101","register_pk":"102070","name":"梅谷歯科医院","kana":"うめたにしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西成区天下茶屋三丁目83","lat":34.6353966,"lng":135.49767447,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造３階建，スレート葺一部瓦葺，建築面積98㎡","structure_material":"木造３階建","registered":"1999.02.17(平成11.02.17)","register_no":"27 － 0057","desc":"木造３階建で道路に面して建ち，外観は１階をタイル貼り，２・３階を下見板張りとするなど洋風の意匠になる。内部は，伝統的な町家の平面を継承した形で，一部を除き和風とする。大阪の下町において洋風の意匠を積極的に取り入れた大正期建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001080"},{"id":"00000139","register_sub_id":"101","register_pk":"101129","name":"大阪倶楽部","kana":"おおさかくらぶ","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区今橋5-11","lat":34.69097102,"lng":135.49891853,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積795㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0015","desc":"開口部の小さい，壁を意識させる造形が特徴的。細部装飾にはインドやイスラムの影響が見られる。関西に多くの作品を残した安井武雄の片岡事務所時代の作品で，施工は大林組。プロポーションへの意識，装飾の取り扱いなど近代建築の黎明期の作品といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000139"},{"id":"00000299","register_sub_id":"101","register_pk":"101289","name":"大阪城天守閣","kana":"おおさかじょうてんしゅかく","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区大阪城1-1","lat":34.68734859,"lng":135.52600333,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造8階建，建築面積1199㎡","structure_material":"鉄骨鉄筋コンクリート造8階建","registered":"1997.09.03(平成9.09.03)","register_no":"27 － 0022","desc":"陸軍用地となっていた旧本丸一帯を公園化する計画に伴い，博物館として建設された。設計は市土木局建築課，施工は大林組による。鉄筋コンクリート造，地上６階地下２階建で，市民の寄付で建設されたこともあり，大阪のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000299"},{"id":"00010658","register_sub_id":"101","register_pk":"201232","name":"大阪市立美術館","kana":"おおさかしりつびじゅつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市天王寺区茶臼山町115","lat":34.650057,"lng":135.510505,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階地下1階建、瓦葺、建築面積4017㎡","structure_material":"鉄骨鉄筋コンクリート造3階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0613","desc":"天王寺公園の高台に建つ。正面に張出す玄関とホール部を一層分高い切妻造とし、左右の翼廊に展示室を配する。装飾を抑えた平滑で三層構成の立面を基調としつつ、壁頂の本瓦葺、蛇腹や窓の洋風装飾などに和洋の意匠を採取する。希少な戦前の大型美術館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010658"},{"id":"00006872","register_sub_id":"101","register_pk":"107854","name":"大阪大学待兼山修学館（旧大阪帝国大学医学部附属病院石橋分院本館）","kana":"おおさかだいがくまちかねやましゅうがくかん（きゅうおおさかていこくだいがくいがくぶふぞくびょういんいしばしぶんいんほんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市待兼山町1-4","lat":34.8066335,"lng":135.45169379,"geo_status":"db","era":"昭和6／平成19改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積793㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"27 － 0448","desc":"大阪府営繕課の設計による鉄筋コンクリート造３階建の病院建築。正面約８０ｍ規模で、南北に両翼を延ばした対称形の平面を採る。３階はもと病棟で、窓の外部に手摺を付ける。外観意匠は、縦長窓を規則的に配し、窓台を連続させ、庇をまわして水平線を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006872"},{"id":"00010003","register_sub_id":"101","register_pk":"196150","name":"大槻能楽堂能舞台","kana":"おおつきのうがくどうのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区上町2-1他","lat":34.67811104,"lng":135.52124786,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0579","desc":"能楽堂内に建つ能舞台。桁行梁間とも五・七メートル、切妻造妻入、檜皮葺で、右手に地謡座、背面に後座を設け、左手後方に橋掛が続く。舞台四方の頭貫上に中世風意匠の蟇股を置き、虹梁絵様や頭貫木鼻に華やかな渦紋を彫るなど、材工ともに質の高い能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010003"},{"id":"00000140","register_sub_id":"101","register_pk":"101130","name":"岸和田市立自泉会館（自泉館）","kana":"きしわだしりつじせんかいかん（じせんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市岸城町5-10","lat":34.46059811,"lng":135.37190387,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積539㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0016","desc":"大規模な事務所建築を得意とした渡辺節の作品。彼の作品の中では比較的小規模な住宅系のものとして注目に値する。装飾の少ないシンプルな外観であるが，列柱を配した玄関部などに様式建築のモチーフが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000140"},{"id":"00015042","register_sub_id":"101","register_pk":"529320","name":"旧朝日湯","kana":"きゅうあさひゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府泉佐野市元町4535-1","lat":34.41255,"lng":135.31433611,"geo_status":"db","era":"大正15年／令和4年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0913","desc":"孝子越街道に南面して建つ旧銭湯。片入母屋造平入桟瓦葺の脱衣場は庇中央を切上げ入口とし北に切妻造妻入桟瓦葺の浴室２棟、その北に土間の釜場を接続。西浴室は中央に御影石製の大浴槽を残し、上部はヴォールト天井を現すなど豪華なつくりの和洋折衷の銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015042"},{"id":"00011349","register_sub_id":"101","register_pk":"209186","name":"旧菅澤眼科病院","kana":"きゅうすがさわがんかびょういん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区土佐堀二丁目47-1他","lat":34.688323,"lng":135.49001,"geo_status":"db","era":"昭和4／昭和56・平成13頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積184㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0647","desc":"大阪市中心部の土佐堀地区に所在する病院建築。南東隅を四分一円として玄関ポーチを設けた平面で、外壁はタイル貼でアール・デコを基調とし、柱形を密に並べて縦長窓を配する。最上階ではアーチ窓とし、柱型に柱頭飾を施す。昭和初期の意匠的特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011349"},{"id":"00000988","register_sub_id":"101","register_pk":"101978","name":"源ケ橋温泉浴場","kana":"げんがはしおんせんよくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区林寺1-37-1","lat":34.64573867,"lng":135.52901424,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造２階建，瓦葺，建築面積343㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"27 － 0055","desc":"平面は番台を挟んで男女別に区画され，浴槽部分は随時改修されているが，脱衣場及び浴室の構えはよく残る。外観は，屋根は茶褐色の桟瓦を葺き，正面２階には彫像付きの洋風窓や丸窓を開く。市街地における木造の公衆浴場の好例で，広く利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000988"},{"id":"00000255","register_sub_id":"101","register_pk":"101245","name":"四天王寺八角亭","kana":"してんのうじはっかくてい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺1-11-18","lat":34.65543222,"lng":135.51820557,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積21㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"27 － 0020","desc":"第５回内国勧業博覧会の小奏楽堂として建築されたものを、後に現在地に移築したと伝える。平面八角で、庇柱は吹き放ちとし、窓には色ガラスをはめる。母屋柱はコリント式の柱頭飾を付け、モールディングの廻り縁を巡らすなど施工技術にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000255"},{"id":"00010681","register_sub_id":"101","register_pk":"201255","name":"島本町立歴史文化資料館（旧麗天館）","kana":"しまもとちょうりつれきしぶんかしりょうかん（きゅうれいてんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府三島郡島本町桜井1-3-1","lat":34.880071,"lng":135.663699,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積421㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0636","desc":"駅前に建つ武徳殿風の大型木造建築。入母屋造桟瓦葺で裳階を廻らし、入母屋屋根の玄関を構える。側廻りは柱上に舟肘木を載せ、腰板を張る。内部は主体部を広いホールとして折上格天井を張り、片側に演壇を設ける。社寺建築の工法を援用した風格ある会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010681"},{"id":"00014265","register_sub_id":"101","register_pk":"509655","name":"杉江能楽堂","kana":"すぎえのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府岸和田市岸城町1909-3","lat":34.46126667,"lng":135.37172778,"geo_status":"db","era":"大正6年／昭和42年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積283㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0856","desc":"岸和田城跡に所在する能楽堂。切妻造の舞台棟と、橋掛り含む楽屋棟を白洲中庭に面して配し、相対する入母屋造座敷棟の見所と、下手の脇見所からなる。見所は床構え付十畳二間、脇見所は六畳間。対置式で白洲に採光するのは希少で、大阪府内現存最古の能楽堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014265"},{"id":"00000989","register_sub_id":"101","register_pk":"101979","name":"住吉神社能舞台","kana":"すみよしじんじゃのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府豊中市服部南町2-3-31","lat":34.76294729,"lng":135.47889793,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積66㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"27 － 0056","desc":"大阪博物場の観能施設として造られた能舞台で，天満宮を経て住吉神社が所有する。総桧造の伝統的形式に則って造られている。設計は大阪府技手岡崎要吉，工事監督井上節，棟梁は京都の雑賀長右衛門で，当時の上方大工の技術水準の高さを示す作品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000989"},{"id":"00012590","register_sub_id":"101","register_pk":"504379","name":"大将軍湯","kana":"だいしょうぐんゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市本町4733-2","lat":34.415081,"lng":135.315353,"geo_status":"geocoded","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積139㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0763","desc":"市中心部の共同浴場。通りに面する表棟は中央に唐破風の玄関を構え、左右塀の腰をタイル張とする。後方の浴室棟は吹抜けの一空間で、中央の浴槽を男湯･女湯の境壁で二分する。浴槽と床の石敷に大ぶりの花崗岩を用いるのは珍しい。戦前の銭湯建築の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012590"},{"id":"00001527","register_sub_id":"101","register_pk":"102517","name":"鯛よし百番","kana":"たいよしひゃくばん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市西成区山王3-5-25","lat":34.64262152,"lng":135.50569438,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積291㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0086","desc":"旧飛田新地の角地に建つ。木造２階建，入母屋造，桟瓦葺で，２階に擬宝珠高欄を巡らし，角を隅切りとして玄関に唐破風を付ける。内部は，日光東照宮陽明門を模すなど各部屋毎に趣向を凝らし，大阪歓楽街の殷賑を色濃く今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001527"},{"id":"00005702","register_sub_id":"101","register_pk":"106690","name":"通天閣","kana":"つうてんかく","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市浪速区恵美須東1-18-6","lat":34.652561,"lng":135.506348,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":null,"structure_material":null,"registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0415","desc":"難波の東南に位置する。脚部をＳＲＣ造とした１０３ｍ高の鉄塔で，塔の東側には円筒形の補助塔を設ける。四角形から八角形に平面形状が変化する塔身に独特な形状の展望台を戴き，四周に広告用等の施設を付設し，大阪のシンボルとして広く親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005702"},{"id":"00007645","register_sub_id":"101","register_pk":"108627","name":"桃花塾教室棟","kana":"とうかじゅくきょうしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府富田林市大字喜志2067-5他","lat":34.52416363,"lng":135.59974094,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0525","desc":"本館の東方、少し低い位置に建つ。桁行１９ｍ梁間７．６ｍと南北に長い木造平屋建、寄棟造桟瓦葺。西側に廊下を通し、東側に教室３室と便所を並べる。西面は腰竪板壁で、各柱間に引違ガラス戸をたて、明るく開放的に造る。簡素な造りの中に温もりが感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007645"},{"id":"00007644","register_sub_id":"101","register_pk":"108626","name":"桃花塾本館","kana":"とうかじゅくほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府富田林市大字喜志2067-5他","lat":34.52421039,"lng":135.59940847,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積214㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0524","desc":"丘陵地の緩い傾斜地に南面して建つ。木造２階建、寄棟造桟瓦葺。１階は中廊下で研究室や図書室、事務室、２階に講堂や拝礼室等を配する。正面は中央に玄関ポーチを設け、壁は下見板張とし、窓を大きくとる。緑の多い敷地環境に調和した、簡明で良質な福祉施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007644"},{"id":"00005953","register_sub_id":"101","register_pk":"106938","name":"山本能楽堂及び能舞台","kana":"やまもとのうがくどうおよびのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区徳井町1-3-6","lat":34.683937,"lng":135.514984,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"能楽堂 木造2階一部3階建、瓦葺、建築面積353㎡、能舞台 木造平屋建、檜皮葺、面積63㎡","structure_material":"能楽堂 木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0399","desc":"街路に北面して建つ。木造２階一部３階建で，建物中央の能舞台周辺は１，２階を吹抜けとし，見所を設ける。能舞台は切妻造，檜皮葺で，東側に橋掛を設け，鏡の間と繋ぐ。楽屋等の舞台裏手の空間もよく残り，伝統的な能舞台の形式を備えた能楽堂として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005953"},{"id":"00008317","register_sub_id":"101","register_pk":"133959","name":"明石市立天文科学館","kana":"あかししりつてんもんかがくかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県明石市人丸町2-6","lat":34.64940585,"lng":135.00147122,"geo_status":"db","era":"昭和35年／昭和59年・平成10年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積1094㎡、高塔付","structure_material":"鉄筋コンクリート造4階建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0460","desc":"鉄筋コンクリート造で、直径２３メートルの円形プラネタリウムを含む４階建の展示棟と、高さ５３メートルの高塔からなる複合建築。二重構造の高塔上部には展望室と天体観測室を備え、大時計が日本標準時を刻む。子午線のまち明石のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008317"},{"id":"00012223","register_sub_id":"101","register_pk":"353023","name":"芦屋仏教会館","kana":"あしやぶっきょうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市前田町100-1","lat":34.732601,"lng":135.301744,"geo_status":"db","era":"昭和2年／平成15年曳家","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積220㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2018.03.27(平成30.03.27)","register_no":"28-679","desc":"丸紅商店社長の伊藤長兵衛の寄附により建てられた。鉄筋コンクリート造四階建で、近代建築に東洋風・印度風の細部意匠を取り入れたものとされる。外観はホールの上下に対応して三階で見切りを入れて二層構成とし、様々な意匠を破綻なくまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012223"},{"id":"00012592","register_sub_id":"101","register_pk":null,"name":"旧岡方倶楽部（小物屋会館）","kana":"きゅうおかがたくらぶ（こものやかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市兵庫区本町二丁目3-46","lat":34.669888,"lng":135.173798,"geo_status":"geocoded","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積180㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2018.11.02(平成30.11.02)","register_no":"28 － 0697","desc":"兵庫津旧市街の町会集会所で、敷地中央に東面して建つ。鉄筋コンクリート造三階建、陸屋根で、正面のみ一階石造風、二階以上タイル張風に仕上げ、玄関ポーチ上部の壁面と頂部を僅かに出して正面性を強調する。1920年代の建築的特徴を備えた洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012592"},{"id":"00002972","register_sub_id":"101","register_pk":"103962","name":"旧海崎医院","kana":"きゅうかいざきいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷2-455","lat":35.16581922,"lng":134.7925425,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0110","desc":"街道に東面して建つ洋風医院建築で，街道側から４畳半規模の診療室，６畳規模の療治場，４畳半の和室を配置する。診療室は竪羽目板張りで，東面には鎧戸付窓を２箇所，北面には櫛形状ペディメントのキャノピーを付け，擬洋風的な木製の重厚な軒蛇腹を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002972"},{"id":"00013293","register_sub_id":"101","register_pk":"366282","name":"旧駒ヶ林公会堂","kana":"きゅうこまがばやしこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市長田区駒ヶ林町五丁目51-2","lat":34.64885833,"lng":135.14596389,"geo_status":"db","era":"大正13年頃／昭和44年・平成19年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造2階建、建築面積138㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0737","desc":"長田港海岸線に平行する市道沿いに建つ公会堂。二階建で、外壁は煉瓦造、内部の柱、梁、スラブは鉄筋コンクリート造とする。左右対称のファサードに縦長窓を配し、装飾性を抑えた外観とする。用途を変えながら利用され、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013293"},{"id":"00015338","register_sub_id":"101","register_pk":"532462","name":"旧野中外科診療棟","kana":"きゅうのなかげかしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県姫路市福中町11","lat":34.83253611,"lng":134.68729444,"geo_status":"db","era":"昭和28年頃／昭和32年改修、同中期増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積86㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0830","desc":"姫路市の中心部に位置し、銀行店舗を転用した旧診療棟。通りに北面する木造２階建で正面西に階段室を張出して大窓を開け、外壁モルタル洗出仕上。一階は診療施設、二階は応接室。階段室に折鶴形照明を吊る。装飾を省いた箱型の外観がモダニズムの影響を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015338"},{"id":"00015339","register_sub_id":"101","register_pk":"532463","name":"旧野中外科病棟","kana":"きゅうのなかげかびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県姫路市福中町11","lat":34.83258056,"lng":134.68711944,"geo_status":"db","era":"昭和29年／昭和32年増改築、同中期増築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0831","desc":"診療棟の南に位置する病室棟。木造2階建切妻造平入桟瓦葺で外壁リシン掻落仕上。一階北面中央を玄関とし、各階東西に中廊下を通して一階は個室、二階は大部屋の病室、北西に便所や浴室などを配する。銀行倉庫の転用と伝わり昭和戦後の地域医療を支えた病棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015339"},{"id":"00013151","register_sub_id":"101","register_pk":"368292","name":"コウノトリ保護増殖センター第一フライングケージ","kana":"こうのとりほごぞうしょくせんたーだいいちふらいんぐけーじ","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市野上1314-1","lat":35.56921389,"lng":134.82551389,"geo_status":"db","era":"昭和40年／平成30年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"ドーム状鉄管造、面積339㎡","structure_material":"ドーム状鉄管造","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0718","desc":"敷地最奥の谷筋に建つコウノトリの飼育ケージ。大型の半球ドームの両脇に小型の半球ドームを接続した形で、湾曲させた鉄管フレームと金網で構成される。コウノトリ保護、増殖の先駆的試みを示す記念的建造物で、飼育ケージ発展の起点となる貴重なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013151"},{"id":"00009517","register_sub_id":"101","register_pk":"194310","name":"中崎遊園地ラヂオ塔","kana":"なかさきゆうえんちらぢおとう","category":"文化福祉","subcategory":"その他工作物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県明石市相生町1-119-5","lat":34.64453167,"lng":134.99964931,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び石造、高さ3.4m","structure_material":"鉄筋コンクリート造及び石造","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0556","desc":"明石海峡に面した中崎遊園地内に建つ。鉄筋コンクリート造一部石造、一辺一・二メートル、高さ三・四メートルの方形の塔で、頂部を燈籠状にしてラジオの台とし、軒反りをつけた宝形造の屋根をのせる。建設当時の社会の様相とラジオの普及の過程を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009517"},{"id":"00001443","register_sub_id":"101","register_pk":"102433","name":"白鶴美術館事務棟","kana":"はくつるびじゅつかんじむとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73068116,"lng":135.25806451,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積301㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0058","desc":"敷地の入口側に建つ事務棟で，階下に事務室・応接室，階上に集会室，地下に荷解室等を配する。本館と同様な鉄骨鉄筋コンクリート造の和風建築であるが，寺院建築風の本館に対し，木造真壁造風の簡潔な意匠を基調とし全体にのびやかな非対称の建築構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001443"},{"id":"00001444","register_sub_id":"101","register_pk":"102434","name":"白鶴美術館土蔵","kana":"はくつるびじゅつかんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73086933,"lng":135.25795397,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、鉛板葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0059","desc":"本館と事務棟を結ぶ長８間の渡廊下のほぼ中間，渡廊下の西側に建つ南北棟，２階建，切妻屋根，平入の収蔵庫で，渡廊下側の東面に入口を設ける。嘉納治兵衛の持論に基づき，鉄筋コンクリート造でなく，伝統的な木造土蔵造りによって建てられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001444"},{"id":"00001442","register_sub_id":"101","register_pk":"102432","name":"白鶴美術館本館","kana":"はくつるびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73103242,"lng":135.25806024,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積526㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0057","desc":"酒造業白鶴の７代目当主嘉納治兵衛が蒐集した美術品を公開する施設で，住吉川の右岸傾斜地の高台側に南面して建つ。鉄骨鉄筋コンクリート造による純和風建築で，竹中工務店の設計施工になり，鷲尾九郎が設計を担当したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001442"},{"id":"00012430","register_sub_id":"101","register_pk":"531754","name":"御影公会堂","kana":"みかげこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区御影石町四丁目73-1","lat":34.71606944,"lng":135.2492,"geo_status":"db","era":"昭和8年／昭和26年・同47年・平成16年・同29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建地下1階、建築面積1032㎡","structure_material":"鉄筋コンクリート造3階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"28-687","desc":"国道二号と石屋川が交差する御影地区の中心地に建つ。嘉納治兵衛の寄附、清水栄二の設計、大林組の施工により、モダニズムを基調に多様な造形表現を取込み、全体を巧みにまとめる。様々な用途で活用され地域に親しまれてきた、独創的な意匠の文化施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012430"},{"id":"00006614","register_sub_id":"101","register_pk":"107597","name":"旧小國家住宅診療所","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県神崎郡福崎町山崎字大将軍814","lat":34.96852176,"lng":134.755386,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"28 － 0300","desc":"主屋の東側に隣接し、東西棟で建つ。桁行４間半梁間３間規模、切妻造桟瓦葺の木造平屋建で、西方を待合室として切妻造の玄関を突出させ、東北には手術室を張り出す。正面東方は庇を出して全面ガラス窓とする。当地域における地域医療施設の状況が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006614"},{"id":"00005337","register_sub_id":"101","register_pk":"106325","name":"杉山小児科医院住居棟","kana":"すぎやましょうにかいいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市本町52","lat":34.65125062,"lng":135.78505289,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、銅板葺、建築面積92㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0096","desc":"木造２階建，寄棟造，銅板葺，妻入で，東に診療棟が接続する。外壁は１階がタイル張，２階が人造石洗い出し仕上げでフリーズ状の飾りをつけ，窓は上げ下げ式の縦長窓とする。診療棟と異なるアールデコ風意匠は当時の造形の傾向を示し，景観上，存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005337"},{"id":"00005336","register_sub_id":"101","register_pk":"106324","name":"杉山小児科医院診療棟","kana":"すぎやましょうにかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県大和郡山市本町52","lat":34.6512481,"lng":135.78517907,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積170㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0095","desc":"街路に北面して建ち，西に居住棟が続く。東西棟の切妻造，平入，平屋建で，中央部は棟が直交した２階建として外壁を立ち上げる。外観はハーフティンバースタイルで，屋根窓や玄関庇など変化に富む。伝統的な町並みにあって，ランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005336"},{"id":"00014904","register_sub_id":"101","register_pk":"519164","name":"手貝町会所","kana":"てがいちょうかいしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市雑司町79他","lat":34.69263056,"lng":135.83514722,"geo_status":"db","era":"昭和14年／昭和51年・平成13年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0357","desc":"東大寺転害門の北の住宅地に建つ集会所。平屋建切妻造桟瓦葺で南面西寄りに入母屋造玄関を付す。内部東は床構え付きの大広間で南東隅に付書院を備え、西は小会議室と物置を配す。小屋組はキングポスト・トラス。四十畳の広間を有し、地域住民が親しむ集会所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014904"},{"id":"00016423","register_sub_id":"101","register_pk":"536490","name":"奈良文化財研究所飛鳥資料館売札所","kana":"ならぶんかざいけんきゅうしょあすかしりょうかんばいさつしょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"奈良県","address":"奈良県桜井市大字山田681","lat":34.48365278,"lng":135.82571667,"geo_status":"db","era":"昭和50年／昭和52年改修","year":1975,"year_source":"db","year_min":1975,"year_max":1975,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積29㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"29 - 0374","desc":"資料館の正門東脇に建つ売札所。設計は谷口吉郎。鉄筋コンクリート造平屋建切妻造桟瓦葺の南北棟で、正面となる南妻は売札口の庇を兼ね螻羽を深くして切妻屋根を強調する。本館と共通する均整の取れた端正な外観で、本館と一体となって歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016423"},{"id":"00016422","register_sub_id":"101","register_pk":"536489","name":"奈良文化財研究所飛鳥資料館本館","kana":"ならぶんかざいけんきゅうしょあすかしりょうかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"奈良県","address":"奈良県高市郡明日香村大字奥山601他","lat":34.48432222,"lng":135.82516111,"geo_status":"db","era":"昭和49年","year":1974,"year_source":"db","year_min":1974,"year_max":1974,"year_label":null,"structure":"鉄筋コンクリート造地上1階地下1階建、瓦葺、建築面積1，182㎡","structure_material":"鉄筋コンクリート造地上1階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"29 - 0373","desc":"明日香村の北部にある文化財展示施設。設計は谷口吉郎。鉄筋コンクリート造地上1階地下1階建。切妻造の東西棟を前後に配し、外壁に格子窓を整然と並べ、周囲に高欄付縁を廻らす。洗練された和風の外観が、飛鳥地域の歴史的な景観と調和する谷口晩期の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016422"},{"id":"00012783","register_sub_id":"101","register_pk":"367686","name":"野村医院旧診療所","kana":"のむらいいんきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県山辺郡山添村大字大西294","lat":34.681325,"lng":136.04389444,"geo_status":"db","era":"明治30年頃／昭和31年移築・改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"29 － 278","desc":"村中心部のもと診療所。木造平屋建、入母屋造桟瓦葺妻入で、南面西半に切妻造の車寄を付す。外壁は漆喰塗の腰下見板張、側面に引分け硝子窓を並べる。内部は2列6室で、待合室や診察室、手術室等を機能的に配する。明治期の地方診療施設の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012783"},{"id":"00008322","register_sub_id":"101","register_pk":"133964","name":"松浦家住宅旧診察室","kana":"まつうらけじゅうたくきゅうしんさつしつ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59880659,"lng":135.70410779,"geo_status":"db","era":"昭和21年／昭和30年改修","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0193","desc":"主屋の南に接続する木造平屋建。外壁モルタル仕上げで、四隅に柱型をつくり、パラペットをまわす。主屋との取り付き部分を含め、南北６．８ｍ東西３．２ｍ。東面北寄りに出入口を開け、南を診察室とした。入口内部の壁には円窓を穿ち、緑色ガラスを嵌める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008322"},{"id":"00014198","register_sub_id":"101","register_pk":"508828","name":"紀伊風土記の丘松下記念資料館","kana":"きいふどきのおかまつしたきねんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県和歌山市岩橋1411","lat":34.22789444,"lng":135.22961389,"geo_status":"db","era":"昭和46年／平成13年改修","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄筋コンクリート造平屋建地階付、建築面積1，593㎡","structure_material":"鉄筋コンクリート造平屋建地階付","registered":"2022.02.17(令和4.02.17)","register_no":"30-0318","desc":"古墳群の傍らに建つ浦辺鎮太郎設計の鉄筋コンクリート造博物館施設。土塁等で設計条件のボリュームを抑えた外観を実現する。大面取りピラスター、長押形水切、青石貼りの壁、銅鐸文様面格子など古代から着想を得て、モダニズムを基調としつつ景観に溶け込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014198"},{"id":"00004286","register_sub_id":"101","register_pk":"105276","name":"火伏医院病院棟","kana":"ひぶせいいんびょういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県橋本市橋本1-16、1-17","lat":34.31638904,"lng":135.61198981,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0057","desc":"主屋の西に位置し，街道から退いて建つ。６．７ｍ角の平面規模，木造２階建，下見板張で，屋根は桟瓦葺とし正面側を寄棟，背面側を切妻につくる。紀ノ川の洪水に配慮して１．３ｍ程の高床としている点に特徴があり，橋本の町並みのランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004286"},{"id":"00013175","register_sub_id":"101","register_pk":"368404","name":"南方熊楠記念館本館","kana":"みなかたくまぐすきねんかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県西牟婁郡白浜町字崎の北3601-1","lat":33.69372778,"lng":135.33628889,"geo_status":"db","era":"昭和40年／平成29年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積240㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0278","desc":"番所山の最高地点に建つ鉄筋コンクリート造二階建の記念館。緩い糸巻き型の細長い平面を北東の田辺湾に向けて眺望を取り、南面を正面とする。正面二階は腕木を手前に張り出させ、丸みを帯びたコンクリート斫り仕上の量感のある庇で特徴的な立面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013175"},{"id":"00012974","register_sub_id":"101","register_pk":"368053","name":"三輪崎青年会館","kana":"みわさきせいねんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県新宮市三輪崎二丁目498-3他","lat":33.685575,"lng":135.98536389,"geo_status":"db","era":"昭和2年／平成13年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積194㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 261","desc":"町中心部の通りに南面して建つ集会施設。木造平屋建、切妻造桟瓦葺妻入で、正面妻に日の出の浮彫を施し、両端の突出部にペディメントを載せる。内部は一空間で、北側に舞台、南側に桟敷状の二階を設ける。三輪崎漁港の街路景観のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012974"},{"id":"00004994","register_sub_id":"101","register_pk":"105984","name":"革島医院","kana":"かわしまいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区麩屋町通六角下る坂井町468-1","lat":35.00656262,"lng":135.76583886,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造3階建、瓦葺、建築面積376㎡","structure_material":"木造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0203","desc":"市役所の南西，麩屋町通に西面して建つ住宅兼病院。ロ字形平面を基本とした木造３階建でフランス瓦を使用。北西端に円錐形屋根を架したタイル張の円筒形塔屋，正面南寄りには格子窓を垂直方向に連ね妻をハーフティンバーとした階段室を張出すなど独特の外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004994"},{"id":"00000544","register_sub_id":"101","register_pk":"101534","name":"関西日仏学館","kana":"かんさいにちふつがっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田泉殿町8-8","lat":35.0262482,"lng":135.77827269,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積549㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1998.04.21(平成10.04.21)","register_no":"26 － 0013","desc":"２０世紀フランスを代表する建築家ペレの弟子メストラレが基本設計にあたる。ペレ流の洗練された柱型と軒線がつくる古典主義的骨格に，要所の曲面が優美さを与える。東大路通に面して建ち，京都大学の諸建築とともに学園街を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000544"},{"id":"00011343","register_sub_id":"101","register_pk":"209180","name":"関西美術院","kana":"かんさいびじゅついん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎南御所町41","lat":35.01559,"lng":135.785054,"geo_status":"db","era":"明治39／明治40増築、昭和37・同39改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積244㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"26－0507","desc":"洋画の普及・指導のために設立された関西美術院の建物。設計は武田五一。木造平屋建で、トラス組で緩勾配の片流屋根をかける。北面には大きな窓を設け、アトリエに最適な採光を確保している。我が国でアトリエ空間を設けた建築の初期の事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011343"},{"id":"00002293","register_sub_id":"101","register_pk":"103283","name":"祇園甲部歌舞練場玄関","kana":"ぎおんこうぶかぶれんじょうげんかん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001949,"lng":135.775299,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0085","desc":"東側本館，南側別館，北側の弥栄会館に囲まれた位置に建ち，演舞会時には一等玄関・一等待合に使用されてきた。入母屋造の主体部に唐破風の車寄を接続した形態で，主体部は４５畳と３０畳の板間に分かれていた。入口に相応しい堂々とした外観を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002293"},{"id":"00002294","register_sub_id":"101","register_pk":"103284","name":"祇園甲部歌舞練場正門","kana":"ぎおんこうぶかぶれんじょうせいもん","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001663,"lng":135.775009,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積174㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0086","desc":"祇園甲部歌舞練場は，明治６年に杉浦治郎右衛門が新しい歌舞芸能として考案した「都踊り」開催場として建設したことに始まる。鉄筋コンクリート造，平屋建，寄棟造・銅板瓦葺の建物で，敷地西側の花見小路に面して建ち，アプローチを構成する重要な要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002294"},{"id":"00002292","register_sub_id":"101","register_pk":"103282","name":"祇園甲部歌舞練場別館","kana":"ぎおんこうぶかぶれんじょうべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001266,"lng":135.77594,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積712㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0084","desc":"本館の南側に接する東西棟・妻入の細長い建物で，１階は当初７０畳敷の点茶席，２階は休憩室・待合室で床・棚付の２室とする。正面となる西面は車寄の唐破風，玄関となる妻庇上の千鳥破風，入母屋造の妻飾が階段状に続き，躍動感のある外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002292"},{"id":"00002291","register_sub_id":"101","register_pk":"103281","name":"祇園甲部歌舞練場本館","kana":"ぎおんこうぶかぶれんじょうほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.00141637,"lng":135.77586118,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造地上2階一部地下1階建、瓦葺、建築面積1035㎡","structure_material":"木造地上2階一部地下1階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0083","desc":"西面して建つ木造２階建で，広大な南北棟の入母屋造・瓦葺屋根を架け，西面に千鳥破風を設ける。北側を舞台，南側を客席とした構成で，良質の檜材を用いた丁寧なつくりになる。記念的な木造の大劇場建築であり，明治期の祇園町都踊りの盛況を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002291"},{"id":"00007069","register_sub_id":"101","register_pk":"108051","name":"旧恩賜京都博物館陳列品収納用倉庫（京都国立博物館技術資料参考館）","kana":"きゅうおんしきょうとはくぶつかんちんれつひんしゅうのうようそうこ（きょうとこくりつはくぶつかんぎじゅつしりょうさんこうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区正面通本町東入茶屋町527他","lat":34.989529,"lng":135.773697,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積101㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0291","desc":"本館東南の高台に建つ。寄棟造桟瓦葺。鉄筋コンクリート造２階地下１階建、東西に長い矩形平面で、西面に庇付の玄関を設ける。スクラッチタイル貼とし、柱や梁の構造を表し、南面に大きく方形の窓、北面に縦型窓を各階に開け、端正でリズム感ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007069"},{"id":"00002296","register_sub_id":"101","register_pk":"103286","name":"旧弥栄会館","kana":"きゅうやさかかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側570-289","lat":35.001785,"lng":135.775482,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上5階地下1階建、瓦葺、建築面積260㎡、西面及び南面東寄り外壁付","structure_material":"鉄骨鉄筋コンクリート造地上5階地下1階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0088","desc":"鉄骨鉄筋コンクリート造，地上５階地下１階建で，南面して建つ。各階に銅板瓦葺屋根をかけ，塔屋状の正面中央部は付庇や宝形造屋根が城郭の天守を思わせる造形で，和風意匠の伝統を巧みに織り込んでいる。設計は劇場建築を手がけた木村得三郎，施工は大林組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002296"},{"id":"00013416","register_sub_id":"101","register_pk":"368501","name":"京都市美術館北案内板","kana":"きょうとしびじゅつかんきたあんないばん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町70","lat":35.01348889,"lng":135.78276667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部木造、銅板葺、間口3.3m","structure_material":"鉄筋コンクリート造一部木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0603","desc":"本館の正面である西面北寄りに建てた案内板。鉄筋コンクリート造で本館と同じタイル貼の柱を二本立て、木造の小屋組の上に切妻造銅板葺の屋根を載せる。柱間には木製の案内板を設置する。本館外観意匠との調和を図り、美術館の外構を構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013416"},{"id":"00013414","register_sub_id":"101","register_pk":"368499","name":"京都市美術館北門","kana":"きょうとしびじゅつかんきたもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町50","lat":35.01359167,"lng":135.78391667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0601","desc":"敷地の北面に設けられた門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。北面の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013414"},{"id":"00013412","register_sub_id":"101","register_pk":"368497","name":"京都市美術館正門（北）","kana":"きょうとしびじゅつかんせいもん（きた）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町70","lat":35.01315556,"lng":135.78274167,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0599","desc":"本館の正面である西面に設けられた北側の正門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。美術館の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013412"},{"id":"00013413","register_sub_id":"101","register_pk":"368498","name":"京都市美術館正門（南）","kana":"きょうとしびじゅつかんせいもん（みなみ）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町144","lat":35.0127,"lng":135.782775,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0600","desc":"本館の正面である西面に設けられた南側の正門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。美術館の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013413"},{"id":"00013415","register_sub_id":"101","register_pk":"368500","name":"京都市美術館東門","kana":"きょうとしびじゅつかんひがしもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町50","lat":35.01289444,"lng":135.78465,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、間口3.9m","structure_material":"石造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0602","desc":"敷地の東面に設けられた門で、間口三・九メートルに配した二基の門柱からなる。花崗岩を用いた石造で、四隅を面取りし、側面に渦巻状の装飾を施す。イオニア式オーダーを想起させる意匠で、美術館の前身である京都商品陳列所の門として立てた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013415"},{"id":"00013411","register_sub_id":"101","register_pk":"368496","name":"京都市美術館本館","kana":"きょうとしびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町124他","lat":35.01286111,"lng":135.78358333,"geo_status":"db","era":"昭和8年／令和元年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上2階地下1階建、銅板葺、建築面積4596㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上2階地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0598","desc":"京都市左京区の南端に位置し、神宮道に西面して建つ。鉄筋コンクリート造一部鉄骨造、地上二階地下一階建で、四面中央に車寄付の入口を設ける。日本趣味を基調とするという条件で設計図案を公募し、和洋の様式を巧みに織り交ぜた意匠が評価された美術館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013411"},{"id":"00013417","register_sub_id":"101","register_pk":"368502","name":"京都市美術館南案内板","kana":"きょうとしびじゅつかんみなみあんないばん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町144","lat":35.01225,"lng":135.78282222,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部木造、銅板葺、間口3.3m","structure_material":"鉄筋コンクリート造一部木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0604","desc":"本館の正面である西面南寄りに建てた案内板。鉄筋コンクリート造で本館と同じタイル貼の柱を二本立て、木造の小屋組の上に切妻造銅板葺の屋根を載せる。柱間には木製の案内板を設置する。本館外観意匠との調和を図り、美術館の外構を構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013417"},{"id":"00000594","register_sub_id":"101","register_pk":"101584","name":"京都大学楽友会館","kana":"きょうとだいがくがくゆうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田近衛町","lat":35.0220308,"lng":135.77953243,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積715㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0016","desc":"京大創立２５周年記念の同窓会館。分離派建築会の森田慶一が設計にあたる。スパニッシュ・ミッションを基調としながら，Ｙ字型の柱に支えられた円みをもつポーチ屋根が破調を与える。森谷延雄による家具とともに内部空間も大正建築の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000594"},{"id":"00001198","register_sub_id":"101","register_pk":"102188","name":"京都大学基督教青年会会館","kana":"きょうとだいがくきりすときょうせいねんかいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田牛ノ宮町21、23","lat":35.02535138,"lng":135.77703403,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造２階建，スレート葺，建築面積197㎡","structure_material":"煉瓦造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"26 － 0038","desc":"京都大学本部構内の西方、東一条通りに南面して建つ。モルタル塗でハーフティンバー風に見せている点に特徴がある。ヴォーリズの初期の作風の一端が窺われるとともに、大学ＹＭＣＡ会館の現存最古例としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001198"},{"id":"00001923","register_sub_id":"101","register_pk":"102913","name":"京都大学人文科学研究所附属漢字情報研究センター","kana":"きょうとだいがくじんぶんかがくけんきゅうじょふぞくかんじじょうほうけんきゅうせんたー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川東小倉町47","lat":35.03023658,"lng":135.78980921,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート2階建、建築面積2436㎡、塔屋付","structure_material":"鉄筋コンクリート2階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0072","desc":"外務省東方文化学院京都研究所として建設。ＲＣ造，外壁スタッコ仕上で、塔付２階建の西棟と平屋建の他棟が中庭を囲みロ字形平面を構成する。スパニッシュ･ミッション様式を基調に外観･内装ともに高密度のデザインが施される。設計は武田五一と東畑謙三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001923"},{"id":"00000739","register_sub_id":"101","register_pk":"101729","name":"京都大学文学部陳列館","kana":"きょうとだいがくぶんがくぶちんれつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.0273761,"lng":135.77984967,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造２階建，瓦葺，建築面積732㎡","structure_material":"煉瓦造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0020","desc":"京都帝大拡張期の代表的建築で，陳列館としての記念碑的性格を有する。ブロークンペディメントや楕円形の窓などネオバロックに傾斜しながらも，細部装飾にはセセッション的意匠が認められ大正期建築の特徴をも示す。京大営繕の山本治兵衛と永瀬狂三の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000739"},{"id":"00015474","register_sub_id":"101","register_pk":"533489","name":"京都府立堂本印象美術館本館","kana":"きょうとふりつどうもといんしょうびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"京都府","address":"京都府京都市北区平野上柳町26-3他","lat":35.03513889,"lng":135.72601111,"geo_status":"db","era":"昭和41年／昭和40年代改修・同45年増築","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積565㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0689","desc":"衣笠山東麓に位置し、日本画家堂本印象の作品を収蔵展示する美術館の本館。鉄筋コンクリート造地上３階地下1階建で、モダンな白色の外壁をレリーフで華やかに飾る。独創的な外観とともにスロープで廻る展示室など内外ともに印象の趣向を強く反映した美術館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015474"},{"id":"00015475","register_sub_id":"101","register_pk":"533490","name":"京都府立堂本印象美術館山のアトリエ","kana":"きょうとふりつどうもといんしょうびじゅつかんやまのあとりえ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市北区平野上柳町26-2","lat":35.03518889,"lng":135.72558611,"geo_status":"db","era":"昭和25年頃／昭和39年移築、平成3年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0690","desc":"最高裁判所大法廷の壁画製作用に建てた堂本印象の作業場。木造平屋建切妻造桟瓦葺で、東に玄関を付す。内部は一室の板敷で天井は船底状に張り、内壁とともに合板張仕上。南面全面にガラス窓と欄間を開け、多くの自然光を内部に取入れる大作制作用のアトリエ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015475"},{"id":"00006384","register_sub_id":"101","register_pk":"107367","name":"対岳文庫","kana":"たいがくぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町100","lat":35.07843876,"lng":135.78313083,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積69㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"26 － 0266","desc":"鉄筋コンクリート造平屋建で、桟瓦葺。東西棟の主屋に切妻妻入の玄関を突出し、外壁は上部をスクラッチタイル貼とし、腰を洗出しとする。内部は陳列室と収蔵室に分かれ、床板敷で、壁を板張とする。簡潔で軽快な意匠で、武田五一の手になる小品の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006384"},{"id":"00009337","register_sub_id":"101","register_pk":"194130","name":"田村家住宅離れ（旧鈴木医院）","kana":"たむらけじゅうたくはなれ（きゅうすずきいいん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市長法寺南谷11","lat":34.93165841,"lng":135.67982681,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0410","desc":"丹波街道沿いの敷地南寄りに建つ。建築面積六一平方メートル、木造二階建、入母屋造桟瓦葺。一階は東面北端に玄関を構え、診察室などを配する。東面と南面は上下階に同意匠のガラス窓を建て、統一感のある外観とする。座敷の造作も丁寧で開放的な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009337"},{"id":"00013586","register_sub_id":"101","register_pk":"504949","name":"日の出湯","kana":"ひのでゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府舞鶴市字東吉原45他","lat":35.45595,"lng":135.32961944,"geo_status":"db","era":"大正6年／昭和29年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0614","desc":"西舞鶴に所在する公衆浴場。道路に西面して建つ切妻造平入で、南を銭湯、北を住居部とする。銭湯は中央に番台を構えて南北に男女を分け、浴場は中心に浴槽、周囲に洗場を配す。二階には上質な床付の座敷を配すなど、戦前の町家風銭湯建築の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013586"},{"id":"00012755","register_sub_id":"101","register_pk":"367658","name":"松井家住宅主屋（旧中井産院）","kana":"まついけじゅうたくしゅおく（きゅうなかいさんいん）","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区深草稲荷榎木橋町9","lat":34.96934778,"lng":135.77112,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺及び瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 581","desc":"伏見稲荷界隈の角地にあり、伏見街道に西面する洋館と、その背面の和館からなる。洋館は布目タイル張に縦長窓を並べた事務所風の外観、和館は切妻造の総二階建である。両館南端に土間を通して中間を中庭とするなど、表屋造の構成を踏襲した近代の医院兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012755"},{"id":"00000060","register_sub_id":"101","register_pk":"101050","name":"南座","kana":"みなみざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路西入中之町198","lat":35.00349866,"lng":135.77236398,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造・鉄骨造地上4階地下1階建、瓦葺、建築面積1797㎡","structure_material":"鉄骨鉄筋コンクリート造・鉄骨造地上4階地下1階建","registered":"1996.12.20(平成8.12.20)","register_no":"26 － 0001","desc":"桃山風の意匠を凝らした劇場建築で，総客席数1500余の大劇場を収容する。平成２年から３年にかけて改修が行われ，外観は竣工当時の姿に復元された。演劇の中心地の一つとして，また都市のランドマークとして，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000060"},{"id":"00002295","register_sub_id":"101","register_pk":"103285","name":"八坂倶楽部","kana":"やさかくらぶ","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001175,"lng":135.775574,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積746㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0087","desc":"木造２階建，入母屋造・瓦葺の大屋根を架けた建物で，敷地南奥に建つ。北面西側に軒唐破風付の玄関を設け，東面と南面から庭園を望む。１階は特等客向けの待合・点茶などに用いられ，２階は広大な１３２畳敷の客席と舞台からなる広壮な舞台座敷としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002295"},{"id":"00000877","register_sub_id":"101","register_pk":"101867","name":"陽明文庫虎山荘","kana":"ようめいぶんここざんそう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野福王子町50","lat":35.03118221,"lng":135.70986929,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積393㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0030","desc":"陽明文庫所蔵品の閲覧を目的として建てられた数寄屋造りの別荘建築。主屋部分と客殿部分から構成され，内部に茶室（滴庵）などを持つ。伝統的な構法の中にも設計者である長谷部鋭吉による新たな試みが随所になされ，細部にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000877"},{"id":"00000876","register_sub_id":"101","register_pk":"101866","name":"陽明文庫事務所","kana":"ようめいぶんこじむしょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野上ノ谷町1-2","lat":35.03175599,"lng":135.71010738,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積159㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0029","desc":"木造平屋建ての事務所建築。第一文庫，第二文庫と並んで配置されている。簡素な意匠・構成になるが，玄関周りの格子状の意匠，暖炉の煙突などに特徴が見られ，全体として洋風とも和風ともつかない特色あるデザインである。設計は長谷部鋭吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000876"},{"id":"00000874","register_sub_id":"101","register_pk":"101864","name":"陽明文庫第一文庫","kana":"ようめいぶんこだいいちぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区鳴滝宇多野谷２","lat":35.03161346,"lng":135.70971315,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積73㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0027","desc":"近衛家に伝わる古文書・美術品などを収める収蔵庫。当時の近衛家所有地の一角に建てられた。収蔵品の重要性に鑑み，湿度管理などを意識して設計されている。土蔵風であるが，ＲＣによる堅牢な構造である。設計は長谷部鋭吉，大工棟梁は俣野忠蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000874"},{"id":"00000875","register_sub_id":"101","register_pk":"101865","name":"陽明文庫第二文庫","kana":"ようめいぶんこだいにぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区鳴滝宇多野谷２","lat":35.0316302,"lng":135.70988057,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積121㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0028","desc":"近衛家が所有する美術品等を収める収蔵庫。第一文庫と同じく湿度管理，耐震耐火などを意識して建てられたが，厳しい資材事情から床下吹き放ちを断念するなど設計・仕様が異なっている。第一文庫と同じく設計は長谷部鋭吉，大工棟梁は俣野忠蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000875"},{"id":"00012389","register_sub_id":"101","register_pk":"531713","name":"若の湯","kana":"わかのゆ","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府舞鶴市字本小字本町59他","lat":35.44853056,"lng":135.3275,"geo_status":"db","era":"大正12年／昭和15年・同49年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡、塀付","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"26-573","desc":"西舞鶴市街にある公衆浴場。奥行の狭い敷地中央に切妻造妻入の玄関棟を構え、左右に男女の各浴場棟を接続し、玄関の左右には塀を延ばす。タイル張と洗出し壁を併用しつつ創作的な洋風意匠でまとめた華やかな外観で、近代舞鶴の発展と賑わいを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012389"},{"id":"00006743","register_sub_id":"101","register_pk":"107726","name":"旧建部歯科医院","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市左京区下鴨松ノ木町2-2","lat":35.04181903,"lng":135.77070217,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積48㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"26 － 0267","desc":"増田友也の設計になり「診療室をもつ小住宅」として発表される。東西６．５ｍ南北６．４ｍ規模で、４隅に柱を置き、屋根を片流れとし、南側を２階建の居住部、北側を診察室とし、診察室東面に縦ルーバーを嵌める。戦後鉄筋コンクリート造小住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006743"},{"id":"00005495","register_sub_id":"101","register_pk":"106483","name":"板井原公民館","kana":"いたいばらこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29107058,"lng":134.24917528,"geo_status":"db","era":"昭和前期／昭和29曳家","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積36㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0100","desc":"向山神社境内の東隣にある。木造２階建，切妻造，鉄板葺で，西妻面に切妻造の玄関を設け，外壁は下見板張であるが，上部の軒下を漆喰塗とする。１階は，前面に梁を架け，広く間口を開放できる構造とし，舞台を兼用している。２階は床付８畳と前室４畳からなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005495"},{"id":"00013881","register_sub_id":"101","register_pk":"507839","name":"旧吉田医院","kana":"きゅうよしだいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市瓦町504他","lat":35.49648611,"lng":134.22709167,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積113㎡","structure_material":"土蔵造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0272","desc":"市街地に位置する施主設計の医院。土蔵造二階建で外壁は白漆喰で塗込め、腰を洗出に海鼠目地を施し、庇付の虫籠窓を開く。内部は一階を診療所、二階を病室とし、洋風の階段室や、東洋風の窓桟の割付など、随所に東西の様式を混在させる民藝調の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013881"},{"id":"00013882","register_sub_id":"101","register_pk":"507840","name":"旧吉田璋也家住宅主屋","kana":"きゅうよしだしょうやけじゅうたくおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市瓦町503他","lat":35.49649167,"lng":134.22724444,"geo_status":"db","era":"昭和28年／昭和29年頃・同35年頃増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0273","desc":"医院の東に接続し、道路に東面して建つ。土蔵造二階建で外壁は白漆喰で塗込め、正面腰を凝灰岩積とし、庇付の大小の虫籠窓を開く。内部一階は茶の間、台所、二階は座敷等を配する。東洋風の家具や洋風天井等東西の意匠を容れた民藝調スタイルでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013882"},{"id":"00009369","register_sub_id":"101","register_pk":"194162","name":"鳥取民藝美術館","kana":"とっとりみんげいびじゅつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市栄町651","lat":35.49612632,"lng":134.2271687,"geo_status":"db","era":"昭和32年／昭和36年増築","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階一部地下1階建、瓦葺、建築面積81㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階一部地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"31 － 0173","desc":"鉄筋コンクリート造の一階に鉄骨造の二階を増築する。建築面積八一平方メートル。外壁はモルタル塗に漆喰仕上げ、腰は洗出しとして土蔵風とする。小屋組は木造で和小屋とし、切妻の置屋根に桟瓦を葺く。民藝運動に参加した施主自らが設計した民藝館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009369"},{"id":"00011791","register_sub_id":"101","register_pk":"210807","name":"鳥取民藝美術館別館湖山池阿弥陀堂","kana":"とっとりみんげいびじゅつかんべっかんこやまいけあみだどう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市三津字小狭間戸888","lat":35.518069,"lng":134.143648,"geo_status":"db","era":"昭和39年／昭和41年増築、昭和50年代改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"31-0225","desc":"湖山池の北岸にある小山の頂上に建つ。木造平屋建で屋根は鋼板葺。池を望む展望室の背面側に水屋を介して四畳半茶室、西には二畳中板茶室を配す。構造材にクリ材を多用するほか、ケヤキ、ラワン、サクラなどを組み合わせるなど、特徴的な民芸的建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011791"},{"id":"00000157","register_sub_id":"101","register_pk":"101147","name":"日野町歴史民俗資料館（旧根雨公会堂）","kana":"ひのちょうれきしみんぞくしりょうかん（きゅうねうこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県日野郡日野町根雨497","lat":35.23736777,"lng":133.44270377,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建，瓦葺，建築面積473㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"31 － 0002","desc":"根雨の町並みを見下ろす山の中腹に建つ切妻造，妻入で，設計は岡田孝雄。間口９間，奥行１６間半，木造２階建ての大規模な公会堂である。外観は周囲の町並みに調和するように，庇を回して抑えた意匠になる。妻壁を飾るマークが文化の殿堂であることを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000157"},{"id":"00008753","register_sub_id":"101","register_pk":"149474","name":"飛龍閣","kana":"ひりゅうかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市仲ノ町3445-1","lat":35.42984395,"lng":133.82350896,"geo_status":"db","era":"明治37年／昭和39年・平成2年・平成20年改修","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0164","desc":"打吹山北麓に所在する。木造平屋建、入母屋造桟瓦葺、建築面積203㎡。北面に入母屋造妻入の玄関を張り出し、左手奥に御座所、その南側に寝殿を配する。御座所はトコと違棚、平書院を構え、町並みを遠望する。洗練された意匠で、格式を感じさせる和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008753"},{"id":"00002811","register_sub_id":"101","register_pk":"103801","name":"中町公民館","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭554-1","lat":35.26938959,"lng":134.22974233,"geo_status":"db","era":"大正11以前","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積140㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"31 － 0054","desc":"当初は個人病院として建てられたが，大正１１年より幼稚園として用いられきた。木造２階建，寄棟造・桟瓦葺で，外壁は鉄板で覆われているが，内側に下見板張を残す。外観は洋風であるが，内部は和風で纏められており，地方の洋風建築の展開を示す一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002811"},{"id":"00006401","register_sub_id":"101","register_pk":"107384","name":"浅野小児科医院","kana":"あさのしょうにかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市末次町74","lat":35.46961077,"lng":133.04677535,"geo_status":"db","era":"大正元／平成元改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"32 － 0056","desc":"道路に東面する木造２階建。間口５間の切妻造桟瓦葺である。正面北端の玄関ポーチはドリス式双子柱で飾り、上部はバルコニーとする。外壁は縦溝付ピラスターの大オーダーで３分割する。窓は２つ１組で、２階窓上にコンソールを添える。整った意匠をもつ佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006401"},{"id":"00005355","register_sub_id":"101","register_pk":"106343","name":"阿須那公民館阿須那分館","kana":"あすなこうみんかんあすなぶんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"島根県","address":"島根県邑智郡邑南町阿須那6-6","lat":34.86903386,"lng":132.61791841,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積426㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"32 － 0045","desc":"社会教育法（昭和２４年公布）に基づく初期の公民館建築。正面１５ｍ規模，切妻造，桟瓦葺，妻入の木造２階建で，中央に講堂を配し，正面妻壁に阿須那村の村章を掲げる。いち早く公民館建設に取り組んだ村民の意気込みが感じられ，今なお広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005355"},{"id":"00013181","register_sub_id":"101","register_pk":"368308","name":"旧島根県立博物館（島根県庁第三分庁舎）","kana":"きゅうしまねけんりつはくぶつかん（しまねけんちょうだいさんぶんちょうしゃ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"島根県","address":"島根県松江市殿町１","lat":35.47113889,"lng":133.05155556,"geo_status":"db","era":"昭和33年／平成25年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積426㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"32 － 0204","desc":"松江城の南側に建つ、鉄筋コンクリート造の旧博物館。張出した箱状の三階を三列の柱で持上げ、一、二階はベランダや吹抜けで開放的とする。景観に馴染むよう白と黒を基調とし、屋根を折板構造とする等の工夫をしつつ、設計者菊竹清訓の作風がよく現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013181"},{"id":"00013885","register_sub_id":"101","register_pk":"507843","name":"旧島根県立博物館新館（島根県庁第三分庁舎）","kana":"きゅうしまねけんりつはくぶつかんしんかん（しまねけんちょうだいさんぶんちょうしゃしんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市殿町1","lat":35.47116389,"lng":133.0513,"geo_status":"db","era":"昭和44年","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積350㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0210","desc":"菊竹清訓設計の博物館新館。鉄筋コンクリート造三階建で、同設計者の本館同様、収蔵施設を上階に持上げ、下部は開放的な展示室。仕上も下層を打放し、上層を白セメントで塗分ける。壁柱の多用や大スパンをとばす梁の表現等に設計者のデザインがよく表れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013885"},{"id":"00013886","register_sub_id":"101","register_pk":"507844","name":"島根県民会館","kana":"しまねけんみんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市殿町158","lat":35.472725,"lng":133.05303889,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上4階地下1階建、建築面積3，893㎡、塔屋付","structure_material":"鉄筋コンクリート造一部鉄骨造地上4階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0211","desc":"鉄筋コンクリート造一部鉄骨造地下一階地上四階建。大ホール他展示室、会議室等を持つ総合施設。松江城大手前にあり、中心にホール、周囲に低層の会議室などを配して周辺環境に配慮。堀を挟んで建つ県庁舎のピロティとあわせて列柱を外部に並べて調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013886"},{"id":"00013887","register_sub_id":"101","register_pk":"507845","name":"島根県立図書館","kana":"しまねけんりつとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市内中原町52","lat":35.47322778,"lng":133.04898333,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積2，012㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0212","desc":"鉄筋コンクリート造一部鉄骨造二階建の図書館。菊竹清訓設計。Ｌ字形の閲覧室のモジュールを敷地形状にあわせて配置し、中央ロビーに鉄骨屋根を架け、展示や休憩スペース等を配した合理的な平面構成。外部壁柱を松江城山公園に向けて揃え、眺望を確保した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013887"},{"id":"00013888","register_sub_id":"101","register_pk":"507846","name":"島根県立武道館","kana":"しまねけんりつぶどうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"島根県","address":"島根県松江市内中原町52","lat":35.47191667,"lng":133.04908889,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積1，704㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0213","desc":"鉄筋コンクリート造一部鉄骨造二階建で、柔剣道場四面にトレーニング場等付属施設を備えた総合体育館。菊竹清訓設計。隣接する図書館とは対照的に閉鎖的外観を持つ。二階に設けられた道場は、大空間の屋根を支える全長四〇メートルの鉄骨トラス梁が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013888"},{"id":"00006754","register_sub_id":"101","register_pk":"107737","name":"津森内科医院","kana":"つもりないかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市本庄町569-1","lat":35.509724,"lng":133.128922,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建及び鉄筋コンクリート造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋一部2階建及び鉄筋コンクリート造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"32 － 0055","desc":"道路西側敷地の南端に建つ木造２階建で、北側の玄関上部をバルコニーとする。背後に平屋建が続く。２階は急勾配の銅板葺半切妻屋根をＬ字に架け、東と北に妻を見せる。外壁はモルタル塗。縦長窓や２階のベイウインドウ、玄関庇などに端正な洋風意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006754"},{"id":"00007319","register_sub_id":"101","register_pk":"108301","name":"津和野町郷土館","kana":"つわのちょうきょうどかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町森村ロ127","lat":34.46558207,"lng":131.77327163,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積292㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0084","desc":"入母屋造妻入赤瓦葺の木造２階建で、両側面前寄りに大きく切妻造平屋建を付設、正面に切妻造の車寄を付ける。玄関ホールに階段を設け、両脇に事務室等を配し、背面側の各階を展示室とする。当初は白漆喰仕上げ。壁面に柱形等を造り出し、大きく窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007319"},{"id":"00007544","register_sub_id":"101","register_pk":"108526","name":"花田医院診療所及び主屋","kana":"はなだいいんしんりょうじょおよびしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市江津町147他","lat":35.00922648,"lng":132.22828974,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0094","desc":"本町通り西側に占める敷地に建つ。Ｔ字型に落棟を付ける寄棟造の木造２階建を中心に、その正面に入母屋造の玄関、その南側直角に半切妻造で洋風意匠になる診療所、背面に半切妻造の台所などを付設する。複雑な構成になる建物で、カーキ色の石州瓦が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007544"},{"id":"00007545","register_sub_id":"101","register_pk":"108527","name":"花田医院門及び塀","kana":"はなだいいんもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市江津町147他","lat":35.00913709,"lng":132.2282167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 鉄筋コンクリート造、間口2.1m、塀 木造、瓦葺、延長19m、開戸付","structure_material":"門 鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0095","desc":"主屋玄関の正面に、高さ２．０ｍのＲＣ造洗出しで、頂部を段状に造る門柱を間口２．１ｍに建てる。通り沿いを生垣とし、その南端から隣地境にカーキ色の石州瓦葺の塀を設ける。方柱で、上部に横桟を渡し、壁は漆喰仕上げ腰モルタル塗とする。屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007545"},{"id":"00011552","register_sub_id":"101","register_pk":"210552","name":"福田平治・与志記念館（旧愛隣会館）","kana":"ふくだへいじ・よしきねんかん（きゅうあいりんかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市北田町48","lat":35.47581889,"lng":133.060795,"geo_status":"db","era":"昭和6年／昭和30年頃改修、昭和34年曳家、平成28年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"32-0179","desc":"育児院の講堂・礼拝堂として建てられた。木造二階建、桁行一三メートル、梁間六メートル、切妻造で、小屋組はキングポストトラスとする。外壁はドイツ壁風のモルタル仕上げとし、礼拝室両脇に縦長窓を並べ、急勾配の屋根と共に特徴的な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011552"},{"id":"00002813","register_sub_id":"101","register_pk":"103803","name":"岡山禁酒会館","kana":"おかやまきんしゅかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区丸の内1-1-157","lat":34.665112,"lng":133.930679,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造3階建、スレート葺、建築面積145㎡","structure_material":"木造3階建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0056","desc":"岡山城西の丸西手櫓に隣接した縦長の敷地に建つ。木造３階建で，寄棟造・スレート葺（一部鉄板葺）の屋根は３階部分で腰折れ風に処理する。ドイツ壁風と白タイル張を組み合わせ垂直性を強調した正面の意匠と相俟って，市街地の歴史的景観の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002813"},{"id":"00012816","register_sub_id":"101","register_pk":"367719","name":"邑久光明園恩賜会館","kana":"おくこうみょうえんおんしかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和16年／平成15年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 317","desc":"瀬戸内海の長島西部にあるハンセン病療養施設で、恩賜会館は敷地中央部に建つ当施設の象徴的存在。木造平屋建、半切妻造妻入で、正面は中央車寄上部の壁面を突出して三連アーチ窓を配し、両側下屋の破風を延ばして妻を二重に現すなど特徴的な造形表現とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012816"},{"id":"00012817","register_sub_id":"101","register_pk":"367720","name":"邑久光明園旧裳掛小・中学校第三分校","kana":"おくこうみょうえんきゅうもかけしょう・ちゅうがっこうだいさんぶんこう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和14年／平成14年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 318","desc":"敷地東部の木尾湾を望んで北面して建つ。木造平屋建、切妻造セメント瓦葺、外壁下見板張で正面中央に切妻造の玄関を出す。正背面に欄間付の硝子窓を並べて採光を確保し、トラス小屋組と軸部を方杖で緊結して補強する。療養施設附属の学校建築の貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012817"},{"id":"00012820","register_sub_id":"101","register_pk":"367723","name":"邑久光明園瀬溝桟橋","kana":"おくこうみょうえんせみぞさんばし","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和24年／昭和46年・平成16年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"石造、延長11m","structure_material":"石造","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 321","desc":"施設西部の官舎区にある、対岸に本土を望む波止場の埠頭。花崗岩の谷積、幅2･8メートル、長さ10メートル、高さ1･5メートルの規模で、石積頂部にコンクリートを打設する。島と本土を結んだ職員用の船着場で、昭和期における療養施設の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012820"},{"id":"00012819","register_sub_id":"101","register_pk":"367722","name":"邑久光明園物資運搬斜路","kana":"おくこうみょうえんぶっしうんぱんしゃろ","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"コンクリート造、延長45m","structure_material":"コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 320","desc":"敷地南部の波止場の西斜面にある、中央部高台の施設に物資を引上げるためのトロッコ軌道。コンクリート造、幅2･7メートル、長さ45メートル、高低差23メートルの規模で、北に軌道、南に階段を設ける。昭和期の鋼索式の傾斜地輸送設備として貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012819"},{"id":"00012818","register_sub_id":"101","register_pk":"367721","name":"邑久光明園奉安殿","kana":"おくこうみょうえんほうあんでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和18年／平成21年改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積2.1㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 319","desc":"敷地北部の高台に南面して建つ。鉄筋コンクリート造、高欄付基壇に建つ切妻造銅板葺で、正面に鉄扉を備える。棟上に千木と鰹木を載せ、外壁の四隅に円柱形を表す。内部は一室で床を板敷、壁を板張、天井を格天井とする。類例の少ない療養施設附属の奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012818"},{"id":"00002310","register_sub_id":"101","register_pk":"103300","name":"旧倉敷天文台スライディングルーフ観測室","kana":"きゅうくらしきてんもんだいすらいでぃんぐるーふかんそくしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県倉敷市福田町古新田940","lat":34.53513611,"lng":133.76969167,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造一部煉瓦造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造一部煉瓦造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"33 － 0053","desc":"日本最初の民間天文台として知られる。東西４．４ｍ，南北５．３ｍの平面規模で，鉄板張の切妻屋根を破風に沿って東西に滑らせて開閉する。基礎は煉瓦造で１．１ｍと高く，上部は下見板張とし，望遠鏡の基礎は別に独立して造る。科学史上においても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002310"},{"id":"00008367","register_sub_id":"101","register_pk":"134009","name":"旧中島病院本館","kana":"きゅうなかしまびょういんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市田町122","lat":35.06250221,"lng":133.99492913,"geo_status":"db","era":"大正6年／平成21年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、鉄板葺一部スレート葺、建築面積127㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"33 － 0234","desc":"津山城西方の市街地に所在。木造２階建で、東正面にポーチを付け、その屋根をドーム状につくる。当初はスレート葺で、ドーム部分に名残を留める。壁は小豆色のモルタル掻き落としで、コリント式の柱や窓飾り等を人造石とする。城下の町並に彩りを添える洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008367"},{"id":"00005504","register_sub_id":"101","register_pk":"106492","name":"定金家住宅主屋","kana":"さだかねけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷229-14","lat":34.54053663,"lng":133.62318777,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積90㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0112","desc":"東を正面として建つ。木造２階建で，東半が洋館，西半が和風住宅になる。洋館は正面中央の玄関を境に左右対称とし，スティックスタイル風の外観で，縦長窓の上を櫛形ペディメントを飾り，妻飾はハンマービームトラスを模す。調和のとれた意匠をもつ洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005504"},{"id":"00000896","register_sub_id":"101","register_pk":"101886","name":"津山基督教図書館","kana":"つやまきりすときょうとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市山下98-1","lat":35.06078343,"lng":134.00450387,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造３階建，銅板葺，建築面積230㎡","structure_material":"木造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0020","desc":"津山城跡の前面の角地に建つ。内村鑑三の弟子森本慶三が創設した建物で，設計は桜庭駒五郎。イオニア式の壁付柱を持ちゲーブルを設けた南面中央入口部の構え，東面にある時計付の塔屋，壁面各所の浮き彫り等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000896"},{"id":"00001645","register_sub_id":"101","register_pk":"102635","name":"永井家住宅主屋","kana":"ながいけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県和気郡和気町和気378","lat":34.79939062,"lng":134.14581307,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0047","desc":"吉井川と金剛川の合流点近くに位置し，県道に南面して建つ。桁行５間，梁行４間半規模の総２階建，桟瓦葺寄棟造，ドイツ下見の洋館で，東南隅に角塔を建てる。歯科診療所として建築され，地元では最初期の西洋館として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001645"},{"id":"00012815","register_sub_id":"101","register_pk":"367718","name":"長島愛生園園長官舎","kana":"ながしまあいせいえんえんちょうかんしゃ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 316","desc":"敷地西部の官舎区の南端に西面して建つ。寄棟造桟瓦葺の平屋建で、北端に切妻造妻入の玄関付洋館を設ける。洋館に応接間と客座敷を設け、主体部に三室を並べて前後に廊下を通し、西南隅に水回りをまとめる。昭和期における和洋館併設の中流住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012815"},{"id":"00016725","register_sub_id":"101","register_pk":"579209","name":"長島愛生園汽缶場","kana":"ながしまあいせいえんきかんば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.680201,"lng":134.249572,"geo_status":"db","era":"昭和5年／昭和37年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、人工スレート葺、建築面積224㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0394","desc":"敷地中央の平地に位置する温熱供給施設。鉄筋コンクリート造平屋建人工スレート葺で西面入口に庇を付し、北西に宿直棟を突出。内部は土間で、小屋組は鉄骨のトラスとする。大屋根頂部に越屋根を設けた妻面が特徴的な姿で、愛生園の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016725"},{"id":"00016723","register_sub_id":"101","register_pk":"579207","name":"長島愛生園旧患者売店","kana":"ながしまあいせいえんきゅうかんじゃばいてん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.680435,"lng":134.249967,"geo_status":"db","era":"昭和5年／昭和中期増築、平成前期・令和5年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、セメント瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0392","desc":"瀬戸内海の長島中央部にあるハンセン病療養施設の患者用の旧売店。敷地中央の高台に南面して建つ、平屋建切妻造セメント瓦葺で東に落棟の増築棟を延ばす。外壁ドイツ下見板張、軒廻り漆喰塗。正面軒の切妻破風と漆喰レリーフが外観のアクセントとなる旧売店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016723"},{"id":"00012811","register_sub_id":"101","register_pk":"367714","name":"長島愛生園旧事務本館","kana":"ながしまあいせいえんきゅうじむほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／昭和前期増築、平成10年・同15年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階一部平屋建及び木造平屋建、建築面積371㎡","structure_material":"鉄筋コンクリート造2階一部平屋建及び木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 312","desc":"瀬戸内海の長島中央部にあるハンセン病療養施設。旧事務本館は施設の中心に建つ鉄筋コンクリート造二階建一部平屋建で、南面東寄りに車寄を付す。西側の翼棟は木造の増築部。正円アーチ形の車寄開口部や二階窓、大ぶりのパラペットなど表現主義の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012811"},{"id":"00012812","register_sub_id":"101","register_pk":"367715","name":"長島愛生園旧収容所","kana":"ながしまあいせいえんきゅうしゅうようじょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／平成29年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積190㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 313","desc":"北岸の波止場に建つ新規入園者の停留施設。鉄筋コンクリート造平屋建で北面中央部に玄関を出し、縦長窓を規則的に並べる。北を廊下、南を病室とし、東半の廊下沿いに診療室や浴室を設ける。束立て板張の床など昭和初期の鉄筋コンクリート工法の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012812"},{"id":"00012814","register_sub_id":"101","register_pk":"367717","name":"長島愛生園旧洗濯場","kana":"ながしまあいせいえんきゅうせんたくば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積156㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 315","desc":"旧日出浴場南側に並んで東面して建つ。鉄筋コンクリート造平屋建、桁行5間梁間2間で、正面の柱間毎に出入口を設け、側背面に縦長窓を並べる。構造体と外壁仕上に旧状を留め、洗濯場まで鉄筋コンクリートでつくるところに内務省直轄事業の特別さが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012814"},{"id":"00012813","register_sub_id":"101","register_pk":"367716","name":"長島愛生園旧日出浴場","kana":"ながしまあいせいえんきゅうひでよくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／昭和30年改修・増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部木造平屋建、建築面積167㎡","structure_material":"鉄筋コンクリート造一部木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 314","desc":"敷地東部の居住区裏山東裾に東面して建つ。鉄筋コンクリート造平屋建、天井に湯気抜とトップライトを設ける。中央から南側が男湯で、北側の女湯は角屋から出入りする。戦前に珍しい鉄筋コンクリートの浴場で温水シャワーを備えるなど当園の特別さが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012813"},{"id":"00016724","register_sub_id":"101","register_pk":"579208","name":"長島愛生園恵の鐘","kana":"ながしまあいせいえんめぐみのかね","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.681702,"lng":134.249585,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、面積9.2㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0393","desc":"敷地中央北寄りの丘陵に位置する鐘楼。高い基壇に建つ鉄筋コンクリート造切妻造桟瓦葺の南北棟で東西面に千鳥破風を飾る。太い円柱を４本立て、ヴォールト天井の中央に鐘を吊る。和洋折衷の独特な外観で、職員と入所者が石材を運んだと伝える記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016724"},{"id":"00014672","register_sub_id":"101","register_pk":"515214","name":"林原美術館中蔵","kana":"はやしばらびじゅつかんなかぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66389444,"lng":133.93327778,"geo_status":"db","era":"明治前期／明治26年頃・同42年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0353","desc":"敷地北側石垣に沿って建つ土蔵３棟のうちの中央棟で、旧生坂向邸から移築されたもの。土蔵造二階建切妻造本瓦葺、外部は漆喰塗り、腰下は海鼠壁、出隅をＬ形役物瓦と平瓦の四半張で飾り、二階壁に水切瓦付の海鼠壁の帯を廻す外観意匠で町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014672"},{"id":"00014674","register_sub_id":"101","register_pk":"515216","name":"林原美術館長屋門","kana":"はやしばらびじゅつかんながやもん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66360833,"lng":133.93369722,"geo_status":"db","era":"江戸末期／明治後期移築、昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0355","desc":"敷地東側の道路から入った位置に東面して建つ、土蔵造入母屋造本瓦葺の長屋門。旧生坂向邸の敷地から明治末までに移築されたもの。外部は漆喰塗りで腰下は海鼠壁、柱梁にトガの良材を用いる。池田家、生坂家の遺構としても貴重で武家屋敷構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014674"},{"id":"00014673","register_sub_id":"101","register_pk":"515215","name":"林原美術館西蔵","kana":"はやしばらびじゅつかんにしぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66391111,"lng":133.933025,"geo_status":"db","era":"明治14年／明治42年頃移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0354","desc":"敷地北側石垣に沿って建つ土蔵３棟のうちの西棟。土蔵造二階建切妻造本瓦葺で、旧生坂向邸からの移築時に２階床を下げて、小屋裏へ収納棚を増設した。外部は漆喰塗り、腰下と出隅を海鼠壁で飾り、二階壁にも海鼠壁の帯を巡らす外観意匠で町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014673"},{"id":"00014671","register_sub_id":"101","register_pk":"515213","name":"林原美術館東蔵","kana":"はやしばらびじゅつかんひがしぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66400556,"lng":133.93345278,"geo_status":"db","era":"明治前期／明治42年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0352","desc":"敷地北側石垣の縁に沿って建つ土蔵３棟のうちの東棟で、旧生坂向邸から明治末に移築されたもの。土蔵造二階建切妻造本瓦葺、外部は漆喰塗り、腰下は平瓦四半張。膨大な貴重資料を収蔵した旧池田家文庫として貴重な建物で、武家の蔵群として町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014671"},{"id":"00014670","register_sub_id":"101","register_pk":"515212","name":"林原美術館本館","kana":"はやしばらびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66363889,"lng":133.93331667,"geo_status":"db","era":"昭和38年／昭和61年増築","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積938㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0351","desc":"岡山城二の丸跡に建つ前川國男設計の鉄筋コンクリート造の美術館。中庭を中心に単位空間を連続した回遊性を重視する平面計画、外壁の焼過ぎ煉瓦とＰＣ板の採用による生産性とディテール精度の追求等、意匠的・技術的にも後の前川の作品に通じる建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014670"},{"id":"00007689","register_sub_id":"101","register_pk":"108671","name":"若竹の園保育園舎事務室棟","kana":"わかたけのそのほいくえんしゃじむしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市中央1-262-1他","lat":34.59502245,"lng":133.77002383,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0228","desc":"通り西側の敷地奥に中央に建つ。広い一室からなる寄棟造の保育室から北に切妻造の事務室を張り出し、さらに園門に向けて東南方向へ切妻造の玄関を設ける。屋根スレート葺で、軒先近くを緩勾配とする。玄関は入口に石積アーチを造るなど、穏やかな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007689"},{"id":"00007690","register_sub_id":"101","register_pk":"108672","name":"若竹の園保育園舎幼児保育南棟","kana":"わかたけのそのほいくえんしゃようじほいくみなみとう","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市中央1-262-1他","lat":34.59484569,"lng":133.77001979,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0229","desc":"事務室棟の南に位置する。南北棟の北側で東に矩折れに曲がり切妻を正面に見せる。スレート葺で、軒先を緩勾配とする。２室の保育室を南北に配し、南室東側に煉瓦敷のテラスを設けて、園庭と一体感をもたせる。装飾は少なく、簡明で優美な園舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007690"},{"id":"00013450","register_sub_id":"101","register_pk":"368535","name":"翁座","kana":"おきなざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県府中市上下町上下字岩崎2077","lat":34.69653611,"lng":133.12315833,"geo_status":"db","era":"大正14年／昭和21年増築、平成6年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積418㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"34 － 0283","desc":"石州街道上下宿の東郊に位置する芝居小屋。木造二階建、切妻造桟瓦葺で、小屋組はキングポストトラス。吹抜の客席と回舞台装置付の舞台を中心に各室を配す。二階はコ字形に桟敷席と擬宝珠高欄を廻らす。歴史的な町並みの中核として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013450"},{"id":"00015373","register_sub_id":"101","register_pk":"532497","name":"旧小野産婦人科医院","kana":"きゅうおのさんふじんかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市十四日元町514-3","lat":34.40938611,"lng":133.20275556,"geo_status":"db","era":"昭和13年／昭和40年代・令和5年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積100㎡","structure_material":"木造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0312","desc":"尾道の中心部に位置する旧産婦人科医院。隅切した角地に建つ木造三階建寄棟造鉄板葺で一階は診察室や手術室、二階は病室、三階は居住用和室を配す。外観モルタル吹付仕上、腰は釉薬スクラッチタイル貼。庇や付柱など直線的構成で角地を強調した外観が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015373"},{"id":"00014677","register_sub_id":"101","register_pk":"515219","name":"旧村井醫院診療棟","kana":"きゅうむらいいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市御調町市字市1200","lat":34.51214444,"lng":133.14733611,"geo_status":"db","era":"大正7年／昭和中期・平成24年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"34 - 0303","desc":"街道の交点に栄えた御調町市にある洋風医院建築。寄棟造妻入桟瓦葺の平屋建。外壁モルタル塗で下見板張・定規柱風の意匠とし、ペディメント付上下窓を並べる。内部は正面角屋を天井飾付診察室、奥にレントゲン室とし中廊下で繋ぐ。街道の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014677"},{"id":"00014678","register_sub_id":"101","register_pk":"515220","name":"旧村井醫院門柱","kana":"きゅうむらいいいんもんちゅう","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市御調町市字市1200","lat":34.51218333,"lng":133.14743889,"geo_status":"db","era":"大正7年頃／昭和中期改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、間口1.9m、石柵付","structure_material":"石造","registered":"2023.08.07(令和5.08.07)","register_no":"34 - 0304","desc":"御調町市の出雲街道沿いにある洋風医院の門柱。花崗岩の角柱で正方形断面、高さ２・９メートル、頂部兜巾で首を造り、江戸切仕上とする。付設の柵は円柱親柱と鉄丸棒からなり、前栽を囲って門柱と調和する。医院表構えとなって街道の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014678"},{"id":"00012245","register_sub_id":"101","register_pk":"353045","name":"瀧口家住宅長屋門及び診療所","kana":"たきぐちけじゅうたくながやもんおよびしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.816159,"lng":133.045449,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"長屋門 土蔵造2階建、瓦葺、建築面積78㎡ 診療所 土蔵造平屋建、瓦葺、建築面積74㎡","structure_material":"長屋門 土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-254","desc":"敷地北面に建つ。二階建の長屋門と平屋建の診療所からなる。長屋門は、西側の室と二階を院長の居室や入院施設にあて、二階廊下には腰掛を設ける。診療所は、診療室や分娩室の南面に窓を開き採光を得る。明治後期の地方病院の形式をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012245"},{"id":"00012241","register_sub_id":"101","register_pk":"353041","name":"瀧口家住宅納屋","kana":"たきぐちけじゅうたくなや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815861,"lng":133.04553,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-250","desc":"敷地東面に建ち主屋に面して出入口を開く。建築面積八七平方メートルで西面は下屋を取り込む。一階は往診用の馬車に使う厩と、もと養蚕の作業所で、二階は飼料置き場に使用されていた。柱に栗材の曲がり材を用い地域性を示しており屋敷構成に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012241"},{"id":"00000549","register_sub_id":"101","register_pk":"101539","name":"南山資料館","kana":"なんざんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市幸崎町能地3369","lat":34.33599824,"lng":133.03439619,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，瓦葺，建築面積85㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"34 － 0015","desc":"木造２階建の診療所建築。１階が診療施設，２階は接客空間とされていた。現在では１階部分を中心として，郷土出身の芸術家清水南山の資料館となっている。上部にアーチ窓を設ける正面中央の玄関が意匠上のアクセントで，洋風の建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000549"},{"id":"00000489","register_sub_id":"101","register_pk":"101479","name":"岩国徴古館","kana":"いわくにちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県岩国市横山2-7-19","lat":34.17096809,"lng":132.17717471,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"煉瓦造平屋建一部2階建，瓦葺，建築面積574㎡","structure_material":"煉瓦造平屋建一部2階建","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0018","desc":"昭和１５年に財団が設立を議決，２０年３月に竣工し，２５年以降博物館となった。ドイツ古典主義の影響がみられる意匠は，低く押さえた外観，正面の角柱の列柱，内部のすそ広がりの柱等が特徴である。設計は，早稲田大学教授で岩国中学出身の佐藤武夫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000489"},{"id":"00006706","register_sub_id":"101","register_pk":"107689","name":"岩国徴古館第一収蔵庫","kana":"いわくにちょうこかんだいいちしゅうぞうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県岩国市横山2-7-19","lat":34.170975,"lng":132.177139,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"35 － 0058","desc":"徴古館の北東に位置する。桁行５間梁間３間規模、切妻造桟瓦葺の２階建土蔵で、徴古館側の西面全面に１間半幅の下屋を差し掛けて蔵前とする。錦川の氾濫に備えて高い石積基礎上に建つ。旧岩国藩主吉川家の別邸内土蔵を移設と伝え、堂々たる姿を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006706"},{"id":"00007407","register_sub_id":"101","register_pk":"108389","name":"旧日下医院正門及び塀","kana":"きゅうくさかいいんせいもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.0763029,"lng":131.77227532,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"正門 石造、間口10m 塀 煉瓦造、総延長117m、北門・東門付","structure_material":"正門 石造","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0066","desc":"本館正面に正門を構え、敷地周囲に塀をまわす。門柱は高さ２．５ｍの石造角柱で、頂部を球状に加工する。塀は高さ１．７ｍで、延長１１７ｍに及び、北と東面に通用門を開く。モルタル仕上げとし、基礎や笠木に御影石を使う。本館と一体感のある景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007407"},{"id":"00007406","register_sub_id":"101","register_pk":"108388","name":"旧日下医院別館","kana":"きゅうくさかいいんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.076134,"lng":131.772095,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部平屋建、鉄板葺、建築面積59㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0065","desc":"本館南面に建つ木造鉄板葺。東半部が２階建で、西半部は北寄りに階段を設け、南を平屋建の陸屋根とし、物干場として利用した。外壁をモルタル塗ドイツ壁とするなど、基本的に本館と共通する意匠であるが、軒まわりや幾何学的装飾の細部などに違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007406"},{"id":"00007405","register_sub_id":"101","register_pk":"108387","name":"旧日下医院本館","kana":"きゅうくさかいいんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.076221,"lng":131.772125,"geo_status":"db","era":"昭和3／昭和前期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0064","desc":"西面して建つ木造２階建。Ｌ字型に落棟を設ける寄棟造瓦葺。正面は中央北寄りに車寄を設け、窓を南に３ヶ所、北に２ヶ所開け、柱型を表す。外壁はモルタル塗で、２階窓下などに幾何学的な装飾を施す。セセッション風意匠になる昭和初期の建築として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007405"},{"id":"00000710","register_sub_id":"101","register_pk":"101700","name":"クリエイティブ・スペース赤れんが（旧山口県立山口図書館書庫）","kana":"くりえいてぃぶ・すぺーすあかれんが（きゅうやまぐちけんりつやまぐちとしょかんしょこ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市中河原町76","lat":34.18030346,"lng":131.4772703,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造２階建，建築面積141㎡","structure_material":"煉瓦造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"35 － 0020","desc":"明治３６年開館の県立図書館の増設書庫として建設。妻面の仕上がりからすると更なる増築が想定されていたようである。設計は，県庁舎新築の監督にあたった藤本勝往。「赤れんがの館」として県市民に親しまれ，平成４年アートスペースとして保存再生された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000710"},{"id":"00001955","register_sub_id":"101","register_pk":"102945","name":"四熊家住宅診療棟","kana":"しくまけじゅうたくしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県周南市土井1-1-1","lat":34.08002342,"lng":131.7729681,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"35 － 0037","desc":"主屋の玄関脇に前方に突出して設けられた付属棟で，約５メートル四方の診療室とその東脇の出入口・受付からなる。外壁は鼠漆喰塗りとし，縦長の上下げ窓の窓枠や隅の柱形は繰形を付けて白漆喰で仕上げ，控えめながら洋風の意匠を造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001955"},{"id":"00001138","register_sub_id":"101","register_pk":"102128","name":"下関市立長府博物館本館（旧長門尊攘堂）","kana":"しものせきしりつちょうふはくぶつかんほんかん（きゅうながとそんじょうどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市長府川端1-2-5","lat":33.99548419,"lng":130.98237633,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積315㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"35 － 0022","desc":"旧功山寺境内にある。地元出身の桂弥一が京都の尊攘堂にならって建てたもの。鉄筋コンクリート造，石貼りの躯体に和風屋根をのせた姿には時代の特徴がよくあらわれている。屋根を２重にする外観全体の構成は国宝功山寺仏殿と似る。設計は潮見長彦と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001138"},{"id":"00001456","register_sub_id":"101","register_pk":"102446","name":"下横瀬公民館（旧明木村立図書館）","kana":"しもよこぜこうみんかん（きゅうあきらぎそんりつとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県萩市明木下横瀬","lat":34.32149117,"lng":131.39334489,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"35 － 0030","desc":"村立図書館の新館を移築・増築したもので，当初は地元の小学校敷地内に建っていた。校舎との連絡用渡り廊下の一部を玄関ポーチとして利用し，そこから縦長の欄間付上げ下げ窓を左右対称に配している。村民の文化教養向上に大きく貢献した建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001456"},{"id":"00008581","register_sub_id":"101","register_pk":"134977","name":"日清講和記念館","kana":"にっしんこうわきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市阿弥陀寺町5-4他","lat":33.95902544,"lng":130.94836306,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部地下1階建、瓦葺、建築面積138㎡","structure_material":"鉄筋コンクリート造平屋一部地下1階建","registered":"2011.01.26(平成23.01.26)","register_no":"35 － 0068","desc":"春帆楼の東南に位置し、西北を正面とする。棟の高いＲＣ造平屋建で、東寄りに地階を設ける。入母屋造妻入本瓦葺とし、玄関に庇を付ける。外観は腰石貼で、太い柱型を現し、上方に大きく矩形の窓を穿つ。組物や懸魚など伝統的な細部を配し、威風ある姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008581"},{"id":"00013457","register_sub_id":"101","register_pk":"368542","name":"旧北室醫院石垣","kana":"きゅうきたむろいいんいしがき","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1他","lat":34.04128611,"lng":134.02589444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、総延長64m","structure_material":"石造","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0212","desc":"北の一段低くなった吉野川側の敷地を支える石垣。北西角から北辺中程まで延び、敷地形状に合わせて雁行配置とする。吉野川流域で見られる阿波の青石（緑泥片岩）を主体に、平石や角石を積上げ、隅は算木積とする。敷地北辺の屋敷景観を整える構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013457"},{"id":"00013453","register_sub_id":"101","register_pk":"368538","name":"旧北室醫院主屋","kana":"きゅうきたむろいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04109167,"lng":134.02629444,"geo_status":"db","era":"明治34年／昭和前期増築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0208","desc":"敷地南東に南面して建つ、漢方医時代の主屋。木造２階建、入母屋造本瓦葺で、四周に下屋を廻し、正面西寄に入母屋玄関を付し、２階壁には木瓜枠の虫籠窓を穿つ。内部は表側に薬局、診療所、床付の座敷を並べ、奥側は住居部とする。重厚かつ上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013453"},{"id":"00013451","register_sub_id":"101","register_pk":"368536","name":"旧北室醫院診療所","kana":"きゅうきたむろいいんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1","lat":34.04107778,"lng":134.02596944,"geo_status":"db","era":"大正10年／昭和中期増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積194㎡","structure_material":"木造2階一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0206","desc":"吉野川南岸の敷地中央西寄に南面して建つ。木造２階建、寄棟造桟瓦葺の洋風建築で、正面に切妻破風と車寄を付す。外壁は柱や貫を現し、小壁を漆喰塗、他を板張とする。改造も少なく医療設備等も良く残り、地域医療を西洋医学で支えた当家の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013451"},{"id":"00013454","register_sub_id":"101","register_pk":"368539","name":"旧北室醫院土蔵","kana":"きゅうきたむろいいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04114722,"lng":134.02613611,"geo_status":"db","era":"明治11年","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0209","desc":"診療所東側に南面して建つ、漢方薬の原料等の保管蔵。土蔵造２階建、本瓦葺で、正面に桟瓦葺の深い下屋を付す。外壁は漆喰で軒裏まで塗込める。内部は板敷で、壁、天井に鉄板を張って区画し、保管棚を設ける。簡素な外観ながら、医院機能を補佐した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013454"},{"id":"00013456","register_sub_id":"101","register_pk":"368541","name":"旧北室醫院土塀","kana":"きゅうきたむろいいんどべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04096667,"lng":134.0262,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土塀、瓦葺、総延長58m","structure_material":"土塀","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0211","desc":"敷地南辺東半から東辺を囲う土塀。南辺土塀の中程を開いて端部を北側に屈折し、主屋への導入路とする。桟瓦葺、壁は漆喰塗で、南辺は腰を洗出仕上とし、要所に木製縦格子を入れた虫籠窓風の開口を穿つ。敷地南東の表構えを重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013456"},{"id":"00013455","register_sub_id":"101","register_pk":"368540","name":"旧北室醫院庭門及び内塀","kana":"きゅうきたむろいいんにわもんおよびうちべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04101111,"lng":134.02629167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、瓦葺、間口1.5m、内塀 木造、銅板葺、総延長5.4m","structure_material":"庭門 木造","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0210","desc":"主屋中程から南の土塀に至る一間棟門と板塀。門は腕木門で屋根は切妻造本瓦葺で、大棟端部に鯱を載せる。板塀は銅板葺で棟に雁振瓦を葺き、布着礎はモルタル塗で、松皮菱文を刻む。壁は大和打の竪板張で、襷桟の欄間を入れる。重厚な意匠の門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013455"},{"id":"00013452","register_sub_id":"101","register_pk":"368537","name":"旧北室醫院病棟","kana":"きゅうきたむろいいんびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1","lat":34.04119167,"lng":134.02591667,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0207","desc":"診療所北側に渡廊下を介して建つ入院病棟。木造平屋建、東西に長い寄妻造桟瓦葺で、東西に下屋を付す。内部は北に７室の病室、南に廊下を配し、南西角に水回りを突出する。病室は洋室で、板床に腰壁を廻らしベッドを置く。地方の医療施設の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013452"},{"id":"00014958","register_sub_id":"101","register_pk":"519218","name":"旧西野家住宅（徳島県立阿波十郎兵衛屋敷）辰巳座敷","kana":"きゅうにしのけじゅうたく（とくしまけんりつあわじゅうろべえやしき）たつみざしき","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市川内町宮島本浦184","lat":34.09158333,"lng":134.584,"geo_status":"db","era":"江戸末期／昭和29年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0226","desc":"吉野川河口の川内の角地に位置し、元藍商屋敷から移築された座敷。東面寄棟造、西面入母屋造桟瓦葺平屋建で三方に庇を付す。東は土間、西は二一畳の座敷で、北面に床、棚を構え、東面は襖絵で飾る。床廻りには銘木を用い、彫物のある筆返しなど上質な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014958"},{"id":"00014959","register_sub_id":"101","register_pk":"519219","name":"旧西野家住宅（徳島県立阿波十郎兵衛屋敷）長屋門","kana":"きゅうにしのけじゅうたく（とくしまけんりつあわじゅうろべえやしき）ながやもん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市川内町宮島本浦184","lat":34.09148611,"lng":134.58418611,"geo_status":"db","era":"安政2年(1855)／昭和29年移築","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0227","desc":"元藍商屋敷から移築された長屋門。敷地東辺に開く入母屋造本瓦葺の平屋建。両開板戸の中央門口を挟んで北に２室、南に１室を配す。外壁は腰を簓子下見板張とし、北寄りに出格子を配して瓦葺の小庇を付す。扉板など良材を用いた格式ある表構えで景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014959"},{"id":"00015513","register_sub_id":"101","register_pk":"533528","name":"貞光劇場","kana":"さだみつげきじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字宮下68-1他","lat":34.03806389,"lng":134.06124167,"geo_status":"db","era":"昭和7年／昭和中期改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積430㎡","structure_material":"木造平屋一部2階建","registered":"2025.08.06(令和7.08.06)","register_no":"36 - 0229","desc":"町の中心部に位置する旧芝居小屋。切妻造銅板葺で外壁を横板張とし、正面に大スパンアーチの玄関を備え、上部に屋号と劇場名を大きく記す。一階は舞台と吹抜の客席を設け、周囲に桟敷を配し、上部の格天井に往事の広告を残す。貞光町の隆盛を示す劇場建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015513"},{"id":"00016741","register_sub_id":"101","register_pk":"579225","name":"延寿閣別館","kana":"えんじゅかくべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県丸亀市一番丁4-乙","lat":34.285895,"lng":133.80108,"geo_status":"db","era":"昭和8年／令和5年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"37 - 0495","desc":"丸亀城跡三の丸にある迎賓施設。平屋建寄棟造桟瓦葺で、北に玄関、南に続き間座敷を配し、東・南に入側の広縁を廻らす。１５畳の座敷は床柱や床板に欅を用い、幅広の杉板を張った天井に棹を吹寄に配る。良材を吟味し、讃岐平野への眺望が優れた上質な座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016741"},{"id":"00001019","register_sub_id":"101","register_pk":"102009","name":"鎌田共済会郷土博物館（旧図書館）","kana":"かまたきょうさいかいきょうどはくぶつかん（きゅうとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県坂出市本町1-1-24","lat":34.31332183,"lng":133.85198971,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積444㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.12.11(平成10.12.11)","register_no":"37 － 0018","desc":"坂出の実業家鎌田勝太郎が慈善育英各種社会教育を目的に設立した財団法人の中核施設。香川県技師富士精一監修の下，竹中工務店の設計施工になる。我が国初期の財団法人の活動事情を示す遺構で，初期の本格的鉄筋コンクリート造図書館建築としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001019"},{"id":"00000551","register_sub_id":"101","register_pk":"101541","name":"琴平町公会堂","kana":"ことひらちょうこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県仲多度郡琴平町川西甲975-1","lat":34.18542776,"lng":133.81815389,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積914㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"37 － 0014","desc":"金刀比羅宮の参道沿いに建つ和風を基調とした大型の公会堂で，大きく玄関棟，ホール棟，和室棟から構成される。ホール内部は近年の改修で一新されたが，入母屋造の大屋根や玄関棟，和室棟の小屋根が取り付く優雅な外観は，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000551"},{"id":"00005036","register_sub_id":"101","register_pk":"106026","name":"堀家時計店","kana":"ほりけとけいてん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県丸亀市西平山町98","lat":34.293236,"lng":133.79541,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0282","desc":"丸亀駅の北東方に位置し，道路に北面して建つ。寄棟造，桟瓦葺の木造２階建で，正面をモルタル塗とした看板建築。もと医院で，端部など要所に柱形を現し，中央入口はやや壁面を前に突出して両脇に柱を建て，中央軒上部にはゲーブル状の装飾等を付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005036"},{"id":"00002844","register_sub_id":"101","register_pk":"103834","name":"山本医院","kana":"やまもといいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡多度津町大通り甲1019-1","lat":34.27342865,"lng":133.7513634,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0112","desc":"多度津町の大通りに南面して建つ。木造２階建，モルタル塗の洋風医院建築で，腰部の石張とせいの高いパラペットにより三層構成をとり，玄関部を薄く張り出して頂部を山形のゲーブル状に納めるなどの特徴があり，当地域でひときわ目立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002844"},{"id":"00011425","register_sub_id":"101","register_pk":"209262","name":"今治ラヂウム温泉本館","kana":"いまばりらぢうむおんせんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県今治市共栄町四丁目2-8","lat":34.069915,"lng":132.998546,"geo_status":"db","era":"大正後期／昭和63改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造2階建、建築面積408㎡、塔屋及び煙突付","structure_material":"鉄筋コンクリート造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"38－0115","desc":"今治の中心市街地に建つ鉄筋コンクリート造銭湯施設。陸屋根の本体中央に五角形平面に六角形平面を重ねた塔屋を掲げ、背面に八角形ドームを持つ男女浴室を並べる、極めて特異な外観を持つ。戦災を受けた今治で戦前より残る貴重なランドマークである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011425"},{"id":"00002185","register_sub_id":"101","register_pk":"103175","name":"内之浦公会堂","kana":"うちのうらこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石5番耕地41","lat":33.47605737,"lng":132.38860201,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、建築面積108㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0016","desc":"川之石港に臨む海岸沿いに建つ地域の公会堂建築。木造２階建，道路沿い西面中央に玄関ポーチを設け，外壁はセメントモルタル洗出し仕上げとし，陸屋根造に見せる。内部は２階を畳敷きの大広間とするなど地区公会堂の性格をもつ。棟梁は那須喜八郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002185"},{"id":"00003471","register_sub_id":"101","register_pk":"104461","name":"愛媛県教育会館","kana":"えひめけんきょういくかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市北持田町131-1","lat":33.845032,"lng":132.776794,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積561㎡","structure_material":"木造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"38 － 0043","desc":"木造３階建で，事務室，会議室，図書室などを設ける。洋風意匠を基調とし和風装飾を組み合わせる昭和前期に特徴的な意匠を持つ。外観は垂直性をやや強調し，玄関上部には和風意匠の直截な引用が見られる。設計は県建築技師の浅香了輔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003471"},{"id":"00002184","register_sub_id":"101","register_pk":"103174","name":"大西内科医院診療棟","kana":"おおにしないかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県四国中央市金生町下分1423","lat":34.0004503,"lng":133.58204444,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0015","desc":"敷地の北寄りにほぼ南面して建つ。木造平屋建，下見板張の医院建築で，外壁は洋風につくるが，屋根は伝統的な入母屋造，桟瓦葺，玄関ポーチも入母屋造の伝統的な車寄とする。道路側の東面に盲のファンライトつけるなど擬洋風的意匠にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002184"},{"id":"00007810","register_sub_id":"101","register_pk":"108791","name":"旧泉寿亭特別室棟","kana":"きゅうせんじゅていとくべつしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市立川町598-1","lat":33.90078785,"lng":133.30967259,"geo_status":"db","era":"昭和12／平成3移築改造","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"38 - 0091","desc":"桁行８．６ｍ梁間１１ｍの木造平屋建。入母屋造桟瓦葺で軒先を銅板葺とし、正面に庇を掛ける切妻屋根の玄関を西面に付ける。六畳と十畳の座敷を南北に配し、四周に縁をまわす。軒まわりに丸太材を多用し、随所に竹や杉皮等をあしらう数寄屋風のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007810"},{"id":"00004057","register_sub_id":"101","register_pk":"105047","name":"武徳殿","kana":"ぶとくでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市徳常町4-6","lat":33.963444,"lng":133.281128,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0058","desc":"石造基壇の上に東西棟で建つ。切妻造，桟瓦葺の主屋根の４周に下屋を廻し，下屋付け根上に高窓を配する。外周廻りの柱上に舟肘木を載せ，内部には５０畳敷規模の剣道場と柔道場を収める。主屋根中央の千鳥破風と入母屋造車寄を重ねた正面の構えに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004057"},{"id":"00013002","register_sub_id":"101","register_pk":"368080","name":"松山城内門","kana":"まつやまじょううちもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84559167,"lng":132.76560278,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造、瓦葺、間口3.2m、脇戸付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 141","desc":"天守と玄関多聞櫓の間に建つ一重櫓門。両下造本瓦葺、一間一戸脇戸付で、外壁は天守と一連の漆喰塗及び下見板張とする。上層は渡廊下とし、両側出入口に両開きの土戸を備える。天守北側の枡形を構成し、筋鉄門と同じく天守の堅固な門構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013002"},{"id":"00012996","register_sub_id":"101","register_pk":"368074","name":"松山城北隅櫓","kana":"まつやまじょうきたすみやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84560833,"lng":132.76540278,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 135","desc":"ロ字形平面の連立式天守西北隅に建つ、南隅櫓と同規模の二重二階櫓。入母屋造本瓦葺で、一重目西面に千鳥破風を付す。外観、構造とも南隅櫓と同形式として天守西面の構えを左右対称に整えるとともに、多層建物が連なる天守の荘重な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012996"},{"id":"00012998","register_sub_id":"101","register_pk":"368076","name":"松山城玄関","kana":"まつやまじょうげんかん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84555,"lng":132.76548889,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 137","desc":"玄関多聞櫓の南面西寄りに接続して建つ。式台と玄関多聞櫓に上がる階段からなり、上り勾配の向唐破風本瓦葺の屋根をかける。式台は側面に壁を設けず開放とし、正面柱上の虹梁に蟇股、小壁に筬欄間を備えるなど、天守玄関にふさわしい格調高いつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012998"},{"id":"00012997","register_sub_id":"101","register_pk":"368075","name":"松山城玄関多聞櫓","kana":"まつやまじょうげんかんたもんやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.845625,"lng":132.76549722,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 136","desc":"北隅櫓の東側に接続して建つ一重多聞櫓。東面入母屋造本瓦葺、東面南半に内門、南面西寄りに玄関を接続する。外壁は北隅櫓と一連の漆喰塗及び下見板張で、北面中央に庇付の石落しを付す。内部は南に廊下を通し、北に一室を配する。天守玄関部の構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012997"},{"id":"00012994","register_sub_id":"101","register_pk":"368072","name":"松山城小天守","kana":"まつやまじょうこてんしゅ","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84535833,"lng":132.76561667,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 133","desc":"ロ字形平面の連立式天守東南隅に建つ二重二階櫓。入母屋造本瓦葺で、一重目南面に千鳥破風を付す。外壁は漆喰塗、下層は腰簓子下見板張、軒裏まで塗込め、外側の東南二面に庇付の石落しを付す。天守に次ぐ規模で、天守中枢部の堂々たる構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012994"},{"id":"00012999","register_sub_id":"101","register_pk":"368077","name":"松山城十間廊下","kana":"まつやまじょうじゅっけんろうか","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84548889,"lng":132.76541944,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 138","desc":"南隅櫓と北隅櫓をつなぐ一重多聞櫓。両下造本瓦葺、外壁は南北両櫓と一連の漆喰塗及び下見板張とし、西面三箇所に庇付の石落しを付す。内部は一室で、天井を張らず和小屋を現し、外側の西面に狭間を整然と並べる。天守防御の城郭構造の要衝となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012999"},{"id":"00013001","register_sub_id":"101","register_pk":"368079","name":"松山城筋鉄門","kana":"まつやまじょうすじがねもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.845425,"lng":132.76567222,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造、瓦葺、間口3.0m、脇戸付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 140","desc":"天守と小天守の間に建つ一重櫓門。両下造本瓦葺、一間一戸脇戸付で、柱の角など要所に筋鉄を打つ。外壁は天守と一連の漆喰塗及び下見板張。上層は渡廊下とし、両側出入口に両開きの土戸を備える。天守南側の枡形を構成し、天守の堅固な門構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013001"},{"id":"00015256","register_sub_id":"101","register_pk":"530680","name":"松山城太鼓門","kana":"まつやまじょうたいこもん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84406944,"lng":132.76684167,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造、瓦葺、間口5.0m、建築面積21㎡、脇戸付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0190","desc":"昭和四七年に復元した木造櫓門。太鼓門は、筒井門とともに堅固な枡形を構成し、大手防御の要となる。石垣に挟まれる脇戸付櫓門で、上階は北続櫓と南続櫓に接続する。上階正背面には窓、正面廻りには狭間を開き、内法下を下見板張とし、他の櫓と意匠が揃う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015256"},{"id":"00015258","register_sub_id":"101","register_pk":"530682","name":"松山城太鼓門北続櫓","kana":"まつやまじょうたいこもんきたつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84410833,"lng":132.76683333,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0192","desc":"昭和四七年に復元した木造単層櫓。北続櫓は戦災前に既に失っていたが、残存する石垣の形状や、葛石上端の斫り状況、周囲の石段などにより続櫓が存在したと判断し、太鼓門上階の櫓から北の石垣上に南続櫓と外観意匠を揃えて復元。太鼓門の一郭を構成する続櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015258"},{"id":"00015257","register_sub_id":"101","register_pk":"530681","name":"松山城太鼓門南続櫓","kana":"まつやまじょうたいこもんみなみつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84403889,"lng":132.76685556,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0191","desc":"昭和四七年に復元した木造単層櫓。太鼓門上階の櫓から南の石垣に延び、石垣出隅に載る隅櫓。背面に出入口を設ける。屋根は太鼓門上階と一連の南北棟入母屋造本瓦葺とする。南東出隅に矩折に石落しを設け、太鼓門正面と太鼓櫓から続く一郭への射線を担う続櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015257"},{"id":"00015259","register_sub_id":"101","register_pk":"530683","name":"松山城太鼓櫓","kana":"まつやまじょうたいこやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84396944,"lng":132.76649167,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"木造二階建、瓦葺、建築面積99㎡","structure_material":"木造二階建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0193","desc":"昭和四八年に復元した木造二層隅櫓。太鼓門の西方、本丸南西隅の高石垣上に聳立。全体は矩折平面で下層は石垣に合わせ不整形平面とし、南西隅の上層も南北棟の不整形平面。西面に千鳥破風を飾り、一階の南西隅矩折と西面北端に石落しを備える厳重な構えの櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015259"},{"id":"00013000","register_sub_id":"101","register_pk":"368078","name":"松山城多聞櫓","kana":"まつやまじょうたもんやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84535,"lng":132.76550833,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 139","desc":"小天守と南隅櫓をつなぐ一重多聞櫓。両下造本瓦葺、外壁は各櫓と共通の漆喰塗及び下見板張とし、外側の南面に庇付の石落しを付す。内部は一室で、小天守側の上り階段上の出入口に両開きの土戸を備える。十間廊下と同じく天守防御の城郭構造を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013000"},{"id":"00014299","register_sub_id":"101","register_pk":"509689","name":"松山城筒井門","kana":"まつやまじょうつついもん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84368889,"lng":132.76679167,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡、脇戸付","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0163","desc":"昭和四六年に復元された木造櫓門。筒井門は本丸下段の正門であって太鼓門一郭のさらに南方に位置する。石垣に挟まれる脇戸付櫓門で、上階は西続櫓と東続櫓に接続する。上階正背面には窓、正面廻りには狭間を開き、内法下を下見板張とし、他の櫓と意匠が揃う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014299"},{"id":"00014301","register_sub_id":"101","register_pk":"509691","name":"松山城筒井門西続櫓","kana":"まつやまじょうつついもんにしつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84364444,"lng":132.76671667,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0165","desc":"昭和四六年に復元された木造単層櫓。筒井門上階の櫓から石垣上に西に接続し、北背面に若干突出する。屋根は筒井門上階と一連の東西棟入母屋造とし、北突出部にも入母屋造屋根を架ける。西南隅矩折れに石落しを設け、西の戸無門とともに独特の枡形を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014301"},{"id":"00014300","register_sub_id":"101","register_pk":"509690","name":"松山城筒井門東続櫓","kana":"まつやまじょうつついもんひがしつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84369722,"lng":132.76687778,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0164","desc":"昭和四六年に復元された木造単層櫓。筒井門上階の櫓から石垣上に東に接続し、折れ曲がって南正面に突出する。屋根は筒井門上階と一連の東西棟入母屋造本瓦葺とし、南突出部にも入母屋屋根を架ける。東には隠門が連続して建ち、松山城特有の縄張りを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014300"},{"id":"00012995","register_sub_id":"101","register_pk":"368073","name":"松山城南隅櫓","kana":"まつやまじょうみなみすみやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84536111,"lng":132.76540833,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 134","desc":"ロ字形平面の連立式天守西南隅に建つ二重二階櫓。入母屋造本瓦葺で、一重目西面に千鳥破風を付す。外壁は漆喰塗、下層を簓子下見板張とし、軒裏まで塗込める。外側の西北二面は下層の各隅に庇付の石落しを付し、上層に高欄を廻す。天守隅角部の構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012995"},{"id":"00007811","register_sub_id":"101","register_pk":"108792","name":"山根競技場観覧席","kana":"やまねきょうぎじょうかんらんせき","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市角野新田町3-2822-9他","lat":33.92348108,"lng":133.30983359,"geo_status":"db","era":"昭和3／昭和62改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、面積4319㎡","structure_material":"石造","registered":"2009.08.07(平成21.08.07)","register_no":"38-0092","desc":"国領川に面する敷地に建設された競技場の観覧席。西端において緩やかに湾曲する延長１７０ｍ、最大２７段の玉石空積による階段状の構造物で、背面の山の斜面の擁壁を兼ねる。鉱山職員の労働奉仕により築かれた福利厚生施設で、鉱山における生活の一面を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007811"},{"id":"00002181","register_sub_id":"101","register_pk":"103171","name":"和田医院診療棟","kana":"わだいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市川之江町1746","lat":34.01260548,"lng":133.57253293,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0012","desc":"川之江市街中心部の角地に建つ木造２階建，切妻造，下見板張の医院建築。ハンマービームを用いた妻の構成や軒下の瓔珞飾りが明治期洋館の意匠的特徴を伝えており，線の細いスティックワークにも特色がある。市内最初期の洋館として市民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002181"},{"id":"00014426","register_sub_id":"101","register_pk":"511415","name":"足摺海底館","kana":"あしずりかいていかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"高知県","address":"高知県土佐清水市三崎4124-1先","lat":32.78596111,"lng":132.86013056,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄骨造4階建、高さ24m、建築面積119㎡、連絡橋付","structure_material":"鉄骨造4階建","registered":"2022.10.31(令和4.10.31)","register_no":"39 - 0305","desc":"竜串海域公園に築かれた海中展望塔。円筒形塔部と十字形平面の展望室を、Ｈ型鋼と外殻板等の全溶接で一体化した鋼構造物。海岸とは連絡橋で接続。丸窓を多用し、頂部にアクリルブロックを廻らす。自然美の中で異彩を放つ近未来的デザインの海洋レジャー施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014426"},{"id":"00012850","register_sub_id":"101","register_pk":"367753","name":"海のギャラリー","kana":"うみのぎゃらりー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"高知県","address":"高知県土佐清水市竜串3908-1","lat":32.78857778,"lng":132.86579722,"geo_status":"db","era":"昭和41年／平成17年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積380㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 304","desc":"竜串海岸にある林雅子設計の展示施設。鉄筋コンクリート折板構造で、二枚貝が天に開く様をモダニズムの造形表現でまとめる。内部は天窓とした大棟からの採光が水中のような幻想的な空間をつくる。デッドスペースが皆無で構造即意匠を旨とする林らしい作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012850"},{"id":"00011583","register_sub_id":"101","register_pk":"210512","name":"織田歯科医院主屋","kana":"おだしかいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高知市升形76-2","lat":33.55802306,"lng":133.52818194,"geo_status":"db","era":"大正14年／平成27年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積93㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"39-0291","desc":"高知城の南西、旧武家地に建つ。鉄筋コンクリート造二階建、塔屋付。大オーダーの柱型を現して垂直性を強調するとともに、正面中央にはバロック風の装飾壁を立ち上げるなど、様式を混在させつつ装飾豊かに仕上げる。県内でも最初期の鉄筋コンクリート造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011583"},{"id":"00011584","register_sub_id":"101","register_pk":"210513","name":"織田歯科医院塀","kana":"おだしかいいんへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高知市升形76-2","lat":33.55803111,"lng":133.52812694,"geo_status":"db","era":"大正14年／平成27年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、延長16m、潜戸付","structure_material":"鉄筋コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"39-0292","desc":"敷地の西辺を画す鉄筋コンクリート造の塀。主屋と共通した意匠となっており、二メートル毎に柱型を見せ、デンティルで装飾する。隅柱にはセセッションを思わせる飾りを頂部に設ける。主屋と一体となって、街区に近代的な景観を創出し、親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011584"},{"id":"00003014","register_sub_id":"101","register_pk":"104004","name":"川久保家住宅診察室及び納屋","kana":"かわくぼけじゅうたくしんさつしつおよびなや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町西佐古594","lat":33.590931,"lng":133.702789,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0064","desc":"中央に１間半の門を開く長屋門形式の建家で，正面右手に奥行３間規模の診察室を，左手に方２間に納屋を配し，納屋の西に桁行１間半の付属屋を張出す。川原石を積んだ基礎に建ち，外壁は縦板張，屋根は寄棟造とする。地方医家の診療施設遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003014"},{"id":"00009227","register_sub_id":"101","register_pk":"164780","name":"旧市川医院","kana":"きゅういちかわいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町安田字東新町1672-1","lat":33.4372856,"lng":133.98013724,"geo_status":"db","era":"大正2年／平成22年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造平屋建、桁行18.7メートル梁間5メートル、寄棟造桟瓦葺。外壁下見板張で、玄関正面を洋風の切妻屋根とし、フィニアルを飾る。内部はレントゲン室や診察室などを1列に並べる構成とする。瀟洒な医院建築と旧柏原家住宅が並び、特徴的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009227"},{"id":"00001352","register_sub_id":"101","register_pk":"102342","name":"末延家住宅（旧末延堂医院）主屋","kana":"すえのぶけじゅうたく（きゅうすえのぶどういいん）しゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡芸西村和食甲1586-1","lat":33.52020536,"lng":133.81021994,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"39 － 0003","desc":"診療所と住居を兼ねた木造２階建，下見板貼の洋館。東西棟の寄棟屋根の両端を切り落とした特徴的な屋根をもち，長屋門側の東面に居宅用の玄関を，また，南面の切妻屋根の張出しに診療所用の玄関を設ける。妻面の持送り意匠に時代的な特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001352"},{"id":"00012849","register_sub_id":"101","register_pk":"367752","name":"田所内科医院主屋","kana":"たどころないかいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県土佐市高岡町字明官寺甲2018-2","lat":33.49596111,"lng":133.42538861,"geo_status":"db","era":"明治25年頃／昭和60年頃・平成2年頃改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 303","desc":"市中心部にある診療所兼住宅で、敷地中央に北面して建つ。入母屋造桟瓦葺の平屋建で、北東二面に下屋を廻す。正面に濡縁、奧の前後に各4室を配し、西端に設けた座敷二室を診察室と検査室にあてる。旧市街の歴史的景観を伝える、地域に親しまれる現役の医院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012849"},{"id":"00004837","register_sub_id":"101","register_pk":"105827","name":"寺村徳夫家住宅主屋","kana":"てらむらのりおけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.51812717,"lng":133.91155135,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積201㎡、庭門付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0183","desc":"安芸土居城跡西南方の旧武家屋敷地に位置する。桁行１０間梁行５間，東西棟，寄棟造，桟瓦葺の木造平屋建で，南面玄関の西方を診療所待合，東方を２室の座敷，北側を家族の居間とし，西北にかま屋，西南に診察室を突き出す。伝統的形式による医家住居の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004837"},{"id":"00005933","register_sub_id":"101","register_pk":"106918","name":"嘉穂劇場","kana":"かほげきじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県飯塚市飯塚281-3、280-14、280-15、282-1","lat":33.63649,"lng":130.68718,"geo_status":"db","era":"昭和6／平成16改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積1117㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"40 － 0042","desc":"木造２階建の芝居小屋。鉄板葺屋根とし，正面は入母屋造，背面は切妻造とする。正面は１，２階共，両端間を除く各間に建具４枚を引違いに建込む。２階外側に手摺りを設け，妻に太鼓櫓を飾る。明治期から昭和初期に筑豊地方に建築された劇場建築の唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005933"},{"id":"00015396","register_sub_id":"101","register_pk":"532520","name":"旧大學湯","kana":"きゅうだいがくゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市東区箱崎三丁目3296","lat":33.6207,"lng":130.42211667,"geo_status":"db","era":"昭和7年／昭和28年増築、同44年・令和3年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0236","desc":"九州大学旧箱崎キャンパス西方にある旧銭湯。前庭に南面する切妻造平入鉄板葺で正面に半切妻造のポーチを付す。南に脱衣場、北に浴室を配し、上部吹抜中央に越屋根を設ける。下見板張の外観洋風の銭湯で、正面に大學湯の看板を掲げ、旧学生街の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015396"},{"id":"00001084","register_sub_id":"101","register_pk":"102074","name":"山辺道文化館（旧中野病院）診療棟","kana":"やまべのみちぶんかかん（きゅうなかのびょういん）しんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市草野町草野487-1","lat":33.31816646,"lng":130.6333221,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，瓦葺，建築面積270㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0006","desc":"久留米市の東方，草野地区に建つ大型の病院建築。煉瓦造基礎，木造下見板貼りの左右対称形の建物で，正面中央部を２階建とし，玄関上部にバルコニーを設ける。２階寄棟屋根から前面に突き出したペディメントの蟇股大瓶束風の飾りはユニーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001084"},{"id":"00001085","register_sub_id":"101","register_pk":"102075","name":"山辺道文化館（旧中野病院）倉庫","kana":"やまべのみちぶんかかん（きゅうなかのびょういん）そうこ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市草野町草野487-1","lat":33.31809142,"lng":130.63317456,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0007","desc":"診療棟の背後，南西方に建つ木造平屋建，桟瓦葺，寄棟屋根の倉庫建物。診療棟と同様，下見板貼りで軒下と腰を縦羽目とする。北面の東端と南面の中央東寄りに出入口を設け，内開き窓の外側に外開きの１枚戸を付けて盗難避けとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001085"},{"id":"00011836","register_sub_id":"101","register_pk":"210852","name":"大隈重信記念館","kana":"おおくましげのぶきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"佐賀県","address":"佐賀県佐賀市水ヶ江二丁目360-2","lat":33.247973,"lng":130.308791,"geo_status":"db","era":"昭和41年／昭和59年・平成27年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積223㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"41-0105","desc":"旧武家地にある大隈重信旧宅の東方に北面する。大隈重信生誕一二五周年を記念し、今井兼次が設計した。鉄筋コンクリート造で県木の楠の根幹と大隈のからだを曲面を多用して表現し、ステンドグラスにより室内を彩る。優れた施工技術に支えられた記念碑的建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011836"},{"id":"00014302","register_sub_id":"101","register_pk":"509692","name":"岡田三郎助アトリエ","kana":"おかださぶろうすけあとりえ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市城内一丁目15-23","lat":33.24514722,"lng":130.30101111,"geo_status":"db","era":"明治41年頃／大正後期増築・平成30年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積115㎡","structure_material":"木造平屋一部2階建","registered":"2022.06.29(令和4.06.29)","register_no":"41 - 0127","desc":"佐賀城内に移築した岡田三郎助のアトリエ。木造平屋一部二階建、金属板葺で、アトリエと女子洋画研究所からなる。内部は安定した採光を確保するため、随所に窓を穿つ。画壇の中心的サロンとなった明治期のアトリエで、初期女性洋画家教育施設としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014302"},{"id":"00010072","register_sub_id":"101","register_pk":"196219","name":"旧村上歯科医院（中町カーサ）","kana":"きゅうむらかみしかいいん（なかまちかーさ）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県唐津市中町1868","lat":33.44729771,"lng":129.96996197,"geo_status":"db","era":"昭和8／平成25改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積159㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0093","desc":"唐津城下の東寄りに位置する。もとは一階を和風の住宅、二階を洋風意匠の歯科診療所として使用した。外観は下見板張で二階に欄間付の縦長窓を並べ洋風とする一方で、一階の庭側に和風の縁を設けるなど、内部に呼応した外観とする。唐津中町通りの象徴的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010072"},{"id":"00001310","register_sub_id":"101","register_pk":"102300","name":"如蘭塾迎賓館","kana":"じょらんじゅくげいひんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県武雄市武雄町大字武雄4322","lat":33.18472603,"lng":130.02278655,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，平屋建，建築面積274㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"41 － 0013","desc":"塾舎及び寄宿舎棟の西側にあって、北面して建つ上質の建物。平面は、洋間及び広縁付きの大広間及び座敷等からなる棟を中心に、北側に玄関ホール・和室・厨房等を配した構成になる。設計は遠藤新と伝え、迎賓館としての品格を備えた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001310"},{"id":"00007934","register_sub_id":"101","register_pk":"108914","name":"杉森家住宅主屋","kana":"すぎもりけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市山内町大字宮野字水尾345","lat":33.20190944,"lng":129.92316585,"geo_status":"db","era":"明治24／昭和45改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"41-0076","desc":"敷地のほぼ中央に東面して建ち、南北２２ｍ東西１２ｍ、入母屋造及び切妻造、桟瓦葺である。正面左手に張り出す、もと待合室は、外壁を下見板張とし、アーチ状の破風板を付けたポーチを構える。明治期の診療所及び製薬所としての平面構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007934"},{"id":"00007935","register_sub_id":"101","register_pk":"108915","name":"杉森家住宅二階門","kana":"すぎもりけじゅうたくにかいもん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市山内町大字宮野字水尾345","lat":33.2017372,"lng":129.92332314,"geo_status":"db","era":"明治24／平成18改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積38㎡","structure_material":"木造2階一部平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"41-0077","desc":"主屋の前方、通りに面して建つ。桁行１５ｍ梁間３．２ｍ、切妻造桟瓦葺である。左右は長屋形式で、漆喰壁と腰竪板張とし、門の部分は櫓状に突き上げ、正・背面を下見板張とする。乗馬戴帽して潜ることを意図した設計と伝え、特徴的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007935"},{"id":"00016613","register_sub_id":"101","register_pk":"574975","name":"清恵庵","kana":"せいけいあん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"佐賀県","address":"佐賀県佐賀市城内一丁目15-23","lat":33.24432278,"lng":130.30056889,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"41 - 0136","desc":"佐賀城跡の外堀に南面して建つ茶室。設計は堀口捨己と早川正夫。入側を介して堀に面する開放的な七畳半広間と四畳半の茶室を南北に配し、東西に寄付、化粧室、台所を備える。寄付に舟入への階段を付す。照明を組み込んだ掛込天井など、堀口の特徴を示す茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016613"},{"id":"00001209","register_sub_id":"101","register_pk":"102199","name":"多久市西渓公園寒鶯亭","kana":"たくしせいけいこうえんかんおうてい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県多久市多久町1975","lat":33.25762676,"lng":130.08900572,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積293㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"41 － 0011","desc":"地元出身の炭鉱主高取伊好が寄贈した公会堂建築。棟札から、設計は杵島炭鉱技師の大坪彌平、棟梁は舩津虎五郎であることが判明している。１６畳３室の四周に縁を回し、入母屋の大屋根を架け、北面の中央に車寄を設ける。木造和風公会堂建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001209"},{"id":"00000368","register_sub_id":"101","register_pk":"101358","name":"徴古館","kana":"ちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市松原2-59","lat":33.25154654,"lng":130.30134912,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積206㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"41 － 0003","desc":"鍋島家所蔵資料を展示するための博物館施設として建てられた。正面ファサードは，ペアコラムを持つ半円形の車寄せと，２階の列柱からなり，背面は簡素な意匠である。県内のＲＣ造としては早い時期のものであり，また本格的な洋風意匠を持つ点にも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000368"},{"id":"00015524","register_sub_id":"101","register_pk":"533539","name":"弓張岳展望所","kana":"ゆみはりだけてんぼうしょ","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長崎県","address":"長崎県佐世保市矢岳町無番地","lat":33.17933056,"lng":129.70081667,"geo_status":"db","era":"昭和40年／平成22年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積69㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"42 - 0146","desc":"西海国立公園指定一〇周年を記念し、佐世保湾を望む丘に築いた展望所。前方二点と後方一点で支えた薄い反り屋根を鉄筋コンクリートＨＰシェル構造で実現。後方支柱は弓と波を象った本郷新のレリーフで飾る。自然景観にシャープな造形が際立つ坪井善勝の小品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015524"},{"id":"00000493","register_sub_id":"101","register_pk":"101483","name":"芦北町立武徳殿","kana":"あしきたちょうりつぶとくでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県葦北郡芦北町大字佐敷204","lat":32.30373348,"lng":130.50438978,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建，スレート葺，建築面積336㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"43 － 0008","desc":"剣道・柔道を行う武道場として建てられた（現在は歴史資料の保管場所に利用）。外観は２重だが，上は明かり取り窓で，内部は平屋である。１階窓を大きく開くなど武道場らしい工夫がみられる特徴ある建物で，町の象徴的な存在となっている。玄関は改造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000493"},{"id":"00016462","register_sub_id":"101","register_pk":"536529","name":"菊池恵楓園旧事務本館","kana":"きくちけいふうえんきゅうじむほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県合志市栄3796","lat":32.88261111,"lng":130.75194167,"geo_status":"db","era":"昭和26年／令和4年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積849㎡、鐘塔付","structure_material":"鉄筋コンクリート造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0220","desc":"黒石原の高原地帯の一角に位置する、ハンセン病療養施設の旧事務本館。設計施工は竹中工務店。鉄筋コンクリート造二階建で、正面中央に車寄を設け、鐘楼を屹立させる。軒と連続する横長窓が水平性を強調し、希望の塔と呼ばれる鐘楼が印象的な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016462"},{"id":"00005515","register_sub_id":"101","register_pk":"106503","name":"旧天草教育会館正門及び塀","kana":"きゅうあまくさきょういくかいかんせいもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市船之尾町336-3","lat":32.45731613,"lng":130.18658136,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"正門 鉄筋コンクリート造、間口4.4m、左右袖塀付、塀 鉄筋コンクリート造、延長40m","structure_material":"正門 鉄筋コンクリート造","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0080","desc":"正門は高さ１．９ｍ，間口４．４ｍ，鉄筋コンクリート造モルタル仕上げの門柱２本から成り，左右に袖塀が付く。塀は敷地境に残る総延長４０ｍの鉄筋コンクリート造。正門，塀共に，本館の玄関ポーチ柱の台座と一体的な意匠となり，統一的な外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005515"},{"id":"00005514","register_sub_id":"101","register_pk":"106502","name":"旧天草教育会館本館","kana":"きゅうあまくさきょういくかいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市船之尾町336-3","lat":32.45718379,"lng":130.18652314,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積271㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0079","desc":"敷地北西に北面して建つ。桁行１０間，梁間７間の規模で，切妻造，桟瓦葺の木造２階建。東側及び西側に階段室が付く。外壁は１階を下見板張，２階をモルタル塗とする。陸屋根庇を張出す玄関ポーチや欄間窓付引違窓からなる正面や東側外壁の丸窓等が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005514"},{"id":"00006954","register_sub_id":"101","register_pk":"107936","name":"旧熊本回春病院日光回転家屋","kana":"きゅうくまもとかいしゅんびょういんにっこうかいてんかおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県合志市栄3796","lat":32.88238908,"lng":130.7516971,"geo_status":"db","era":"昭和初期／昭和49移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、板葺、建築面積4.2㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"43 － 0103","desc":"ハンセン病救済施設内に日光浴を目的として建設された施設。床下５ヶ所に鋳鉄製キャスターを付け、建物全体が回転する。木造平屋建で、面積は４．２㎡。外壁は竪板張で、正面一杯に両開双折戸をたてる。機能に応じた、工夫がみられる建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006954"},{"id":"00014552","register_sub_id":"101","register_pk":"513966","name":"公衆温泉新温泉","kana":"こうしゅうおんせんしんおんせん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県人吉市紺屋町80-10","lat":32.21404167,"lng":130.75742778,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0200","desc":"温泉街に所在する公衆浴場。入母屋造妻入平屋建、正面庇付で男女別入口を開け、内部に番台を置き、脱衣室と浴場の田の字形平面としてガラス戸を多用。小屋はトラス組、ヴォールト形湯気抜を設ける。当地で大正から昭和にかけて建ち並んだ公衆温泉浴場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014552"},{"id":"00006036","register_sub_id":"101","register_pk":"107021","name":"慈愛園モード・パウラス記念資料館（旧宣教師館）","kana":"じあいえんもーど・ぱうらすきねんしりょうかん（きゅうせんきょうしかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市神水1-633-1","lat":32.784943,"lng":130.742249,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、スレート葺、建築面積87㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0086","desc":"広大な敷地の中央部に東西棟で南面して建つ。切妻造，スレート葺の木造２階建で，１階南側にリビングを置き，西に玄関，東にダイニングを配し，２階に寝室４室を設ける。西面に駒形の妻を２重に見せ，２階南面には大きく屋根窓を突き出す特徴的な形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006036"},{"id":"00009682","register_sub_id":"101","register_pk":"194678","name":"髙木医院","kana":"たかきいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字城山1323他","lat":32.98544362,"lng":130.81189827,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、スレート葺、建築面積114㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0122","desc":"県立菊池高校の向いに建つ木造二階建の医院建築で、一階を診療所、二階を応接間などとする。外観はハーフティンバー風とし、半切妻の銅板葺屋根にドーマー窓を載せ、玄関ポーチや窓廻りなどを中心に洋風意匠を巧みに取入れる。昭和初期の隈府の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009682"},{"id":"00000374","register_sub_id":"101","register_pk":"101364","name":"水俣市立蘇峰記念館（旧淇水文庫）","kana":"みなまたしりつそほうきねんかん（きゅうきすいぶんこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県水俣市陣内1-101-1","lat":32.21144771,"lng":130.4083839,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積288㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"43 － 0005","desc":"徳富蘇峰が自らの父の名前をとって建てた図書館。現在では記念館として用いられている。設計は地元の技術者渡辺録治によるが，蘇峰自身も関わったとされる。軒周りなどに装飾が配されているが，全体としては簡素な外観で，早い時期のＲＣ造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000374"},{"id":"00006975","register_sub_id":"101","register_pk":"107957","name":"リデル、ライト両女史記念館（旧熊本回春病院らい菌研究所）","kana":"りでる、らいとりょうじょしきねんかん（きゅうくまもとかいしゅんびょういんらいきんけんきゅうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪5-1","lat":32.81898291,"lng":130.73076593,"geo_status":"db","era":"大正8／昭和10増築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"43 － 0102","desc":"東西に長い寄棟造桟瓦葺の建物で、北面西端を半間突き出すL字型平面とし、正面中央にポーチを設ける。基礎は煉瓦造で石貼とする。１階を下見板張、２階をモルタル仕上げとし、白色に塗装する。１階庇や出窓、２階正面の手摺、建具など、瀟洒な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006975"},{"id":"00004480","register_sub_id":"101","register_pk":"105470","name":"龍驤館","kana":"りゅうじょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県宇城市三角町三角浦1320-22","lat":32.62212166,"lng":130.45608138,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び銅板葺、建築面積234㎡","structure_material":"木造平屋一部2階建","registered":"2004.11.08(平成16.11.08)","register_no":"43 － 0075","desc":"三角旧港東南に南面して建ち，桁行１５ｍ梁間９．２ｍの棟の南面両隅に，テラスで結ばれた宝形造，方形平面の二棟を配する。屋根は破風付の寄棟造で，軒下小壁ではハーフティンバー風に木部を見せる。大正期らしい簡略化されたスティックスタイルの建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004480"},{"id":"00007324","register_sub_id":"101","register_pk":"108306","name":"臼杵市立臼杵図書館荘田平五郎記念子ども図書館","kana":"うすきしりつうすきとしょかんしょうだへいごろうきねんこどもとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲5","lat":33.121655,"lng":131.798691,"geo_status":"db","era":"大正7／平成15改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0139","desc":"道路北側に占める敷地の南寄りに位置する。桁行１７ｍ梁間１２ｍ規模の木造２階建で、東西棟の入母屋造桟瓦葺とし、１階に庇をまわす。外壁は全面に下見板張で、東面中央に出入口を設ける。妻は漆喰塗とし、獅子口には「圖」の文字をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007324"},{"id":"00007325","register_sub_id":"101","register_pk":"108307","name":"臼杵市立臼杵図書館文庫","kana":"うすきしりつうすきとしょかんぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲5","lat":33.121754,"lng":131.798767,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積60㎡","structure_material":"土蔵造3階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0140","desc":"子ども図書館の北側に並行して建つ。土蔵造３階建、切妻造桟瓦葺で、各階上部に水切り瓦を付ける。漆喰仕上げで、北面は各階に８ヶ所の窓を穿ち、採光を取る。南面中央に出入口を開き、鉄扉をたてる。内部も漆喰仕上げで、窓位置に合わせて書棚を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007325"},{"id":"00014442","register_sub_id":"101","register_pk":"511431","name":"旧大分県立大分図書館（アートプラザ）","kana":"きゅうおおいたけんりつおおいたとしょかん（あーとぷらざ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"大分県","address":"大分県大分市荷揚町3-31","lat":33.24054722,"lng":131.60949444,"geo_status":"db","era":"昭和41年／平成9年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1，600㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2022.10.31(令和4.10.31)","register_no":"44 - 0234","desc":"建築家磯崎新の初期代表作。鉄筋コンクリート造三階建、地下一階の図書館建築。二階にエントランスを配し、一階・地下に書庫、二・三階に閲覧室等を配す。打放しの中空梁、巨大なペアウォールを用い、スキップフロアを多用した巧みな空間構成は独創的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014442"},{"id":"00000421","register_sub_id":"101","register_pk":"101411","name":"旧小幡記念図書館","kana":"きゅうおばたきねんとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県中津市1385","lat":33.60306499,"lng":131.1845894,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建，瓦葺，建築面積213㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"44 － 0018","desc":"慶應義塾の塾長をつとめた小幡篤次郎の寄贈図書を中心に明治４１年に設立された記念図書館を建て替えたもの。木造２階建で，立ちが高く，石張りの玄関ポーチ，連続するアーチ窓，軒廻りの装飾等に特徴がある。旧城下町に建つひときわ目立つ洋風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000421"},{"id":"00002869","register_sub_id":"101","register_pk":"103859","name":"旧長田医院","kana":"きゅうながたいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後大野市三重町市場1600-3","lat":32.98055471,"lng":131.58454709,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0082","desc":"木造２階建の病院建築。街路側は中央に玄関ポーチを備える洋風の立面を持ち，背面側はほぼ和風の意匠とする。１階には手術室・診察室，控室など病院機能を備え，２階には床棚を備える広間と四畳半の和室２室を配する。現在では喫茶店として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002869"},{"id":"00004193","register_sub_id":"101","register_pk":"105183","name":"竹瓦温泉","kana":"たけがわらおんせん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県別府市元町16-23","lat":33.277424,"lng":131.506012,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積712㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"44 － 0101","desc":"中央は入母屋造の２階建で，１階が休憩所や脱衣所，２階が床・棚付の畳敷大広間になる。浴室は東側に突出する平屋建で，西側の寄棟造の平屋建は砂風呂になる。変化に富んだ外観や正面の唐破風玄関など，重厚かつ豪華なつくりで，温泉街の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004193"},{"id":"00000111","register_sub_id":"101","register_pk":"101101","name":"野口病院管理棟","kana":"のぐちびょういんかんりとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市野口中町６-33","lat":33.28143237,"lng":131.49811394,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積563㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"44 － 0002","desc":"東側に尖塔屋根を軸とする左右対称のファサードを持ち，背面に２列に棟が伸び，中庭を囲む構成をとる。グレーのモルタルススペイン壁の上部に白漆喰のハーフティンバーがのる外壁に特徴があり，まちなみ景観のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000111"},{"id":"00005687","register_sub_id":"101","register_pk":"106675","name":"浜田温泉資料館","kana":"はまだおんせんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県別府市亀川浜田町3-21","lat":33.32996258,"lng":131.4941245,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"44 － 0116","desc":"亀川海岸砂丘上の共同浴場として建設。東面して建つ桁行１４ｍ，梁間８ｍの木造平屋建で，入母屋造，銅板葺。望楼状の宝形屋根を載せ東面と西面に千鳥破風を飾り，正面玄関を唐破風とする。平成１７年の修復工事により片側の浴室上に床を張り展示室とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005687"},{"id":"00012079","register_sub_id":"101","register_pk":"211020","name":"石井記念友愛社静養館","kana":"いしいきねんゆうあいしゃせいようかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡木城町大字椎木字上中原644-1","lat":32.142472,"lng":131.448512,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"45-91","desc":"岡山で孤児救済活動を行なっていた石井十次が、理想的農村共同体を築くために開墾した地に建つ。静養館は明治一二年に岡山に建てられた二階建西洋館を大正二年に移築し、同一三年に現在の姿に改造・移築されたもの。当地開墾の歴史を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012079"},{"id":"00012080","register_sub_id":"101","register_pk":"211021","name":"石井記念友愛社方舟館","kana":"いしいきねんゆうあいしゃはこぶねかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡木城町大字椎木字上中原644-1","lat":32.142408,"lng":131.448186,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡、鐘楼付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"45-92","desc":"当地での開墾事業に当たり職員の集会等に利用された建物。木造二階建、建築面積八〇平方メートルで、上部に鐘楼を設ける。内部は玄関奥左を事務室、右を書庫とし、書庫の奥に和室を設ける。二階は一室とする。特異な外観で、開墾地のシンボルとして知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012080"},{"id":"00005527","register_sub_id":"101","register_pk":"106515","name":"旧外山医院","kana":"きゅうとやまいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-9-1","lat":31.5835045,"lng":131.402679,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0036","desc":"北西の角地に建ち，桁行５間半，梁間４間の規模で，木造２階建，寄棟造，桟瓦葺とし，外壁をモルタル塗とし，現在は外側に鉄板を張る。１，２階に縦長窓を並べ，北側に玄関をとり，１階を全て洋室とし，２階に和室４室をとる。市内に数少ない洋館の意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005527"},{"id":"00012855","register_sub_id":"101","register_pk":"367758","name":"服部植物研究所","kana":"はっとりしょくぶつけんきゅうしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"宮崎県","address":"宮崎県日南市飫肥六丁目3888","lat":31.62894278,"lng":131.35507583,"geo_status":"db","era":"昭和20年代／昭和50年代移築","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積108㎡","structure_material":"木造2階一部平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"45 － 105","desc":"飫肥旧城下の本町通りに北面して建つ。東の東西棟平屋建の洋館と西の南北棟二階建の和館からなる。寄棟造桟瓦葺、外壁はドイツ壁。洋館は板敷で格天井の一空間とし、和館二階に畳敷の個室を配する。町並みの整備が進んだ本町通りのランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012855"},{"id":"00014443","register_sub_id":"101","register_pk":"511432","name":"服部植物研究所研究・標本棟","kana":"はっとりしょくぶつけんきゅうしょけんきゅうひょうほんとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"宮崎県","address":"宮崎県日南市飫肥六丁目3888","lat":31.62491389,"lng":131.35509444,"geo_status":"db","era":"昭和29年頃／同42年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"45 - 0113","desc":"飫肥城下の本町通りに面する敷地奥に北面して建つ。木造総二階建で、１・２階を貫く柱形に戸袋を収め、垂直性を強調した簡素な外観。標本を保管する２階は北面以外の開口部を狭め、日差しを抑える。世界的に著名なコケ専門研究所の創設時から残る研究施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014443"},{"id":"00013773","register_sub_id":"101","register_pk":"504981","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県西之表市西町7105","lat":30.73356278,"lng":130.99585972,"geo_status":"db","era":"天保11年(1840)／大正後期増築","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積242㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"46 － 123","desc":"西之表市の中心部に建つ。近世の建築とみられる土間及び床上部二列四室の正面に続き間座敷、西に医院部分を増築した。主体部は切妻造桟瓦葺。増築部は赤土の壁に縁側の天井を曲面とするなど数寄屋風の造作をみせる。伝統家屋に近代和風の要素を加味した住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013773"},{"id":"00007150","register_sub_id":"101","register_pk":"108132","name":"大崎公民館（旧大崎報公義會舘）本館","kana":"おおさきこうみんかん（きゅうおおさきほうこうぎかいかん）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6078-2他","lat":31.42587762,"lng":130.29258878,"geo_status":"db","era":"明治末期／大正末期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"石造及び鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積309㎡","structure_material":"石造及び鉄筋コンクリート造平屋一部2階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0067","desc":"明治末期の平屋建石造会堂の前面に鉄筋コンクリート造２階建を増築し、桁行２８ｍ梁間１０ｍ規模とする。会堂演台まわりはイオニア式の柱や偏平アーチで飾られ、増築部は柱形頂部や玄関ポーチの縁取、正面の飾りなど独特で特異な意匠が随所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007150"},{"id":"00007151","register_sub_id":"101","register_pk":"108133","name":"大崎公民館（旧大崎報公義會舘）門及び石塀","kana":"おおさきこうみんかん（きゅうおおさきほうこうぎかいかん）もんおよびいしべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6078-2他","lat":31.42597588,"lng":130.2925969,"geo_status":"db","era":"明治末期・大正末期／昭和63移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"門 コンクリート造門柱2基、間口3.5m 塀 石造、延長66m","structure_material":"門 コンクリート造門柱2基","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0068","desc":"石塀は、石造会堂と同時期築造の石積３段の敷地外周塀で、北辺はほぼ全長の４６ｍ、南辺は道路寄り２０ｍを残す。門は、増築部と同時期築造のコンクリート造門柱で、高さ２．１ｍ規模とし、正・側面に幾何学的なイオニア式風柱頭飾りを付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007151"},{"id":"00007148","register_sub_id":"101","register_pk":"108130","name":"鹿児島県立博物館（旧鹿児島県立図書館）","kana":"かごしまけんりつはくぶつかん（きゅうかごしまけんりつとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市城山町1-1","lat":31.59399075,"lng":130.55269759,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積671㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0065","desc":"照国神社前交差点の角地に建つ。鉄筋コンクリート造３階建塔屋付で、鹿児島県建築課の設計による。担当は地元出身の岩下松雄。丸くした隅部に正面玄関を配し、階段室や塔屋に曲面を用いてダイナミックな構成とするなどに岩下松雄の作風がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007148"},{"id":"00001024","register_sub_id":"101","register_pk":"102014","name":"鹿児島県立博物館考古資料館","kana":"かごしまけんりつはくぶつかんこうこしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市城山町1-1","lat":31.59444945,"lng":130.55207783,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"石造２階建，建築面積337㎡","structure_material":"石造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"46 － 0001","desc":"興業館として建設され，鹿児島県の産業振興に大きな役割を果たした。石造アーチ橋の文化圏にある鹿児島ならではの石造建築で，洋風を基調としながら，随所に和風モチーフの細部を混在させた特異な建造物として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001024"},{"id":"00005070","register_sub_id":"101","register_pk":"106060","name":"鹿児島市中央公民館","kana":"かごしましちゅうおうこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町","lat":31.595329,"lng":130.554459,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1126㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"46 － 0020","desc":"建物周囲にドライエリアを設け，ラーメン構造のＲＣ造，地下１階地上３階建とする。正面立面及び平面をほぼ左右対称とし，玄関両脇に階段室塔屋を配し，その間に４本のピラスター，イスラム風尖頭アーチの窓を設置するなど，中央重視の特徴ある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005070"},{"id":"00002871","register_sub_id":"101","register_pk":"103861","name":"加治木町立図書館（旧郷土館陳列館）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんちんれつかん）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.74116408,"lng":130.66403922,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0012","desc":"木造平屋建。旧町役場が移転した跡地に郷土館として建設された。当初はコの字型平面で，正面には２重に破風を連ねた玄関を突出させ，全体を洋風の意匠でまとめている。内部は１室とし現在では図書館として活用されている。洋風展示館建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002871"},{"id":"00002872","register_sub_id":"101","register_pk":"103862","name":"加治木町立図書館（旧郷土館日本館）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんにほんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.741009,"lng":130.663956,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0013","desc":"旧郷土館陳列館の南西側に接して建つ。内部は１２畳，６畳，６畳の３室を南北に並べ，東西南の三方に縁を廻らす。東面には玄関を設け，屋根も三方に庇を設けている。内部・外部ともに全体を和風の意匠でまとめており，洋風の陳列館と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002872"},{"id":"00002873","register_sub_id":"101","register_pk":"103863","name":"加治木町立図書館（旧郷土館付属石造倉庫）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんふぞくせきぞうそうこ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.74122294,"lng":130.66417235,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造2階建、瓦葺、建築面積26㎡","structure_material":"石造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0014","desc":"旧郷土館陳列館の北東に建つ桁行５．９ｍ，梁間４．０ｍの小規模な石造倉庫。加治木石と呼ばれる地元産の凝灰岩を用い，屋根は切妻造，桟瓦葺で，南面に庇をかけて出入口を置く。腰部２段分は石材表面を平滑に仕上げ，金属製の換気口を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002873"},{"id":"00007819","register_sub_id":"101","register_pk":"108800","name":"旧鯵坂医院","kana":"きゅうあじさかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田18278","lat":31.4130529,"lng":130.31817822,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"46-0082","desc":"旧道西側の敷地中央に位置する。木造平屋建桟瓦葺、建築面積１６０㎡。東西棟の切妻造の主棟に、東・西に落棟、北に寄棟造、南に下屋を付け、変化に富む屋根を構成する。外壁は下見板張で、軒には軒持送りを付ける。用水路や石垣が残る地域にたつ洋風医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007819"},{"id":"00006471","register_sub_id":"101","register_pk":"107454","name":"旧黒木回春堂医院","kana":"きゅうくろきかいしゅんどういいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県日置市吹上町永吉14307","lat":31.56110869,"lng":130.35245594,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"46 － 0047","desc":"通り沿いに建つ木造平屋建。建築面積５２㎡、桟瓦葺で、両妻を半切妻とする。外壁は、内法間を下見板張として周囲に縦長の上げ下げ窓を配し、その上下は竪板張とする。玄関の欄間や軒下の持送りを洋風意匠で瀟洒に飾る、白色の外観が印象的な医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006471"},{"id":"00013775","register_sub_id":"101","register_pk":"505343","name":"當山紀念館","kana":"とうやまきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"沖縄県","address":"沖縄県国頭郡金武町字金武4","lat":26.4564,"lng":127.92624167,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、陸屋根、建築面積96㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"47 － 88","desc":"金武町の中心部に位置。鉄筋コンクリート造平屋建で屋根は陸屋根。南北一五メートル、東西六・四メートルで南端に玄関ポーチを付け、矩形の窓を並べる。内部は一室である。玄関ポーチのアーチや北端の八角形の窓以外は装飾要素を持たない平明な意匠の記念館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013775"},{"id":"00006672","register_sub_id":"101","register_pk":"107655","name":"弐六荘","kana":"にろくそう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港33","lat":25.95439912,"lng":131.28691763,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積243㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"47 － 0060","desc":"燐鉱採掘事業において宿泊や娯楽等に使われた。北面して建ち、東に切妻造妻入、西に入母屋造妻入を並行に設け、その間を繋ぐ工字型平面を基本に、突出が多く複雑な屋根構成になる。正面はガラス戸をたて開放的であり、屋根勾配が緩く、穏やかな佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006672"},{"id":"00010087","register_sub_id":"101","register_pk":"196234","name":"美里村屋","kana":"んざとぅむらやー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県沖縄市美里3-22-1","lat":26.34621113,"lng":127.81433557,"geo_status":"db","era":"昭和29／昭和49改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、164㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"47 － 0082","desc":"通り沿いの敷地に南面して建ち、木造平屋建、入母屋造瓦葺である。内部は広い一室の集会所周囲に廊下を廻らし、西面にトコを構える。西端に土間、東端に台所を附属する。開放的な平面で、前面の軒を雨端柱で支えるなど地方的特色を備えた、もと公民館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010087"}];
